function wireManagedOptionSelect(id,key,label,apply){const select=document.getElementById(id);if(!select)return;select.onchange=async()=>{const value=select.value;if(value==='__ADD_NEW__'){const added=prompt('Add new '+label+' option:')?.trim();if(!added){renderContractStep();return}try{const saved=await mutateMasterOption(key,'add',added);apply(saved);renderContractStep()}catch(e){alert(e.message);renderContractStep()}return}if(value==='__MANAGE__'){openOptionManager(key,label,()=>renderContractStep());renderContractStep();return}apply(value)}}
const masterValues=type=>(Array.isArray(MASTER_DATA[type])?MASTER_DATA[type]:[]).map(row=>Array.isArray(row?.values)?row.values:[]);
const productMasters=()=>masterValues('products').filter(v=>v[1]);
const currentCropYear=()=>String(masterValues('product_settings')[0]?.[0]||'2025/2026').trim();
const cleanRiceType=v=>{const raw=String(v?.[2]||'').trim(),clean=raw.replace(/\s+\d+(?:\.\d+)?%\s*(?:MAX\s*)?BROKEN\b/i,'').trim();return clean||(/\d+(?:\.\d+)?%\s*(?:MAX\s*)?BROKEN/i.test(raw)?'White Rice':raw)};
const cleanBroken=v=>{const raw=String(v?.[7]||'').trim(),match=raw.match(/[\d.]+\s*%/);return match?match[0].replace(/\s+/g,''):raw.replace(/\s*max\b/i,'').trim()};
