function qualityList(value){const parts=String(value||'').split(/\s*;\s*/).map(x=>x.trim()).filter(Boolean);if(parts.length<2)return parts[0]||'';return parts.slice(0,-1).join(', ')+' and '+parts.at(-1)}
function qualityDescription(c){const identity=['PAKISTAN LONG GRAIN',c.variety,c.riceType].filter(Boolean).join(' '),parts=[identity,c.brokenText&&c.brokenText+' BROKEN',qualityList(c.finish),c.cropYear&&'NEW CROP '+c.cropYear,c.standardBasis||'AS PER ORIGIN STANDARD'];return parts.filter(Boolean).join(', ').toUpperCase()+'.'}
function applyProductMaster(c,identity){const v=productMasters().find(row=>productIdentityCode(row)===identity||productLabel(row)===identity);if(!v){c.product=identity;return}c.productIdentityCode=productIdentityCode(v);c.variety=String(v[1]||'').trim();c.riceType=cleanRiceType(v);c.brokenText=cleanBroken(v);c.broken=num(String(c.brokenText).match(/[\d.]+/)?.[0]||0);c.finish=String(v[17]||'').trim();c.cropYear=currentCropYear();c.standardBasis=/contract specific|buyer specific|customer specific/i.test(String(v[5]||''))?'AS PER SPECIFICATIONS BELOW':'AS PER ORIGIN STANDARD';c.product=[c.variety,c.riceType].filter(Boolean).join(' ');c.additionalQuality=String(v[18]||DEFAULT_QUALITY).trim();c.quality=qualityDescription(c);c.specMode='Contract Specific';const fields=[['Average Grain Length',v[6]],['Moisture',v[8]],['Damaged / Shriveled / Yellow',v[9]],['Chalky / Immature',v[10]],['Contrasting / Other Varieties',v[11]],['Foreign Grains',v[12]],['Foreign Matter',v[13]],['Paddy',v[14]],['Red Kernels / Red Rice',v[15]],['Under-milled / Red-striped',v[16]]];let custom=[];try{custom=JSON.parse(String(v[20]||'[]'))}catch{}c.specRows=[...fields.filter(x=>x[1]).map(([name,value])=>({name,value})),...(Array.isArray(custom)?custom.map(x=>({name:String(x.name||''),value:String(x.limit||'')})).filter(x=>x.name||x.value):[])]}
function seed(){return {version:'clean-v3',customers:[],suppliers:[],fi:[],contracts:[],shipments:[],accountsReceipts:[],millSync:{newExportBags:[],productionInstructions:[],exportLoading:[]},audits:[],alerts:[],settings:{}}}
function normalize(x){x=x&&typeof x==='object'?x:seed();x.version='clean-v3';for(const k of ['customers','suppliers','fi','contracts','shipments','accountsReceipts','audits','alerts'])x[k]=Array.isArray(x[k])?x[k]:[];x.millSync=x.millSync||{};for(const k of ['newExportBags','productionInstructions','exportLoading'])x.millSync[k]=Array.isArray(x.millSync[k])?x.millSync[k]:[];return x}
