async function uploadDocument(file,category,s){if(!file)throw new Error('Select a file.');if(file.size>10*1024*1024)throw new Error('Document must be 10 MB or smaller.');const access=window.TT_MODULE_ACCESS||{};if(access.csrf){const body=new FormData();body.append('csrf',access.csrf);body.append('category',category);body.append('contractRef',s.contractRef||'');body.append('lotId',s.lotId||'');body.append('file',file);const response=await fetch('api/export_documents.php',{method:'POST',credentials:'same-origin',body});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Upload failed.');return result.document}const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=()=>reject(new Error('File could not be read.'));r.readAsDataURL(file)});return{id:uid('DOC'),name:file.name,mime:file.type,size:file.size,dataUrl,uploadedAt:new Date().toISOString(),category}}
