function lcSpecificTerms(c){const days=num(c?.usanceDays)||90,out=['PARTIAL SHIPMENT TO BE ALLOWED IN THE L/C.','TRANS-SHIPMENT TO BE ALLOWED IN THE L/C.','THE L/C MUST BE WORKABLE AND IRREVOCABLE AND ISSUED BY A FIRST-CLASS BANK ACCEPTABLE TO THE SELLER.'];if(c?.paymentCode==='LC_USANCE')out.push(`USANCE L/C TO BE PAYABLE ${days} DAYS FROM B/L DATE; NEGOTIATION AND/OR ACCEPTANCE THROUGH SELLER’S NOMINATED OR ACCEPTABLE BANK. DEFERRED PAYMENT L/C IS NOT ACCEPTABLE.`);out.push(`THE L/C MUST BE RECEIVED BY AUTHENTICATED SWIFT LATEST BY ${fmt(c?.paymentDeadline)}. THEREAFTER SUBJECT TO SELLER’S RE-CONFIRMATION.`,'THE L/C MUST BE AVAILABLE FOR NEGOTIATION THROUGH THE SELLER’S NOMINATED OR ACCEPTABLE BANK.','IF THE L/C IS ISSUED BY A BANK WHICH IS NOT A FIRST-CLASS BANK ACCEPTABLE TO THE SELLER, THE L/C MUST BE CONFIRMED BY A FIRST-CLASS BANK ACCEPTABLE TO THE SELLER.','ALL BANK CHARGES OUTSIDE PAKISTAN SHALL BE FOR BUYER’S ACCOUNT. CONFIRMATION CHARGES, IF ANY, SHALL ALSO BE FOR BUYER’S ACCOUNT.','ANY DOCUMENTARY DISCREPANCY ACCEPTED BY BUYER SHALL BE PROMPTLY WAIVED / ACCEPTED THROUGH THE ISSUING BANK TO PERMIT NEGOTIATION.');return out}
function exportMasterTerms(c){const payment=String(c?.paymentCode||'').toUpperCase(),groups=new Set(['BASE',payment,payment.startsWith('LC_')?'LC':'',payment.startsWith('ADV_')||payment==='ADV100'?'ADVANCE':'',payment.startsWith('CAD')?'CAD':''].filter(Boolean));return masterValues('export_terms').filter(v=>String(v[2]||'Active').toLowerCase()!=='inactive'&&groups.has(String(v[0]||'BASE').toUpperCase())).map(v=>String(v[1]||'').trim()).filter(Boolean)}
function effectiveTerms(c){const shared=exportMasterTerms(c),out=[...(shared.length?shared:DEFAULT_TERMS),...(c.terms||[])];if(c.incoterm==='FOB')out.push('Load Port Terminal Handling Charges (THC), if applicable, shall be for Buyer’s account.');out.push(`Insurance shall be for ${c.insurance==="Seller's Account"?'Seller’s':'Buyer’s'} account.`);if(c.inspection&&!['None','No'].includes(c.inspection))out.push(`Inspection by ${c.inspection} at Seller’s cost.`);if(String(c.paymentCode).startsWith('LC_'))out.push(...lcSpecificTerms(c));else out.push('Partial shipment allowed.');if(c.seller==='TG')out.push('Third-party documents are acceptable except Commercial Invoice and documents specifically required to be issued by the Seller.');return[...new Set(out.map(x=>String(x).trim()).filter(Boolean))]}
