function millLocations(){let rows=[];try{rows=JSON.parse(localStorage.getItem(MILL_STORE)||'[]')}catch{}if(!Array.isArray(rows))rows=[];for(const v of masterValues('mills')){const name=String(v[0]||'').trim();if(name&&!rows.some(x=>String(x.name||'').trim().toLowerCase()===name.toLowerCase()))rows.push({id:v[1]||name,name,type:v[2]||'Master'})}if(!rows.some(x=>String(x.name||'').trim().toLowerCase()==='tti rice mills'))rows.unshift({id:1,name:'TTI Rice Mills',type:'Own / Default'});return rows}
function registerMillLocation(name,type){name=String(name||'').trim();if(!name)return;const rows=millLocations();if(!rows.some(x=>String(x.name||'').trim().toLowerCase()===name.toLowerCase())){rows.push({id:Date.now(),name,type:type==='TTI'?'Own / Default':'External Milling / Processing'});localStorage.setItem(MILL_STORE,JSON.stringify(rows))}const access=window.TT_MODULE_ACCESS||{};if(access.csrf)fetch('api/location-master.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:access.csrf,name,type,source:'Exports loading instructions'})}).catch(()=>{})}

function mount(){upgradeState();document.getElementById('app').innerHTML=`<div class="shell"><div class="topbar"><div><h1>TRANSTRADE EXPORTS</h1><div class="sub">Clean operational build · shared live data</div></div><span class="status green">READY</span><div class="spacer"></div><button class="masterTopButton" id="masterTop" title="Master Data" aria-label="Master Data"><b>M</b></button><span class="topDate">${new Date().toLocaleDateString(undefined,{weekday:'short',day:'2-digit',month:'short',year:'numeric'})}</span><span id="saveBadge" class="tiny"></span><button class="btn small" id="logoutTop" title="Log out" aria-label="Log out">⏻</button></div><div class="nav" id="nav"></div><main id="main"></main></div>`;document.getElementById('masterTop').onclick=()=>window.TT_OPEN_EXPORT_MASTER_DATA?.();document.getElementById('logoutTop').onclick=()=>location.href='logout.php';setTimeout(()=>{if(document.getElementById('ttUserBar'))document.getElementById('logoutTop').style.display='none'},0);render()}
