function renderContracts(){document.getElementById('main').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Sales Contracts</h2><div class="metaText">Pre-acceptance amendments remain direct. Accepted contracts require a controlled reopen, addendum, or cancellation reason.</div></div><div class="spacer"></div><button class="btn green" id="newContract">+ NEW SALES CONTRACT</button></div><div class="tableWrap"><table class="table"><thead><tr><th>Ref</th><th>Date</th><th>Buyer</th><th>Product</th><th>Qty MT</th><th>Payment</th><th>Status</th><th>Controlled Actions</th></tr></thead><tbody>${state.contracts.map(c=>`<tr><td>${esc(c.ref)}</td><td>${fmt(c.date)}</td><td>${esc(customer(c.customerId)?.name||c.customer||'')}</td><td>${esc(c.product)}</td><td>${num(c.qty).toFixed(3)}</td><td>${esc(PAYMENT_LABELS[c.paymentCode]||c.paymentText||'')}</td><td>${esc(c.status)}</td><td><div class="rowActions"><button class="btn small soft" data-contract="${esc(c.id)}">Open / Amend</button>${c.received?`<button class="btn small amber" data-reopen="${esc(c.id)}">${c.reopenAuthorized?'Reopen Approved':'Request Reopen'}</button><button class="btn small green" data-addendum="${esc(c.id)}">Addendum</button>`:''}${!state.shipments.some(s=>s.kind!=='lot'&&s.contractRef===c.ref)?`<button class="btn small green" data-start-shipment="${esc(c.id)}">Start Shipment</button>`:''}<button class="btn small red" data-cancel-contract="${esc(c.id)}" ${c.status==='Cancelled'?'disabled':''}>Cancel</button></div></td></tr>`).join('')}</tbody></table></div></div>`;document.getElementById('newContract').onclick=()=>startContract();document.querySelectorAll('[data-contract]').forEach(b=>b.onclick=()=>openContract(b.dataset.contract));document.querySelectorAll('[data-reopen]').forEach(b=>b.onclick=()=>requestContractReopen(b.dataset.reopen));document.querySelectorAll('[data-addendum]').forEach(b=>b.onclick=()=>createAddendum(b.dataset.addendum));document.querySelectorAll('[data-start-shipment]').forEach(b=>b.onclick=()=>startShipmentFromContract(b.dataset.startShipment));document.querySelectorAll('[data-cancel-contract]').forEach(b=>b.onclick=()=>cancelContract(b.dataset.cancelContract))}
function restartShipmentData(contractId){const c=state.contracts.find(x=>x.id===contractId);if(!c)return null;const existing=state.shipments.find(s=>s.kind!=='lot'&&s.contractRef===c.ref);if(existing)return existing;const p=makeShipment(c);state.shipments.push(p);c.status=c.received?'Contract Received':'Awaiting Customer Confirmation';return p}
function startShipmentFromContract(contractId){const p=restartShipmentData(contractId);if(!p)return;currentShipmentId=p.id;audit('Shipment','Started from retained Sales Contract',p.contractRef);view='shipments';activeWorkspace='';renderShipmentWorkspace()}
function nextContractRef(custId,seller='TTI'){const cu=customer(custId)||{code:'CUS',nextSeq:1};return `${seller}/${cu.code||'CUS'}/${String(cu.nextSeq||1).padStart(2,'0')}`}
function newContractShape(){return{id:uid('CT'),ref:'',seller:'TTI',customerId:'',date:'',product:'',productIdentityCode:'',variety:'',riceType:'',broken:0,brokenText:'',finish:'',cropYear:currentCropYear(),standardBasis:'AS PER ORIGIN STANDARD',quality:'',additionalQuality:DEFAULT_QUALITY,specMode:'Contract Specific',specRows:[],containers:0,weightPer:0,qty:0,tolerance:0,pol:'',shipmentDate:'',podPort:'',podCountry:'',destPort:'',destPortManual:false,packingUnit:'',packings:[],currency:'',incoterm:'',inspection:'',insurance:'',paymentCode:'',advancePct:0,usanceDays:0,customPayment:'',paymentText:'',signedDeadline:'',paymentDeadline:'',docs:[],documentsPresented:[],terms:[],showAllPrices:false,status:'Draft',issued:false,received:false,versions:[],sourceDocument:null}}
function reusableContractTemplate(customerId){return[...state.contracts].reverse().find(c=>c.customerId===customerId&&c.status!=='Cancelled')||null}
function applyBuyerTemplate(customerId){const previous=reusableContractTemplate(customerId),date=TODAY(),next=Object.assign(newContractShape(),{id:contractDraft.id,seller:previous?.seller||'TTI',customerId,date,tolerance:5,pol:'Karachi Port, Pakistan or Port Qasim, Pakistan',packingUnit:customer(customerId)?.packingDefault||'KG',currency:'USD',incoterm:'FOB',inspection:'No',insurance:"Buyer's Account",paymentCode:'ADV_SCAN',advancePct:20,usanceDays:90});if(previous){const reusable=['seller','product','productIdentityCode','variety','riceType','broken','brokenText','finish','standardBasis','additionalQuality','specMode','specRows','containers','weightPer','qty','tolerance','pol','podPort','podCountry','destPort','destPortManual','packingUnit','packings','currency','incoterm','inspection','insurance','paymentCode','advancePct','usanceDays','customPayment','docs','documentsPresented','terms','showAllPrices'];for(const key of reusable)if(previous[key]!==undefined)next[key]=structuredClone(previous[key]);next.cropYear=currentCropYear();if(next.productIdentityCode)applyProductMaster(next,next.productIdentityCode)}next.ref=nextContractRef(customerId,next.seller);next.date=date;next.shipmentDate='';next.signedDeadline=addDays(date,2);next.paymentDeadline=addBankDays(date,4);if(!next.docs.length)next.docs=defaultDocsFor(next);contractDraft=next;activePackingIndex=-1;packingDraft=null}
function startContract(){contractDraft=newContractShape();contractStep=1;activePackingIndex=-1;packingDraft=null;view='contracts';renderContractEditor()}
function openContract(id){const c=state.contracts.find(x=>x.id===id);if(!c)return;if(c.status==='Cancelled')return alert('A cancelled contract is read-only. Its history remains available.');if(c.received&&contractHasDownstream(c)&&!c.reopenAuthorized)return alert('This accepted contract has downstream work. Request a controlled Director reopen or create an addendum.');contractDraft=structuredClone(c);contractStep=1;activePackingIndex=-1;packingDraft=null;renderContractEditor()}
function requestContractReopen(id){const c=state.contracts.find(x=>x.id===id);if(!c)return;const reason=requiredReason('Reason for reopening this accepted contract:');if(!reason)return;c.reopenRequests=Array.isArray(c.reopenRequests)?c.reopenRequests:[];const canApprove=/director|super admin/i.test(currentRole());c.reopenRequests.push({id:uid('CRR'),reason,requestedAt:new Date().toISOString(),requestedBy:currentUser(),status:canApprove?'Approved':'Pending Director Approval',approvedAt:canApprove?new Date().toISOString():'',approvedBy:canApprove?currentUser():''});c.reopenAuthorized=canApprove;audit('Sales Contract',canApprove?'Director reopen approved':'Director reopen requested',`${c.ref} · ${reason}`);renderContracts()}
function createAddendum(id){const c=state.contracts.find(x=>x.id===id);if(!c)return;openModal('Contract Addendum — '+c.ref,`<div class="grid2"><div class="field"><label>Addendum Reference</label><input id="adRef" value="${esc(c.ref)}-ADD-${String((c.addenda||[]).length+1).padStart(2,'0')}"></div><div class="field"><label>Effective Date</label><input id="adDate" type="date" value="${TODAY()}"></div><div class="field full"><label>Changes / Agreed Terms</label><textarea id="adText"></textarea></div><div class="field full"><label>Reason</label><textarea id="adReason"></textarea></div></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveAddendum">SAVE & PRINT ADDENDUM</button>`);document.getElementById('saveAddendum').onclick=()=>{const text=adText.value.trim(),reason=adReason.value.trim();if(!adRef.value.trim()||!text||!reason)return alert('Reference, changes and reason are mandatory.');const a={id:uid('ADD'),reference:adRef.value.trim(),date:adDate.value,text,reason,createdAt:new Date().toISOString(),createdBy:currentUser()};c.addenda=Array.isArray(c.addenda)?c.addenda:[];c.addenda.push(a);audit('Sales Contract','Addendum created',`${c.ref} · ${a.reference} · ${reason}`);closeModal();printShipmentDoc('CONTRACT ADDENDUM',pageDoc(c,'CONTRACT ADDENDUM',`<div class="docRefGrid"><div class="docRefBox"><b>Contract</b>${esc(c.ref)}</div><div class="docRefBox"><b>Addendum</b>${esc(a.reference)} · ${fmt(a.date)}</div></div><h3 class="docSection">AGREED CHANGES</h3><p>${esc(a.text).replace(/\n/g,'<br>')}</p><h3 class="docSection">REASON / RECORD</h3><p>${esc(a.reason)}</p>${signature(c)}`),c.seller);renderContracts()}}
function cancelContract(id){const c=state.contracts.find(x=>x.id===id);if(!c)return;const reason=requiredReason('Mandatory reason for cancelling '+c.ref+':');if(!reason)return;snapshot(c,reason,'Cancelled');c.status='Cancelled';c.cancelled=true;c.cancelReason=reason;c.cancelledAt=new Date().toISOString();c.cancelledBy=currentUser();for(const s of state.shipments.filter(x=>x.contractRef===c.ref&&!x.completed)){s.cancelled=true;s.cancelReason=reason;s.status='Cancelled'}audit('Sales Contract','Cancelled',`${c.ref} · ${reason}`);renderContracts()}
async function deleteShipmentDocuments(contractRef){const access=window.TT_MODULE_ACCESS||{};if(!access.csrf)return{deleted:0};const body=new FormData();body.append('csrf',access.csrf);body.append('action','delete-shipment');body.append('contractRef',contractRef);const response=await fetch('api/export_documents.php',{method:'POST',credentials:'same-origin',body});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Shipment documents could not be deleted.');return result}
function deleteShipmentData(processId){const p=state.shipments.find(x=>x.id===processId&&x.kind!=='lot');if(!p)return{shipmentCount:0,lotCount:0,contractRef:''};const doomed=[p,...lotsFor(p)],shipmentIds=new Set(doomed.map(x=>String(x.id||''))),ref=p.contractRef,matches=row=>row&&((row.contractRef&&String(row.contractRef)===ref)||(row._ttContractRef&&String(row._ttContractRef)===ref)||(row.shipmentId&&shipmentIds.has(String(row.shipmentId)))||(row._ttShipmentId&&shipmentIds.has(String(row._ttShipmentId))));const readRows=key=>{try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v:[]}catch{return[]}},writePruned=(key,predicate)=>{if(localStorage.getItem(key)===null)return;const rows=readRows(key),kept=rows.filter(x=>!predicate(x));if(kept.length!==rows.length)localStorage.setItem(key,JSON.stringify(kept))};const exRows=readRows('tt35exmill'),exIds=new Set(exRows.filter(matches).map(x=>String(x.id||'')));for(const key of ['tt30bags','tt30prodinst','tt30ship','tt32exportsync','tt35exmill','tt39bridgequarantine'])writePruned(key,matches);writePruned('tt35exload',row=>matches(row)||(row?.sodaId&&exIds.has(String(row.sodaId))));state.shipments=state.shipments.filter(x=>!shipmentIds.has(String(x.id||'')));for(const key of ['newExportBags','productionInstructions','exportLoading'])state.millSync[key]=(state.millSync[key]||[]).filter(x=>!matches(x));for(const fi of state.fi||[])fi.allocations=(fi.allocations||[]).filter(x=>!matches(x));state.alerts=(state.alerts||[]).filter(x=>!matches(x));if(shipmentIds.has(String(currentShipmentId||'')))currentShipmentId='';const c=contractByRef(ref);if(c){c.status=c.received?'Contract Received':'Draft';c.cancelled=false;delete c.cancelReason;delete c.cancelledAt;delete c.cancelledBy}return{shipmentCount:doomed.length,lotCount:doomed.filter(x=>x.kind==='lot').length,contractRef:ref}}
function confirmShipmentDelete(processId){const p=state.shipments.find(x=>x.id===processId&&x.kind!=='lot');if(!p)return renderHome();view='home';renderNav();document.getElementById('main').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Are you sure you want to delete this shipment?</h2><div class="metaText">${esc(p.contractRef)} · ${esc(p.buyer||'')}</div></div></div><div class="notice warn" style="margin-top:14px"><b>This cannot be undone.</b> The shipment process, all its lots and uploaded documents, and linked Milling instructions/loading data will be deleted. The Sales Contract, customer/master records, Accounts data and audit history will remain.</div><div id="shipmentDeleteError" class="notice bad" style="display:none;margin-top:12px"></div><div class="toolbar" style="margin-top:16px"><div class="spacer"></div><button class="btn" id="keepShipment">No — Keep Shipment</button><button class="btn red" id="deleteShipmentYes">Yes — Delete Shipment</button></div></div>`;document.getElementById('keepShipment').onclick=renderHome;document.getElementById('deleteShipmentYes').onclick=async()=>{const button=document.getElementById('deleteShipmentYes'),error=document.getElementById('shipmentDeleteError');button.disabled=true;button.textContent='Deleting…';try{await deleteShipmentDocuments(p.contractRef)}catch(e){error.textContent=e.message||'Shipment documents could not be deleted. Nothing was changed.';error.style.display='block';button.disabled=false;button.textContent='Yes — Delete Shipment';return}const result=deleteShipmentData(processId);audit('Shipment','Permanently deleted after confirmation',result.contractRef+' · '+result.shipmentCount+' shipment record(s) · '+result.lotCount+' lot(s)');window.TT_SHARED_SYNC?.bridge?.();renderHome()}}
function priceComponents(p,c=contractDraft){const freight=num(p.freight),insurance=c?.incoterm==='CIF'?num(p.insurance):0,legacy=num(p.price)+(c?.incoterm==='FOB'?0:freight)+(c?.incoterm==='CIF'?insurance:0),finalRate=num(p.contractRate)||legacy;return{finalRate,freight,insurance,fob:Math.max(0,finalRate-freight-insurance)}}
function unitRate(p,c=contractDraft){return priceComponents(p,c).finalRate}
function contractValue(){return contractDraft.packings.reduce((a,p)=>a+num(p.containers)*num(contractDraft.weightPer)*unitRate(p,contractDraft),0)}
function syncQty(){contractDraft.qty=num(contractDraft.containers)*num(contractDraft.weightPer);contractDraft.packings.forEach(p=>p.weightPer=num(contractDraft.weightPer))}
function paymentText(c=contractDraft){if(c.paymentCode==='LC_SIGHT')return 'BY A WORKABLE AND IRREVOCABLE 100% L/C AT SIGHT FROM A FIRST-CLASS BANK ACCEPTABLE TO THE SELLER, AVAILABLE FOR NEGOTIATION THROUGH THE SELLER’S NOMINATED / ACCEPTABLE BANK.';if(c.paymentCode==='LC_USANCE')return `BY IRREVOCABLE USANCE L/C PAYABLE ${num(c.usanceDays)||90} DAYS FROM B/L DATE, WITH NEGOTIATION AND/OR ACCEPTANCE THROUGH THE SELLER’S NOMINATED / ACCEPTABLE BANK.`;if(c.paymentCode==='CUSTOM')return c.customPayment||'';if(c.paymentCode==='ADV100')return '100% ADVANCE PAYMENT.';if(c.paymentCode==='CAD100')return '100% CASH AGAINST DOCUMENTS (CAD).';if(c.paymentCode==='ADV_CAD')return `${num(c.advancePct)}% ADVANCE + BALANCE CASH AGAINST DOCUMENTS (CAD).`;return `${num(c.advancePct)}% ADVANCE + BALANCE AGAINST SCAN COPIES.`}
function renderContractEditorLegacy(){view='contracts';renderNav();document.getElementById('main').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Sales Contract</h2><div class="metaText">${esc(contractDraft.ref)} · ${esc(contractDraft.status)}</div></div><div class="spacer"></div>${contractDraft.customerId?'':'<button class="btn soft" id="uploadContractInside">UPLOAD CUSTOMER CONTRACT</button>'}<button class="btn" id="closeContract">Close</button></div><div class="steps">${['Buyer & Reference','Product','Quantity & Shipment','Packing','PRICE','Payment Terms','Documents / Validity','Review'].map((x,i)=>`<div class="step ${contractStep===i+1?'active':''}" data-step="${i+1}">${i+1}. ${x}</div>`).join('')}</div><div id="contractBody"></div><div class="toolbar" style="margin-top:12px"><button class="btn" id="backStep" ${contractStep===1?'disabled':''}>← Back</button><div class="spacer"></div>${contractStep<8?'<button class="btn green" id="nextStep">Next →</button>':'<button class="btn green" id="issueContract">SAVE / PRINT</button>'}</div></div>`;renderContractStep();document.querySelectorAll('[data-step]').forEach(x=>x.onclick=()=>{contractStep=num(x.dataset.step);renderContractEditor()});document.getElementById('uploadContractInside')?.addEventListener('click',openContractUpload);document.getElementById('closeContract').onclick=()=>{contractDraft=null;renderContracts()};document.getElementById('backStep').onclick=()=>{contractStep--;renderContractEditor()};if(contractStep<8)document.getElementById('nextStep').onclick=()=>{const err=validateContractStep(contractStep);if(err)return alert(err);contractStep++;renderContractEditor()};else document.getElementById('issueContract').onclick=()=>saveContract(true)}
function renderContractStep(){const b=document.getElementById('contractBody');const c=contractDraft,cu=customer(c.customerId)||{},fallbackProducts=['IRRI-6 White Rice','IRRI-6 Parboiled Rice','C-9 White Rice','PK-386 White Rice','Super Kernel Basmati','D-98 White Rice','1121 White Rice'],products=productMasters().length?[...new Set(productMasters().map(productLabel).filter(Boolean))]:fallbackProducts;if(contractStep===1)b.innerHTML=`<div class='grid2'><div class='field full'><label>Customer</label><div class='toolbar'><div class='customerTypeahead' style='flex:1'><input id='cCustomerSearch' value='${esc(cu.name||'')}' placeholder='Type customer name — for example A, then AS' autocomplete='off' aria-autocomplete='list' aria-controls='cCustomerMatches'><div id='cCustomerMatches' class='customerMatches' role='listbox'></div></div><button class='btn small green' id='addCustomer'>+ Customer</button></div></div>${cu.id?`<div class='field'><label>Selling Entity</label><select id='cSeller'>${Object.keys(SELLERS).map(k=>`<option value='${k}' ${c.seller===k?'selected':''}>${k} — ${SELLERS[k]}</option>`).join('')}</select></div><div class='field'><label>Contract Reference</label><input id='cRef' value='${esc(c.ref)}'></div><div class='field'><label>Contract Date</label><input id='cDate' type='date' value='${c.date}'></div><div class='field full'><label>Buyer Address</label><textarea readonly>${esc(cu.address||'')}</textarea></div>`:`<div class='notice full'>Start typing the customer name. Contract fields remain empty until a customer is selected.</div>`}</div>`;else if(contractStep===2)b.innerHTML=`<div class="grid2"><div class="field"><label>Product / Variety</label><select id="cProduct"><option value="" ${!c.product?'selected':''}>Select Product</option>${products.map(x=>`<option ${c.product===x?'selected':''}>${esc(x)}</option>`).join('')}${c.product&&!products.includes(c.product)?`<option selected>${esc(c.product)}</option>`:''}</select></div><div class="field"><label>Broken / Range</label>${managedOptionSelectHTML('cBroken','product_broken','Broken',c.brokenText||'')}</div><div class="field"><label>Processing / Finish</label>${managedOptionSelectHTML('cFinish','product_finishes','Finish',c.finish||'')}</div><div class="field"><label>Specifications</label><select id="cSpecMode"><option ${c.specMode==='Pakistan Origin Standard'?'selected':''}>Pakistan Origin Standard</option><option ${c.specMode==='Contract Specific'?'selected':''}>Contract Specific</option></select></div><div class="field full"><label>Additional Quality / Specifications</label><textarea id="cQuality">${esc(c.quality||DEFAULT_QUALITY)}</textarea></div>${c.specMode==='Contract Specific'?`<div class="full" id="specRows">${specRowsHTML()}</div>`:''}</div>`;else if(contractStep===3)b.innerHTML=`<div class="grid4"><div class="field"><label>No. Containers</label><input id="cContainers" type="number" value="${c.containers||''}"></div><div class="field"><label>Weight / Container MT</label><input id="cWeightPer" type="number" step="0.001" value="${c.weightPer||''}"></div><div class="field"><label>Total Quantity MT</label><input id="cQty" readonly value="${num(c.qty).toFixed(3)}"></div><div class="field"><label>Quantity Tolerance ±%</label><input id="cTolerance" type="number" value="${c.tolerance}"></div><div class="field"><label>Latest Shipment Date</label><input id="cShipmentDate" type="date" value="${c.shipmentDate||''}"></div><div class="field"><label>Port of Loading</label><input id="cPOL" value="${esc(c.pol)}"></div><div class="field"><label>Port of Discharge</label><input id="cPOD" value="${esc(c.podPort)}"></div><div class="field"><label>Country</label><input id="cPODCountry" value="${esc(c.podCountry)}"></div><div class="field"><label>Final Place of Delivery</label><input id="cDest" value="${esc(c.destPort)}"></div></div>`;else if(contractStep===4)b.innerHTML=`<div class="toolbar"><h3>Packing</h3><div class="spacer"></div><div class="field" style="min-width:160px"><label>Packing Unit</label><select id="cPackingUnit"><option ${c.packingUnit==='KG'?'selected':''}>KG</option><option ${c.packingUnit==='LB'?'selected':''}>LB</option></select></div></div><div id="packingList">${packingListHTML()}</div>`;else if(contractStep===5)b.innerHTML=`<div class="grid4"><div class="field"><label>Currency</label>${managedOptionSelectHTML('cCurrency','currencies','Currency',c.currency||'')}</div><div class="field"><label>Incoterm</label><select id="cIncoterm">${['FOB','CFR','CIF'].map(x=>`<option ${c.incoterm===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Insurance</label><select id="cInsurance"><option ${c.insurance==="Buyer's Account"?'selected':''}>Buyer's Account</option><option ${c.insurance==="Seller's Account"?'selected':''}>Seller's Account</option></select></div><div class="field"><label>Inspection</label>${managedOptionSelectHTML('cInspection','inspection_companies','Inspection',c.inspection||'')}</div></div><div id="priceLines">${priceLinesHTML()}</div><div class="notice"><b>Total Contract Value:</b> <span id="contractValue" class="amount">${money(contractValue(),c.currency)}</span></div>`;else if(contractStep===6)b.innerHTML=`<div class="grid2"><div class="field"><label>Payment Terms</label><select id="cPayment">${Object.entries(PAYMENT_LABELS).map(([k,v])=>`<option value="${k}" ${c.paymentCode===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div id="paymentDynamic">${paymentDynamicHTML()}</div></div><div class="notice" id="paymentPreview">${esc(paymentText(c))}</div>`;else if(contractStep===7)b.innerHTML=`<div class="grid2"><div class="field"><label>Signed / Stamped Contract Latest By</label><input id="cSignedDeadline" type="date" value="${c.signedDeadline||''}"></div><div class="field"><label>${c.paymentCode.startsWith('LC_')?'L/C':'Advance / Payment'} Latest By</label><input id="cPaymentDeadline" type="date" value="${c.paymentDeadline||''}"></div><div class="field full"><label>Documents to be Presented</label>${documentsTableHTML(c)}</div><div class="field full"><label>Other Terms</label><textarea id="cTerms">${esc((c.terms||[]).join('\n'))}</textarea></div></div>`;else b.innerHTML=reviewContractHTML();wireContractStep()}
function specRowsHTML(){const rows=contractDraft.specRows.length?contractDraft.specRows:[{name:'Broken',value:`${contractDraft.broken}% MAX`},{name:'Moisture',value:''},{name:'Chalky',value:''},{name:'Damaged / Yellow',value:''}];contractDraft.specRows=rows;return `<div class="section"><div class="toolbar"><h3>Contract Specific Specifications</h3><div class="spacer"></div><button class="btn small green" id="addSpec">+ Specification</button></div>${rows.map((r,i)=>`<div class="grid2" style="margin-bottom:7px"><input data-spec-name="${i}" value="${esc(r.name)}"><div class="toolbar"><input style="flex:1" data-spec-value="${i}" value="${esc(r.value)}"><button class="btn small red" data-remove-spec="${i}">Remove</button></div></div>`).join('')}</div>`}
function blankPackingShape(){return{type:'',size:0,brand:'',tare:0,containers:0,weightPer:0,price:0,contractRate:0,freight:0,insurance:0,extraBagPct:1,masterBag:{enabled:false,bagsPerMaster:0,quantity:0,weight:0,tare:0}}}
function packingEditorHTML(){if(!packingDraft)return contractDraft.packings.length?'<div class="notice">Select a bag tab to view or update it, or add another bag type.</div>':'<div class="notice warn">No packing entered yet. Press + ADD BAG TYPE to start with a blank form.</div>';const p=packingDraft,i=activePackingIndex,master=!!p.masterBag?.enabled;return `<div class="packingInline"><div class="grid3"><div class="field"><label>BAG TYPE</label><input id="mPackType" value="${esc(p.type||'')}"></div><div class="field"><label>BAG SIZE in kgs</label><input id="mPackSize" type="number" step="0.001" value="${p.size||''}"></div><div class="field"><label>BRAND</label><input id="mPackBrand" value="${esc(p.brand||'')}"></div><div class="field"><label>TARE GRAMS</label><input id="mPackTare" type="number" value="${p.tare||''}"></div><div class="field"><label>HOW MANY CONTAINERS FOR THIS PACKING</label><input id="mPackContainers" type="number" value="${p.containers||''}"></div><div class="field"><label>CALCULATED NUMBER OF BAGS</label><input id="mCalculatedBags" readonly></div><div class="field"><label>Extra Bags (%)</label><input id="mPackExtra" type="number" step="0.1" value="${p.extraBagPct===undefined?'':p.extraBagPct}"></div><label class="masterBagToggle"><input id="mMasterEnabled" type="checkbox" ${master?'checked':''}> <b>MASTER BAG</b></label><div id="masterBagFields" class="grid3 full ${master?'':'hidden'}"><div class="field"><label>How many bags in one master bag?</label><input id="mMasterQty" type="number" value="${p.masterBag?.bagsPerMaster||''}"></div><div class="field"><label>MASTER BAG QUANTITY</label><input id="mMasterCount" readonly></div><div class="field"><label>MASTER BAG WEIGHT</label><input id="mMasterWeight" readonly></div><div class="field"><label>Master Bag Tare</label><input id="mMasterTare" type="number" value="${p.masterBag?.tare||''}"></div></div></div><div class="toolbar packingActions">${i<contractDraft.packings.length?'<button class="btn red" id="removePacking">REMOVE THIS BAG TYPE</button>':''}<div class="spacer"></div><button class="btn green" id="savePacking">SAVE BAG ${i+1}</button></div></div>`}
function packingListHTML(){const tabs=contractDraft.packings.map((p,i)=>`<button type="button" class="packingTab ${activePackingIndex===i?'active':''}" data-pack-tab="${i}"><b>BAG ${i+1}</b><span>${esc(p.brand||p.type||'Saved')}</span></button>`).join(''),newTab=packingDraft&&activePackingIndex===contractDraft.packings.length?`<button type="button" class="packingTab active" data-pack-tab="${activePackingIndex}"><b>BAG ${activePackingIndex+1}</b><span>New</span></button>`:'';return `<div class="packingTabs">${tabs}${newTab}<button type="button" class="packingTab add" id="addPacking"><b>＋</b><span>ADD BAG TYPE</span></button></div>${packingEditorHTML()}`}
