function saveContract(print){const c=structuredClone(contractDraft);for(let step=1;step<=7;step++){const err=validateContractStep(step);if(err){contractStep=step;renderContractEditor();return alert(err)}}let docRows=documentsPresented(c).filter(x=>!/^Insurance Policy \/ Certificate$/i.test(x.name));if(c.incoterm==='CIF')docRows.push({sequence:docRows.length+1,name:'Insurance Policy / Certificate',original:1,copies:0});syncDocumentSources(c,docRows);c.paymentText=paymentText(c);const duplicate=state.contracts.find(x=>x.ref.toLowerCase()===c.ref.toLowerCase()&&x.id!==c.id);if(duplicate)return alert('Contract Reference already exists.');const idx=state.contracts.findIndex(x=>x.id===c.id);if(idx>=0){const old=state.contracts[idx],oldRef=old.ref,newBuyer=customer(c.customerId)?.name||'';c.versions=[...(old.versions||[]),{at:new Date().toISOString(),snapshot:structuredClone(old)}];state.contracts[idx]=c;for(const linked of state.shipments.filter(s=>s.contractRef===oldRef)){linked.contractRef=c.ref;linked.buyer=newBuyer||linked.buyer;linked.seller=c.seller;if(linked.kind==='process'){linked.plannedQty=c.qty;linked.containers=c.containers}if(linked.bl?.notify===old.customer||linked.bl?.notify===customer(old.customerId)?.name)linked.bl.notify=newBuyer}for(const key of ['newExportBags','productionInstructions','exportLoading'])for(const row of state.millSync[key]||[])if(row.contractRef===oldRef)row.contractRef=c.ref;for(const f of state.fi)for(const a of f.allocations||[])if(a.contractRef===oldRef)a.contractRef=c.ref;audit('Sales Contract','Amended',c.ref)}else{c.issued=true;c.status='Awaiting Customer Confirmation';state.contracts.push(c);const cu=customer(c.customerId);if(cu)cu.nextSeq=num(cu.nextSeq)+1;state.shipments.push(makeShipment(c));audit('Sales Contract','Created',c.ref)}contractDraft=structuredClone(c);save();if(print){printHTML('SALES CONTRACT',salesContractPrint(c));contractDraft=null;view='home';activeWorkspace='';render()}else renderContractEditor()}
function structuralContractSignature(c){return JSON.stringify({seller:c.seller,customerId:c.customerId,product:c.product,productIdentityCode:c.productIdentityCode||'',brokenText:c.brokenText||'',finish:c.finish||'',cropYear:c.cropYear||'',qty:num(c.qty),containers:num(c.containers),packingUnit:c.packingUnit,packings:(c.packings||[]).map(p=>({type:p.type,size:num(p.size),brand:p.brand,tare:num(p.tare),containers:num(p.containers),weightPer:num(p.weightPer),masterBag:p.masterBag||{enabled:false,qty:0,tare:0}}))})}
const saveContractUnchecked=saveContract;
saveContract=function(print){const old=state.contracts.find(x=>x.id===contractDraft?.id),process=old&&state.shipments.find(s=>s.kind!=='lot'&&s.contractRef===old.ref),hasDownstream=!!process&&((process.bagOrders||[]).length||process.production?.sentToMill||lotsFor(process).length),structural=old&&structuralContractSignature(old)!==structuralContractSignature(contractDraft);if(old&&hasDownstream&&structural&&!old.reopenAuthorized)return alert('Packing, quantity, product, buyer or seller cannot be structurally amended after downstream work starts without an approved Director reopen. Use an addendum when the original contract must remain unchanged.');if(old&&old.received){const reason=requiredReason('Mandatory reason for this accepted-contract amendment:');if(!reason)return;snapshot(old,reason,'Accepted contract amended');contractDraft.lastAmendmentReason=reason;contractDraft.reopenAuthorized=false}return saveContractUnchecked(print)};

function nextBagPoNo(){const yy=new Date().getFullYear().toString().slice(-2),used=processes().flatMap(p=>[...(p.bagOrders||[]),...(p.bagOrderDraft?[p.bagOrderDraft]:[])]).map(x=>String(x.poNo||'').match(new RegExp('^PO-'+yy+'(\\d{4})$'))).filter(Boolean).map(m=>num(m[1]));return 'PO-'+yy+String((used.length?Math.max(...used):0)+1).padStart(4,'0')}
