function openSupplierModal(){openModal('Add Bag Supplier',`<div class="field"><label>Supplier Name</label><input id="newSupplierName"></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveSupplier">SAVE SUPPLIER</button>`);document.getElementById('saveSupplier').onclick=()=>{const name=document.getElementById('newSupplierName').value.trim();if(!name)return alert('Supplier name is required.');if(!state.suppliers.some(x=>x.name.toLowerCase()===name.toLowerCase()))state.suppliers.push({id:uid('SUP'),name});shipment().bagOrderDraft.supplier=name;audit('Supplier','Added from Bag Order',name);closeModal();renderShipmentWorkspace()}}
function ensureBagDraft(){const s=shipment(),c=contractByRef(s.contractRef);if(!s.bagOrderDraft){s.bagOrderDraft={poNo:nextBagPoNo(),supplier:'',deliverTo:'To Be Advised Later',requiredDate:'',lines:c.packings.map((p,i)=>{const req=bagRequired(p,c),extra=num(p.extraBagPct);return{packingIndex:i,brand:p.brand,type:p.type,size:p.size,unit:c.packingUnit,tare:p.tare,requiredBags:req,extraPct:extra,extraBags:Math.ceil(req*extra/100),totalBags:req+Math.ceil(req*extra/100),artworkName:'',artworkData:'',artworkAttached:false,approved:false,approvedAt:'',handle:'No',masterBag:structuredClone(p.masterBag||{enabled:false,qty:0,tare:0})}})}}for(const l of s.bagOrderDraft.lines){l.masterBag=l.masterBag||{enabled:false,qty:0,tare:0};l.approved=!!l.artworkAttached}return s.bagOrderDraft}
function renderBagOrder(d){const s=shipment(),po=ensureBagDraft();d.innerHTML=`<div class="section"><div class="toolbar"><div><h3>BAG ORDER</h3><div class="metaText">One PO and one form for every packing line and master bag in this shipment.</div></div><div class="spacer"></div><button class="btn soft" id="newPODraft">Reset Draft</button></div><div class="grid3"><div class="field"><label>PO Number</label><input id="boNo" value="${esc(po.poNo)}"></div><div class="field"><label>Supplier</label><select id="boSupplier"><option value="">Select Supplier</option>${state.suppliers.map(x=>`<option ${po.supplier===x.name?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="btn small green" id="addSupplier">+ Supplier</button></div><div class="field"><label>Deliver To</label><input id="boDeliver" value="${esc(po.deliverTo)}"></div><div class="field"><label>Required Delivery Date</label><input id="boDate" type="date" value="${po.requiredDate||''}"></div></div><div class="tableWrap" style="margin-top:10px"><table class="table"><thead><tr><th>#</th><th>Brand</th><th>Packing</th><th>Tare g</th><th>Required</th><th>Extra %</th><th>Total</th><th>Handle</th><th>Master Bag Qty / Tare</th><th>GOOD SIDE Artwork</th></tr></thead><tbody>${po.lines.map((l,i)=>`<tr><td>${i+1}</td><td><input data-bo-brand="${i}" value="${esc(l.brand)}" readonly></td><td>${esc(l.type)} · ${l.size} ${l.unit}</td><td><input data-bo-tare="${i}" type="number" value="${l.tare}" readonly></td><td>${l.requiredBags.toLocaleString()}</td><td><input data-bo-extra="${i}" type="number" step="0.1" value="${l.extraPct}" readonly></td><td data-total-bags="${i}">${l.totalBags.toLocaleString()}</td><td><select data-bo-handle="${i}"><option ${l.handle==='No'?'selected':''}>No</option><option ${l.handle==='Yes'?'selected':''}>Yes</option></select></td><td><label><input data-bo-master="${i}" type="checkbox" ${l.masterBag.enabled?'checked':''} disabled> Yes</label><input data-bo-master-qty="${i}" type="number" placeholder="Qty" value="${l.masterBag.qty||''}" readonly><input data-bo-master-tare="${i}" type="number" placeholder="Tare g" value="${l.masterBag.tare||''}" readonly></td><td><input data-bo-art="${i}" type="file" accept="image/*"><div class="metaText">${esc(l.artworkName||'No file')}</div>${l.artworkData?.startsWith('data:image/')?`<img src="${l.artworkData}" alt="Good side artwork" style="max-width:120px;max-height:90px;object-fit:contain">`:''}</td></tr>`).join('')}</tbody></table></div><div class="toolbar" style="margin-top:12px"><div class="notice" style="margin:0">Delivery Challan must clearly mention BRAND NAME and P.O. NUMBER.</div><div class="spacer"></div><button class="btn green" id="generatePO">GENERATE ONE PO & SEND TO MILL</button></div></div>${s.bagOrders.length?`<div class="section"><h3>Issued POs</h3>${s.bagOrders.map((x,i)=>`<div class="notice"><b>${esc(x.poNo)}</b> · ${esc(x.supplier)} · ${x.lines.length} line(s) <button class="btn small soft" data-load-po="${i}">Update Same PO</button></div>`).join('')}</div>`:''}`;wireBagOrder()}
function wireBagOrder(){const s=shipment(),po=ensureBagDraft();document.getElementById('addSupplier').onclick=openSupplierModal;boNo.oninput=e=>po.poNo=e.target.value;boSupplier.onchange=e=>po.supplier=e.target.value;boDeliver.oninput=e=>po.deliverTo=e.target.value;boDate.onchange=e=>po.requiredDate=e.target.value;newPODraft.onclick=()=>{s.bagOrderDraft=null;save();renderShipmentWorkspace()};document.querySelectorAll('[data-bo-brand]').forEach(x=>x.oninput=e=>po.lines[num(x.dataset.boBrand)].brand=e.target.value);document.querySelectorAll('[data-bo-tare]').forEach(x=>x.oninput=e=>po.lines[num(x.dataset.boTare)].tare=num(e.target.value));document.querySelectorAll('[data-bo-extra]').forEach(x=>x.oninput=e=>{const l=po.lines[num(x.dataset.boExtra)];l.extraPct=num(e.target.value);l.extraBags=Math.ceil(l.requiredBags*l.extraPct/100);l.totalBags=l.requiredBags+l.extraBags;document.querySelector(`[data-total-bags="${x.dataset.boExtra}"]`).textContent=l.totalBags.toLocaleString()});document.querySelectorAll('[data-bo-handle]').forEach(x=>x.onchange=e=>po.lines[num(x.dataset.boHandle)].handle=e.target.value);document.querySelectorAll('[data-bo-master]').forEach(x=>x.onchange=e=>po.lines[num(x.dataset.boMaster)].masterBag.enabled=e.target.checked);document.querySelectorAll('[data-bo-master-qty]').forEach(x=>x.oninput=e=>po.lines[num(x.dataset.boMasterQty)].masterBag.qty=num(e.target.value));document.querySelectorAll('[data-bo-master-tare]').forEach(x=>x.oninput=e=>po.lines[num(x.dataset.boMasterTare)].masterBag.tare=num(e.target.value));document.querySelectorAll('[data-bo-art]').forEach(x=>x.onchange=async e=>{const f=e.target.files[0],l=po.lines[num(x.dataset.boArt)];if(!f)return;if(f.size>1536*1024){e.target.value='';return alert('Each bag marking file must be 1.5 MB or smaller.')}if(!f.type.startsWith('image/')){e.target.value='';return alert('Bag marking must be an image.')}try{const doc=await uploadDocument(f,'bag-marking',s);l.artworkName=doc.name;l.artworkDocument=doc;l.artworkData=doc.downloadUrl||doc.dataUrl;l.artworkAttached=true;l.approved=true;l.approvedAt=new Date().toISOString();save();renderShipmentWorkspace()}catch(err){e.target.value='';alert(err.message)}});generatePO.onclick=issuePO;document.querySelectorAll('[data-load-po]').forEach(x=>x.onclick=()=>{s.bagOrderDraft=structuredClone(s.bagOrders[num(x.dataset.loadPo)]);s.bagOrderDraft._updateIndex=num(x.dataset.loadPo);renderShipmentWorkspace()})}
function issuePO(){const s=shipment(),c=contractByRef(s.contractRef),po=ensureBagDraft();if(!c.received)return alert('Mark the signed Sales Contract received before issuing the Bag Order.');if(!po.supplier)return alert('Select Supplier.');if(po.lines.some(l=>!l.brand.trim()))return alert('Every packing line must have a Brand.');if(po.lines.some(l=>!l.artworkAttached||!l.approved||!String(l.artworkData||'').trim()))return alert('Upload the GOOD SIDE bag marking for every packing line. Uploading it is the approval and makes it visible on the PO.');if(po.lines.some(l=>l.masterBag?.enabled&&(num(l.masterBag.qty)<=0||num(l.masterBag.tare)<=0)))return alert('Complete master bag quantity and tare.');const out=structuredClone(po);out.issuedAt=new Date().toISOString();out.status='Synced to Mill';if(Number.isInteger(po._updateIndex)){const old=s.bagOrders[po._updateIndex];out.poNo=old.poNo;out.versions=[...(old.versions||[]),{at:out.issuedAt,snapshot:structuredClone(old)}];s.bagOrders[po._updateIndex]=out}else{s.bagOrders.push(out)}state.millSync.newExportBags=state.millSync.newExportBags.filter(x=>!(x.contractRef===s.contractRef&&x.poNo===out.poNo));out.lines.forEach((l,i)=>state.millSync.newExportBags.push({contractRef:s.contractRef,poNo:out.poNo,supplier:out.supplier,deliverTo:out.deliverTo,requiredDate:out.requiredDate,line:i+1,brand:l.brand,type:l.type,size:l.size,unit:l.unit,orderedTare:l.tare,requiredBags:l.requiredBags,extraPct:l.extraPct,extraBags:l.extraBags,totalOrdered:l.totalBags,artworkName:l.artworkName,artworkData:l.artworkData,artworkDocument:l.artworkDocument||null,approved:true,handle:l.handle,masterBag:l.masterBag,status:'Order from Export — Awaiting Receipt'}));audit('BAG ORDER','Generated one multi-line PO with uploaded approved markings and sent to Mill',s.contractRef+' · '+out.poNo);s.bagOrderDraft=null;printShipmentDoc('PURCHASE ORDER',purchaseOrderPrint(out),c.seller);renderShipmentWorkspace()}
function purchaseOrderPrint(po){const c=contractByRef(shipment().contractRef),summary=`<table class="docMeta"><tr><td class="lbl">PO Number</td><td>${esc(po.poNo)}</td><td class="lbl">Order Date</td><td>${fmt((po.issuedAt||'').slice(0,10))}</td></tr><tr><td class="lbl">Supplier</td><td>${esc(po.supplier)}</td><td class="lbl">Required Delivery</td><td>${po.requiredDate?fmt(po.requiredDate):'TO BE ADVISED LATER'}</td></tr><tr><td class="lbl">Deliver To</td><td colspan="3">${esc(po.deliverTo||'To Be Advised Later')}</td></tr></table><table class="docTable"><thead><tr><th>#</th><th>Brand / Packing</th><th>Required + Extra</th><th>Total</th><th>Master Bag</th></tr></thead><tbody>${po.lines.map((l,i)=>`<tr><td>${i+1}</td><td><b>${esc(l.brand)}</b><br>${esc(l.type)} · ${l.size} ${l.unit} · tare ${l.tare}g · handle ${esc(l.handle||'No')}</td><td>${l.requiredBags.toLocaleString()} + ${l.extraBags.toLocaleString()} (${l.extraPct}%)</td><td>${l.totalBags.toLocaleString()}</td><td>${l.masterBag?.enabled?`${num(l.masterBag.qty).toLocaleString()} pcs · ${num(l.masterBag.tare)}g`:'No'}</td></tr>`).join('')}</tbody></table><div class="greenBox"><b>DELIVERY CHALLAN MUST CLEARLY MENTION THE BRAND NAME AND P.O. NUMBER.</b></div>${signature(c)}`,artPages=po.lines.map((l,i)=>pageDoc(c,`APPROVED BAG MARKING — ${esc(l.brand)}`,`<div class="approvedMarking"><div class="approvedMarkingLabel">APPROVED · GOOD SIDE</div><img src="${l.artworkData}" alt="Approved ${esc(l.brand)} bag marking"><h2>${esc(l.brand)}</h2><p>${esc(l.type)} · ${num(l.size)} ${esc(l.unit)} · Tare ${num(l.tare)}g · PO ${esc(po.poNo)}</p></div>${signature(c)}`)).join('');return pageDoc(c,'PURCHASE ORDER',summary)+artPages}
const renderBagOrderBase=renderBagOrder;
renderBagOrder=function(d){renderBagOrderBase(d);const s=shipment(),po=ensureBagDraft(),subtitle=d.querySelector('.metaText');if(subtitle)subtitle.textContent='One PO for all packing lines. Uploading a GOOD SIDE bag marking means it is approved; no separate approval stages or source fields.';d.querySelectorAll('[data-bo-art]').forEach((input,i)=>{const line=po.lines[i],cell=input.closest('td');if(line?.artworkData&&!String(line.artworkData).startsWith('data:image/')&&cell&&!cell.querySelector('.artPreview'))cell.insertAdjacentHTML('beforeend',`<img class="artPreview" src="${esc(line.artworkData)}" alt="Approved GOOD SIDE bag marking">`);if(line?.approved&&cell&&!cell.querySelector('.artApproved'))cell.insertAdjacentHTML('beforeend','<div class="status green artApproved">APPROVED ON UPLOAD</div>')});for(const order of s.bagOrders||[])for(const line of order.lines||[])line.approved=!!line.artworkAttached};
function renderProduction(d){
 const s=shipment(),c=contractByRef(s.contractRef),p=s.production,specs=contractSpecRows(c),issued=s.bagOrders.at(-1);
 d.innerHTML=`<div class="section"><div class="toolbar"><div><h3>PRODUCTION INSTRUCTIONS</h3><div class="metaText">Contract quality, specifications and the issued Bag PO flow here automatically.</div></div><div class="spacer"></div>${p.sentToMill?'<div class="stamp">PRODUCTION INSTRUCTIONS ALREADY SENT</div>':''}</div>
 <div class="grid4"><div class="field"><label>Dry On</label><select id="piDry"><option ${p.dryOn==='No'?'selected':''}>No</option><option ${p.dryOn==='Yes'?'selected':''}>Yes</option></select></div><div class="field"><label>Craft Paper</label><select id="piCraft"><option ${p.craftPaper==='No'?'selected':''}>No</option><option ${p.craftPaper==='Yes'?'selected':''}>Yes</option></select></div><div class="field"><label>DPP</label><select id="piDPP"><option ${p.dpp==='Yes'?'selected':''}>Yes</option><option ${p.dpp==='No'?'selected':''}>No</option></select></div><div class="field"><label>Inspection</label><input id="piInspection" value="${esc(p.inspection||c.inspection)}"></div><div class="field full"><label>Quality / Special Instructions</label><textarea id="piQuality">${esc(p.qualityNotes||c.quality)}</textarea></div></div>
 <h4>Contract Specifications</h4><div class="tableWrap"><table class="table"><thead><tr><th>Specification</th><th>Requirement</th></tr></thead><tbody>${specs.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.value)}</td></tr>`).join('')}</tbody></table></div>
 <h4>Packing & Bag Requirement</h4><div class="tableWrap"><table class="table"><thead><tr><th>Brand</th><th>Product</th><th>Packing</th><th>Tare</th><th>Containers</th><th>Required MT</th><th>Bags Ordered</th><th>Master Bags quantity</th><th>Master Bag tare</th></tr></thead><tbody>${c.packings.map((pk,i)=>{const line=issued?.lines?.find(x=>num(x.packingIndex)===i)||issued?.lines?.[i],master=line?.masterBag||pk.masterBag||{};return`<tr><td>${esc(pk.brand)}</td><td>${esc(c.product)}</td><td>${num(pk.size)} ${esc(c.packingUnit)} ${esc(pk.type)}</td><td>${num(pk.tare)} g</td><td>${num(pk.containers)}</td><td>${(num(pk.containers)*num(pk.weightPer)).toFixed(3)}</td><td>${num(line?.totalBags||bagRequired(pk,c)).toLocaleString()}</td><td>${master.enabled?num(master.quantity||master.qty).toLocaleString():'No'}</td><td>${master.enabled?num(master.tare)+' g':'—'}</td></tr>`}).join('')}</tbody></table></div>
 <div class="toolbar" style="margin-top:12px"><div class="spacer"></div><button class="btn green" id="sendPI">SEND PRODUCTION INSTRUCTIONS TO MILL</button></div></div>`;
 const piDry=document.getElementById('piDry'),piCraft=document.getElementById('piCraft'),piDPP=document.getElementById('piDPP'),piInspection=document.getElementById('piInspection'),piQuality=document.getElementById('piQuality'),sendPI=document.getElementById('sendPI');
 piDry.onchange=e=>p.dryOn=e.target.value;piCraft.onchange=e=>p.craftPaper=e.target.value;piDPP.onchange=e=>p.dpp=e.target.value;piInspection.oninput=e=>p.inspection=e.target.value;piQuality.oninput=e=>p.qualityNotes=e.target.value;
 sendPI.onclick=()=>{if(!c.received)return alert('Mark the signed Sales Contract received first.');if(!s.bagOrders.length)return alert('Issue the Bag Order before sending Production Instructions.');if(c.packings.some(pk=>!pk.brand.trim()))return alert('Every required bag brand must be inserted before sending Production Instructions.');p.sentToMill=true;state.millSync.productionInstructions=state.millSync.productionInstructions.filter(x=>x.contractRef!==s.contractRef);state.millSync.productionInstructions.push({contractRef:s.contractRef,product:c.product,specifications:structuredClone(specs),quality:c.quality||DEFAULT_QUALITY,packings:structuredClone(c.packings),bagOrder:structuredClone(s.bagOrders.at(-1)),production:structuredClone(p),sentAt:new Date().toISOString()});audit('PRODUCTION INSTRUCTIONS','Sent to Mill',s.contractRef);renderShipmentWorkspace()}
}

/* Production hardening: migration, deterministic document readers and reviewed imports. */
function cleanText(v){return String(v||'').replace(/\r/g,'\n').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim()}
function lines(v){return cleanText(v).split('\n').map(x=>x.trim()).filter(Boolean)}
function fieldValue(text,labels){const ls=lines(text);for(const label of labels){const re=new RegExp('^:?(?:'+label+')\\s*(?::|-)?\\s*(.+)$','i');for(const line of ls){const m=line.match(re);if(m?.[1])return m[1].trim()}}return''}
function swiftBlock(text,code){const src=String(text||'').split(/\r?\n/),out=[];let active=false;const start=new RegExp(`^\\s*(?:(?::\\s*)?${code}\\s*:|FIELD\\s+${code}\\s*:)\\s*(.*)$`,'i'),next=/^\s*(?:(?::\s*)?\d{2}[A-Z]?\s*:|FIELD\s+\d{2}[A-Z]?\s*:)/i;for(const line of src){const m=line.match(start);if(m){active=true;if(m[1])out.push(m[1]);continue}if(active&&next.test(line))break;if(active)out.push(line)}return cleanText(out.join('\n'))}
function isLcControlFieldLine(name){return /^(?:FIELD\s*)?(?:20|21|23|31C|31D|32B|39A|40A|40E|41A|42A|42C|43P|43T|44A|44B|44C|44E|44F|45A|47A|48|49|50|51A|53A|57A|59|71B|72|78|79)\s*[:.-]/i.test(String(name||''))}
function lcDocumentLines(text){const block=swiftBlock(text,'46A'),source=block||text;return lines(source).filter(x=>!isLcControlFieldLine(x)).filter(x=>/COMMERCIAL INVOICE|PACKING LIST|BILL OF LADING|CERTIFICATE|E-?PHYTO|PHYTOSANITARY|FUMIGATION|INSPECTION|INSURANCE/i.test(x)).slice(0,80)}
function documentCountsFromText(name){const text=String(name||'').toUpperCase(),original=(text.match(/(\d+)\s*ORIGINALS?\b/)||[])[1],copy=(text.match(/(\d+)\s*COP(?:Y|IES)\b/)||[])[1];if(original||copy)return{originals:original?num(original):1,copies:copy?num(copy):0};if(/QUADRUPLICATE/.test(text))return{originals:1,copies:3};if(/TRIPLICATE/.test(text))return{originals:1,copies:2};if(/DUPLICATE/.test(text))return{originals:1,copies:1};return{originals:1,copies:0}}
function lcConditionLines(text){const block=swiftBlock(text,'47A'),source=block?lines(block):lines(text).filter(x=>/ADDITIONAL CONDITION|DISCREPANC|BANK CHARGE|REIMBURSEMENT/i.test(x));return source.filter(x=>!/^ADDITIONAL CONDITIONS?\s*:?\s*$/i.test(x)&&!isLcControlFieldLine(x)).slice(0,120)}
function firstNumber(v){const m=String(v||'').match(/\d[\d.,]*/);if(!m)return 0;let s=m[0];if(s.includes(',')&&!s.includes('.'))s=/,\d{1,2}$/.test(s)?s.replace(',','.'):s.replace(/,/g,'');else if(s.includes(',')&&s.includes('.'))s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');return Number(s)||0}
function parseDate(v){const s=String(v||'');let m=s.match(/(20\d{2})[-\/.](\d{1,2})[-\/.](\d{1,2})/);if(m)return`${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;m=s.match(/(\d{1,2})[-\/.](\d{1,2})[-\/.](20\d{2})/);if(m)return`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;m=s.toUpperCase().match(/(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[A-Z]*\s+(20\d{2})/);if(m){const months={JAN:'01',FEB:'02',MAR:'03',APR:'04',MAY:'05',JUN:'06',JUL:'07',AUG:'08',SEP:'09',OCT:'10',NOV:'11',DEC:'12'};return`${m[3]}-${months[m[2]]}-${m[1].padStart(2,'0')}`}m=s.match(/(?:^|\D)(\d{2})(\d{2})(\d{2})(?:\D|$)/);return m?`20${m[1]}-${m[2]}-${m[3]}`:''}
function paymentFromText(text){const u=String(text).toUpperCase(),raw=fieldValue(text,['PAYMENT(?: TERMS?)?','TERMS OF PAYMENT']);if(/USANCE|DEFERRED|\d+\s*DAYS.*(?:B\/?L|BILL OF LADING)/.test(u))return{paymentCode:'LC_USANCE',usanceDays:firstNumber((u.match(/\d+\s*DAYS/)||[])[0])||90,paymentText:raw};if(/LETTER OF CREDIT|DOCUMENTARY CREDIT|L\/?C\s+AT\s+SIGHT|IRREVOCABLE\s+L\/?C/.test(u))return{paymentCode:'LC_SIGHT',usanceDays:0,paymentText:raw};if(/100\s*%\s*ADVANCE/.test(u))return{paymentCode:'ADV100',advancePct:100,paymentText:raw};const pct=firstNumber((u.match(/\d+(?:\.\d+)?\s*%\s*ADVANCE/)||[])[0]);if(/CASH AGAINST DOCUMENTS|\bCAD\b/.test(u))return{paymentCode:pct?'ADV_CAD':'CAD100',advancePct:pct,paymentText:raw};return pct?{paymentCode:'ADV_SCAN',advancePct:pct,paymentText:raw}:{paymentCode:'CUSTOM',customPayment:raw,paymentText:raw}}
function parsePackingLines(text,qty,containers,price){const out=[];for(const line of lines(text)){const m=line.match(/(\d+(?:\.\d+)?)\s*(KG|KGS|LB|LBS)\b/i);if(!m||!/BAG|SACK|PACK/i.test(line))continue;const size=num(m[1]),unit=/LB/i.test(m[2])?'LB':'KG',type=/JUTE/i.test(line)?'Jute Bags':/PAPER/i.test(line)?'Paper Bags':'PP Bags',brand=((line.match(/(?:BRAND|MARKING)\s*(?::|-)?\s*([A-Z0-9][A-Z0-9 &._\/-]{0,40}?)(?=\s+(?:TARE|MASTER BAG|CONTAINERS?|CNTRS?|\d+(?:\.\d+)?\s*(?:MT|MTS|M\/TONS?))|$)/i)||[])[1]||'').trim(),tare=firstNumber((line.match(/TARE[^\d]{0,8}(\d+(?:\.\d+)?)/i)||[])[1]),lineContainers=firstNumber((line.match(/(\d+)\s*(?:X\s*)?(?:CONTAINERS?|CNTRS?)/i)||[])[1]),lineQty=firstNumber((line.match(/(\d+(?:\.\d+)?)\s*(?:MT|MTS|M\/TONS?)/i)||[])[1]);if(!out.some(x=>x.size===size&&x.unit===unit&&x.type===type))out.push({type,size,unit,brand,tare,containers:lineContainers,weightPer:lineContainers&&lineQty?lineQty/lineContainers:0,price:num(price),freight:0,insurance:0,extraBagPct:0,masterBag:{enabled:/MASTER BAG/i.test(line),qty:firstNumber((line.match(/MASTER BAG[^\d]{0,12}(\d+)/i)||[])[1]),tare:firstNumber((line.match(/MASTER BAG.*?TARE[^\d]{0,8}(\d+(?:\.\d+)?)/i)||[])[1])}})}if(out.length===1){out[0].containers=out[0].containers||num(containers);out[0].weightPer=out[0].weightPer||(containers?num(qty)/num(containers):0)}if(out.length>1&&out.every(x=>!x.containers)&&containers%out.length===0)for(const x of out)x.containers=containers/out.length;if(containers)for(const x of out)x.weightPer=x.weightPer||qty/containers;return out}
