function readerBody(kind,shipId=''){return`<div class="notice info">The reader runs in this browser and does not use ChatGPT or require a Plus subscription. Extracted values are reviewed before becoming master data.</div>${kind==='lc'?`<div class="field"><label>Shipment / Contract</label><select id="readerShipment">${processes().map(s=>`<option value="${esc(s.id)}" ${shipId===s.id?'selected':''}>${esc(s.contractRef)} · ${esc(s.buyer)}</option>`).join('')}</select></div>`:''}<div class="field"><label>${kind==='lc'?'L/C':'Customer contract'} file</label><input id="readerFile" type="file" accept=".pdf,.docx,.txt,.png,.jpg,.jpeg,.webp"></div><div class="field"><label>Or paste document text</label><textarea id="readerText" style="min-height:150px"></textarea></div><div id="readerProgress" class="metaText"></div><div id="readerReview"></div>`}
