function tgPakistanCoveringDoc(s,c){const pc={...pakistanCustomsContext(s,c),paymentCode:'INTERCOMPANY'},fi=(s.customs.fiAllocations||[]).map(v=>v.number||v).filter(Boolean).join(', '),gd=(s.customs.gdRefs||[]).map(v=>v.number||v).filter(Boolean).join(', '),docs=['Intercompany / Custom Invoice','Custom Packing List','Phytosanitary Invoice / Application','Bill of Lading','Certificate of Origin','Supporting Certificates'];return pageDoc(pc,'PAKISTAN BANK COVERING — TG SETTLEMENT',`<p>${fmt(s.customs.date||TODAY())}</p><div class="docPartyBox"><b>To</b>${esc(s.customs.bank||'The Manager, Export Department')}</div><div class="coverSubject">${esc(s.contractRef)} · ${esc(s.lotId)} · ${esc(SELLERS[pakistanExporterKey(s)])} → ${esc(SELLERS.TG)}</div><p>Please find enclosed the Pakistan-side export and intercompany documents for settlement of the above physical shipment.</p><table class="coverDocs"><tr><th>#</th><th>Document</th></tr>${docs.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x)}</td></tr>`).join('')}</table><p><b>Custom / Intercompany Invoice:</b> ${esc(s.customs.invoiceNo||c.ref)}${fi?` · <b>FI:</b> ${esc(fi)}`:''}${gd?` · <b>GD:</b> ${esc(gd)}`:''}</p>${s.customs.iban?`<p><b>IBAN:</b> ${esc(s.customs.iban)}</p>`:''}${signature(pc)}`)}
function lcDraftDoc(s,c){const l=s.lc||{},amount=invoiceLines(s,c,false).reduce((sum,line)=>sum+num(line.amount),0);return pageDoc(c,'BILL OF EXCHANGE',`<div class="draftCopyLabel">ORIGINAL / DUPLICATE</div><div class="draftAmount">${esc(c.currency)} ${amount.toLocaleString(undefined,{minimumFractionDigits:2})}</div><div class="draftBody"><p>At <span class="draftLine">${c.paymentCode==='LC_USANCE'?`${num(c.usanceDays||l.usanceDays)} days from B/L date`:'SIGHT'}</span> pay to the order of <span class="draftLine">${esc(l.advisingBank||s.covering.bank||'SELLER’S BANK')}</span> the sum of ${esc(c.currency)} ${amount.toLocaleString(undefined,{minimumFractionDigits:2})}.</p><p>Drawn under L/C No. <b>${esc(l.lcNo)}</b> dated ${fmt(l.lcDate)} issued by ${esc(l.issuingBank)}.</p><p>TO: ${esc(l.issuingBank)}</p></div>${signature(c)}`)}
