function customsBalanced(s,c){if(!s?.customs?.saved)return false;const value=customsInvoiceValue(s,c),allocated=(s.customs.fiAllocations||[]).reduce((sum,v)=>sum+num(v.amount),0),open=num(s.customs.openAccount);return Math.abs(allocated+open-value)<=.01&&Math.abs(num(s.customs.invoiceValue)-value)<=.01}
