function renderHistory(d){const s=shipment(),p=processFor(s),allPOs=processes().flatMap(x=>(x.bagOrders||[]).map(po=>String(po.poNo||''))),uniquePOs=(p?.bagOrders||[]).map(x=>String(x.poNo||'')).filter(po=>po&&allPOs.filter(x=>x===po).length===1),tokens=[s.contractRef,s.bl?.blNo,s.commercial?.invoiceNo,s.covering?.tracking,...(s.customs?.gdRefs||[]).flatMap(g=>[g.number||g]),...(s.customs?.fiAllocations||[]).flatMap(a=>[a.fiNumber,a.fiId]),...uniquePOs].map(String).filter(x=>x&&x!=='undefined');const rows=state.audits.filter(a=>tokens.some(token=>String(a.detail||'').includes(token)));d.innerHTML=`<div class="section"><h3>HISTORY & VERSIONS</h3><div class="tableWrap"><table class="table"><thead><tr><th>When</th><th>User</th><th>Area</th><th>Action</th><th>Detail</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${new Date(a.at).toLocaleString()}</td><td>${esc(a.user)}</td><td>${esc(a.area)}</td><td>${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div></div>`}
const REPORT_DEFS=[['contracts','▤','Sales Contract Register'],['shipments','▣','Shipment Register'],['pendingShipments','⏳','Pending Shipments'],['pendingDocs','⚠','Pending Documents'],['customers','👤','Customer-wise Export'],['products','◈','Product-wise Export'],['containers','▦','Container / Loading Register'],['bl','🚢','B/L Register'],['bags','▧','Bag Order Register'],['dispatch','✉','Document Dispatch Register'],['fi','🏦','FI Register / FI Utilisation'],['gd','#','GD Register'],['invoice','💵','Commercial Invoice Register'],['cancelled','⊘','Cancelled Shipments'],['completed','✓','Completed Shipments']];
function reportTable(key){const lots=state.shipments.filter(s=>s.kind==='lot'),cFor=s=>contractByRef(s.contractRef)||{},table=(heads,rows)=>`<div class="tableWrap"><table class="table"><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${heads.length}">No records.</td></tr>`}</tbody></table></div>`;if(key==='contracts')return table(['Contract','Date','Buyer','Product','Qty MT','Status'],state.contracts.map(c=>`<tr><td>${esc(c.ref)}</td><td>${fmt(c.date)}</td><td>${esc(customer(c.customerId)?.name||'')}</td><td>${esc(c.product)}</td><td>${num(c.qty).toFixed(3)}</td><td>${esc(c.status)}</td></tr>`));if(key==='containers')return table(['Contract / Lot','Container','Seal','Loading From','Bags','Net KG'],lots.flatMap(s=>(s.millActuals||[]).map(a=>`<tr><td>${esc(s.contractRef)} · ${esc(s.lotId)}</td><td>${esc(a.number)}</td><td>${esc(a.seal)}</td><td>${esc(a.location)}</td><td>${num(a.bags).toLocaleString()}</td><td>${num(a.netKg).toFixed(3)}</td></tr>`)));if(key==='bags')return table(['Contract','PO','Supplier','Lines','Status'],processes().flatMap(p=>(p.bagOrders||[]).map(x=>`<tr><td>${esc(p.contractRef)}</td><td>${esc(x.poNo)}</td><td>${esc(x.supplier)}</td><td>${x.lines.length}</td><td>${esc(x.status)}</td></tr>`)));if(key==='fi')return table(['FI','Customer','Currency','Total','Used','Available'],state.fi.map(f=>`<tr><td>${esc(f.number)}</td><td>${esc(f.customer)}</td><td>${esc(f.currency)}</td><td>${num(f.value).toFixed(2)}</td><td>${fiUsed(f).toFixed(2)}</td><td>${(num(f.value)-fiUsed(f)).toFixed(2)}</td></tr>`));if(key==='bl')return table(['Contract / Lot','B/L','On Board','Vessel','Final Original'],lots.map(s=>`<tr><td>${esc(s.contractRef)} · ${esc(s.lotId)}</td><td>${esc(s.bl.blNo)}</td><td>${fmt(s.bl.onBoardDate)}</td><td>${esc(s.bl.vessel)}</td><td>${s.bl.finalDocument?'Yes':'No'}</td></tr>`));if(key==='gd')return table(['Contract / Lot','GD No.','GD Date'],lots.flatMap(s=>(s.customs.gdRefs||[]).map(g=>`<tr><td>${esc(s.contractRef)} · ${esc(s.lotId)}</td><td>${esc(g.number||g)}</td><td>${fmt(g.date||'')}</td></tr>`)));if(key==='invoice')return table(['Contract / Lot','Invoice','Date','Currency','Value','Received','Balance'],lots.map(s=>{const c=cFor(s),total=invoiceLines(s,c,false).reduce((a,v)=>a+num(v.amount),0),received=accountsTotal(s,c);return`<tr><td>${esc(s.contractRef)} · ${esc(s.lotId)}</td><td>${esc(s.commercial.invoiceNo)}</td><td>${fmt(s.commercial.date)}</td><td>${esc(c.currency)}</td><td>${total.toFixed(2)}</td><td>${received.toFixed(2)}</td><td>${(total-received).toFixed(2)}</td></tr>`}));if(key==='dispatch')return table(['Contract / Lot','Through','Courier','AWB','Date','Frozen'],lots.filter(s=>s.covering.dispatched).map(s=>`<tr><td>${esc(s.contractRef)} · ${esc(s.lotId)}</td><td>${esc(s.covering.sentThrough)}</td><td>${esc(s.covering.otherCourier||'')}</td><td>${esc(s.covering.tracking)}</td><td>${fmt(s.covering.dispatchDate)}</td><td>${s.covering.frozen?'Yes':'No'}</td></tr>`));if(key==='pendingDocs')return table(['Contract / Lot','Missing Items'],lots.filter(s=>!s.cancelled&&!s.completed).map(s=>`<tr><td>${esc(s.contractRef)} · ${esc(s.lotId)}</td><td>${esc(completionMissing(s,cFor(s)).join(', '))}</td></tr>`));if(key==='pendingShipments')return table(['Contract / Lot','Qty MT','Status'],lots.filter(s=>!s.cancelled&&!s.completed).map(s=>`<tr><td>${esc(s.contractRef)} · ${esc(s.lotId)}</td><td>${num(s.plannedQty).toFixed(3)}</td><td>${esc(lotStatus(s))}</td></tr>`));if(key==='cancelled'||key==='completed')return table(['Contract / Lot','Buyer','Qty MT','Status / Reason'],lots.filter(s=>key==='cancelled'?s.cancelled:s.completed).map(s=>`<tr><td>${esc(s.contractRef)} · ${esc(s.lotId)}</td><td>${esc(s.buyer)}</td><td>${num(s.plannedQty).toFixed(3)}</td><td>${esc(s.cancelReason||s.status)}</td></tr>`));if(key==='customers'){const groups=new Map();for(const s of lots.filter(x=>!x.cancelled)){const g=groups.get(s.buyer)||{lots:0,mt:0};g.lots++;g.mt+=num(s.plannedQty);groups.set(s.buyer,g)}return table(['Customer','Lots','Quantity MT'],[...groups].map(([name,g])=>`<tr><td>${esc(name)}</td><td>${g.lots}</td><td>${g.mt.toFixed(3)}</td></tr>`))}if(key==='products'){const groups=new Map();for(const s of lots.filter(x=>!x.cancelled)){const name=cFor(s).product||'',g=groups.get(name)||{lots:0,mt:0};g.lots++;g.mt+=num(s.plannedQty);groups.set(name,g)}return table(['Product','Lots','Quantity MT'],[...groups].map(([name,g])=>`<tr><td>${esc(name)}</td><td>${g.lots}</td><td>${g.mt.toFixed(3)}</td></tr>`))}return table(['Contract / Lot','Buyer','Quantity MT','Status'],lots.map(s=>`<tr><td>${esc(s.contractRef)} · ${esc(s.lotId)}</td><td>${esc(s.buyer)}</td><td>${num(s.plannedQty).toFixed(3)}</td><td>${esc(s.status)}</td></tr>`))}
function renderReports(){document.getElementById('main').innerHTML=`<div class="panel"><h2>Reports & Registers</h2><div class="workspaceTiles reportTiles">${REPORT_DEFS.map(([k,icon,label])=>`<button class="workspaceTile" data-report="${k}"><span class="workspaceGlyph">${icon}</span><b>${esc(label)}</b></button>`).join('')}</div><div class="workspaceDetail" id="reportDetail"><div class="notice">Select one report. It opens immediately below these boxes; opening another replaces it.</div></div></div>`;document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-report]').forEach(x=>x.classList.toggle('active',x===b));const def=REPORT_DEFS.find(x=>x[0]===b.dataset.report);reportDetail.innerHTML=`<div class="section"><div class="toolbar"><h3>${esc(def[2])}</h3><div class="spacer"></div><button class="btn green" id="printReport">PRINT / SAVE</button></div>${reportTable(def[0])}</div>`;printReport.onclick=()=>printHTML(def[2],`<div class="printDoc"><section class="docPage"><h1 class="docTitle">${esc(def[2])}</h1>${reportTable(def[0])}<div class="docPageNo">Generated ${fmt(TODAY())}</div></section></div>`)})}
function openModal(title,body,foot){const id=uid('modal');modalStack.push(id);const w=document.createElement('div');w.className='modalBackdrop';w.dataset.modal=id;w.innerHTML=`<div class="modal"><div class="modalHead"><h3>${esc(title)}</h3><div style="margin-left:auto"></div><button class="btn small" data-modal-close>✕</button></div><div class="modalBody">${body}</div><div class="modalFoot">${foot||''}</div></div>`;document.body.appendChild(w);w.querySelectorAll('[data-modal-close]').forEach(x=>x.onclick=closeModal);return w}
function closeModal(){const id=modalStack.pop();document.querySelector(`[data-modal="${id}"]`)?.remove()}
function directPrint(title,html,mode='with'){const root=document.getElementById('printRoot');root.className=mode==='without'?'printModeWithout':'printModeWith';root.innerHTML=html;root.setAttribute('aria-hidden','false');const old=document.title;document.title=`${title} - Transtrade`;setTimeout(()=>{window.print();setTimeout(()=>{root.innerHTML='';root.className='';root.setAttribute('aria-hidden','true');document.title=old},250)},100)}
function printShipmentDoc(title,html,seller='TTI'){const hasFooter=!!SELLER_DETAILS[seller]?.footer,label=hasFooter?'HEADER / FOOTER':'HEADER';openModal('Print / Save — '+title,`<div class="notice info"><b>Choose the paper mode.</b> Saved PDFs and plain-paper prints include the full-width ${esc(seller)} ${hasFooter?'header and footer':'header (this company has no footer)'}. Physical company letterhead leaves the artwork blank and preserves printing space.</div><div class="cards"><button class="btn green big" id="printWith">WITH ${label}<br><span class="tiny">Save PDF or print on plain paper</span></button><button class="btn amber big" id="printWithout">WITHOUT ${label}<br><span class="tiny">Print on physical company letterhead</span></button></div>`,`<button class="btn" data-modal-close>Cancel</button>`);document.getElementById('printWith').onclick=()=>{closeModal();directPrint(title,html,'with')};document.getElementById('printWithout').onclick=()=>{closeModal();directPrint(title,html,'without')}}
function printHTML(title,html){directPrint(title,html,'with')}
window.addEventListener('beforeprint',()=>document.getElementById('printRoot')?.setAttribute('aria-hidden','false'));
document.addEventListener('change',e=>{if(!contractDraft)return;if(e.target?.id==='cPayment')contractDraft.paymentDeadline=addBankDays(contractDraft.date,String(contractDraft.paymentCode).startsWith('LC_')?5:4);if(e.target?.id==='cDate')contractDraft.paymentDeadline=addBankDays(contractDraft.date,String(contractDraft.paymentCode).startsWith('LC_')?5:4);if(e.target?.id==='cProduct'&&productMasters().length){applyProductMaster(contractDraft,e.target.value);renderContractStep()}});
function requiredFinalCertificateTypes(s,c){const text=[...(c.docs||[]),...(s.lc?.documents||[])].join(' ').toLowerCase(),types=[];if(/phyto/.test(text))types.push('phyto');if(/fumigation/.test(text))types.push('fumigation');if(/inspection/.test(text))types.push('inspection');if(/insurance/.test(text)||c.incoterm==='CIF')types.push('insurance');return types}
function hasFinalCertificate(s,needle){return(s.certs||[]).some(x=>String(x.type||'').toLowerCase().includes(needle)&&x.finalDocument)}
function completionMissing(s,c){const missing=[];if(!millActualsComplete(s))missing.push('complete and valid Mill container/seal actuals');if(!customsBalanced(s,c))missing.push('balanced Customs master (re-save after any weight, rate or payment change)');const gds=s.customs?.gdRefs||[];if(!gds.length||gds.some(g=>!String(g.number||'').trim()||!/\d{4}-\d{2}-\d{2}/.test(String(g.date||''))))missing.push('GD number and date');else if(!s.customs?.gdDocument||s.customs.gdDocument.gdRefsFingerprint!==gdRefsFingerprint(gds))missing.push('Goods Declaration (GD) file matching the saved GD number(s) and date(s)');if(!s.bl?.finalized||!s.bl?.finalDocument||!s.bl?.blNo||!s.bl?.onBoardDate)missing.push('Final / Original B/L file, number and date');if(!s.commercial?.saved)missing.push('Commercial master');if(s.seller==='TG'&&!s.tgdocs?.saved)missing.push('reviewed TG / Pakistan settlement pack');if(/certificate of origin|\bcoo\b/i.test([...(c.docs||[]),...(s.lc?.documents||[])].join(' '))&&!s.coo?.finalDocument)missing.push('completed Certificate of Origin');for(const type of requiredFinalCertificateTypes(s,c))if(!hasFinalCertificate(s,type))missing.push(`completed ${type} certificate`);const requiredDispatchDocs=(lcApplies(s,c)&&s.lc?.documents?.length?s.lc.documents:documentsPresented(c).filter(row=>num(row.original)>0).map(row=>row.name)).filter(name=>!isLcControlFieldLine(name));if(!s.covering?.dispatched||!s.covering?.frozen)missing.push('completed and frozen document dispatch');else if(requiredDispatchDocs.some(name=>num(s.covering?.documentCounts?.[name]?.originals)<=0))missing.push('original dispatch quantity for every required document');return missing}
document.addEventListener('click',e=>{if(e.target?.id==='cancelLot'){e.preventDefault();e.stopImmediatePropagation();const s=shipment(),reason=s&&requiredReason(`Mandatory reason for cancelling ${s.contractRef} · ${s.lotId}:`);if(!s||!reason)return;s.cancelled=true;s.cancelReason=reason;s.cancelledAt=new Date().toISOString();s.cancelledBy=currentUser();s.status='Cancelled';audit('Lot','Cancelled',`${s.contractRef} · ${s.lotId} · ${reason}`);view='home';render();return}if(e.target?.id==='completeLot'){e.preventDefault();e.stopImmediatePropagation();const s=shipment(),c=s&&contractByRef(s.contractRef);if(!s||!c)return;const missing=completionMissing(s,c);if(missing.length)return alert('Cannot complete lot. Missing: '+missing.join(', '));s.completed=true;s.status='Completed';const p=processFor(s),valid=lotsFor(p).filter(l=>!l.cancelled),allocated=valid.reduce((a,l)=>a+num(l.plannedQty),0);if(valid.length&&valid.every(l=>l.completed)&&allocated+.001>=num(p.plannedQty)*(1-num(c.tolerance)/100)){p.completed=true;p.status='Completed';c.status='Completed'}audit('Lot','Completed after all gates passed',`${s.contractRef} · ${s.lotId}`);view='home';render()}},true);
document.addEventListener('click',e=>{if(e.target?.id!=='saveCustoms')return;const box=document.getElementById('cuGD'),lines=box?box.value.split('\n').map(v=>v.trim()).filter(Boolean):[];const invalid=lines.find(line=>{const [number,date]=line.split('|').map(v=>v.trim());return!number||!/^\d{4}-\d{2}-\d{2}$/.test(date||'')});if(invalid){e.preventDefault();e.stopImmediatePropagation();return alert('Enter each GD as GD NUMBER | YYYY-MM-DD. Both number and date are required.')}setTimeout(()=>{const s=shipment();if(!s?.customs)return;s.customs.gdRefs=lines.map(line=>{const [number,date]=line.split('|').map(v=>v.trim());return{number,date}});save()},0)},true);
document.addEventListener('focusin',e=>{if(e.target?.id==='cuGD'){const label=e.target.closest('.field')?.querySelector('label');if(label)label.textContent='GD References — one per line: GD NUMBER | YYYY-MM-DD'}if(e.target?.id==='cvDocs')e.target.readOnly=true});
document.addEventListener('click',e=>{if(e.target?.id!=='sendLoading')return;const p=shipment(),count=num(p?.loading?.draft?.physicalContainers);if(count<=0||!Number.isInteger(count)){e.preventDefault();e.stopImmediatePropagation();setLoadingFeedback('loadingFeedback','Physical Containers must be a positive whole number. Use fractional shares only in the loading-source rows.')}},true);
document.addEventListener('click',e=>{if(e.target?.id!=='saveContractImport')return;const c=[...state.contracts].reverse().find(x=>x.sourceDocument?.type==='Customer Contract');if(!c)return;c.signedDeadline=addDays(c.date,2);c.paymentDeadline=addBankDays(c.date,String(c.paymentCode).startsWith('LC_')?5:4);const p=state.shipments.find(s=>s.kind!=='lot'&&s.contractRef===c.ref);if(p)p.paymentDeadline=c.paymentDeadline;save()});





function combinedLotRecord(lots,c){const first=structuredClone(lots[0]),all=x=>[...new Map(lots.flatMap(l=>(l.customs?.[x]||[])).map(v=>[JSON.stringify(v),v])).values()];first.id='COMBINED';first.lotId=lots.map(l=>l.lotId).join(' + ');first.plannedQty=lots.reduce((a,l)=>a+num(l.plannedQty),0);first.containers=lots.reduce((a,l)=>a+num(l.containers),0);first.millActuals=lots.flatMap(l=>l.millActuals||[]);first.customs.fiAllocations=all('fiAllocations');first.customs.gdRefs=all('gdRefs');first.customs.invoiceNo=lots.map(l=>l.customs.invoiceNo).filter(Boolean).join(' / ');first.commercial.invoiceNo=lots.map(l=>l.commercial.invoiceNo).filter(Boolean).join(' / ');first.bl.blNo=lots.map(l=>l.bl.blNo).filter(Boolean).join(' / ');first.covering.docs=[...new Set(lots.flatMap(l=>l.covering.docs||[]))];return first}
function openCombineLots(base){const eligible=state.shipments.filter(l=>l.kind==='lot'&&!l.cancelled&&l.contractRef===base.contractRef&&l.customs?.saved);openModal('Combine Lots / GDs',eligible.length>=2?`<div class="notice">Select two or more lots from the same contract. The combined output reuses each lot's Mill actuals, FI and GD references without changing the individual lot records.</div><div class="checklist">${eligible.map(l=>`<label class="checkItem"><input type="checkbox" data-combine-lot="${esc(l.id)}" ${l.id===base.id?'checked':''}> ${esc(l.lotId)} · ${num(l.plannedQty).toFixed(3)} MT · ${(l.customs.gdRefs||[]).map(x=>esc(x.number||x)).join(', ')||'No GD'}</label>`).join('')}</div>`:`<div class="notice warn">At least two saved Customs masters are required under this contract before lots/GDs can be combined.</div>`,eligible.length>=2?`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="printCombinedLots">PRINT COMBINED SET</button>`:`<button class="btn" data-modal-close>Close</button>`);document.getElementById('printCombinedLots')?.addEventListener('click',()=>{const selected=[...document.querySelectorAll('[data-combine-lot]:checked')].map(x=>state.shipments.find(l=>l.id===x.dataset.combineLot)).filter(Boolean);if(selected.length<2)return alert('Select at least two lots.');const c=contractByRef(base.contractRef),combined=combinedLotRecord(selected,c),html=commercialInvoiceDoc(combined,c,false)+packingListDoc(combined,c,false)+commercialInvoiceDoc(combined,c,true)+packingListDoc(combined,c,true)+coveringDoc(combined,c);closeModal();printShipmentDoc('COMBINED LOT / GD DOCUMENT SET',html,c.seller)})}

function tgInternalDoc(s,c){const pc={...pakistanCustomsContext(s,c),paymentCode:'INTERCOMPANY'},t=actualTotals(s,c),rate=num(s.customs.rate),fi=(s.customs.fiAllocations||[]).map(v=>v.number||v).filter(Boolean).join(', '),gd=(s.customs.gdRefs||[]).map(v=>v.number||v).filter(Boolean).join(', ');return pageDoc(pc,'TG / PAKISTAN SETTLEMENT CONTROL',`${partyGrid(pc)}<div class="notice"><b>Same physical shipment:</b> ${esc(s.contractRef)} · ${esc(s.lotId)}</div><table class="docMeta"><tr><td class="lbl">Pakistan Exporter</td><td>${esc(SELLERS[pakistanExporterKey(s)])}</td></tr><tr><td class="lbl">Importer</td><td>${esc(SELLERS.TG)}</td></tr><tr><td class="lbl">Quantity</td><td>${t.mt.toFixed(3)} MTONS</td></tr><tr><td class="lbl">Intercompany Rate</td><td>${money(rate,c.currency)} / MT</td></tr><tr><td class="lbl">Pakistan-side Value</td><td>${money(t.mt*rate,c.currency)}</td></tr><tr><td class="lbl">FI Reference(s)</td><td>${esc(fi||'OPEN ACCOUNT / NOT YET ALLOCATED')}</td></tr><tr><td class="lbl">GD Reference(s)</td><td>${esc(gd||'PENDING')}</td></tr><tr><td class="lbl">Pakistan Bank / IBAN</td><td>${esc(s.customs.bank||'PENDING')}${s.customs.iban?` · ${esc(s.customs.iban)}`:''}</td></tr></table><p>The physical packing, container and seal allocation is identical to this lot. The TG → final-customer sales price and receipts remain in the TG customer pack and are not used in this Pakistan settlement pack.</p>${signature(pc)}`)}
function renderTG(d){const s=shipment(),c=contractByRef(s.contractRef),t=actualTotals(s,c),fi=(s.customs.fiAllocations||[]).map(v=>v.number||v).filter(Boolean).join(', '),gd=(s.customs.gdRefs||[]).map(v=>v.number||v).filter(Boolean).join(', ');d.innerHTML=`<div class="section"><h3>TG DOCUMENTS — TWO LINKED LEGAL PACKS</h3><div class="notice red"><b>Locked separation:</b> TG → final buyer documents use the Sales Contract price. ${esc(SELLERS[pakistanExporterKey(s)])} → TG documents use only the intercompany rate and Pakistan FI/GD/bank references.</div><div class="grid3"><div class="field"><label>Pakistan Exporter / Letterhead</label><select id="tgExporter"><option value="TTI" ${pakistanExporterKey(s)==='TTI'?'selected':''}>${esc(SELLERS.TTI)}</option><option value="BRM" ${pakistanExporterKey(s)==='BRM'?'selected':''}>${esc(SELLERS.BRM)}</option></select></div><div class="field"><label>Physical Shipment</label><input readonly value="${esc(s.contractRef)} · ${esc(s.lotId)} · ${t.mt.toFixed(3)} MT"></div><div class="field"><label>Intercompany Rate / MT</label><input id="tgRate" type="number" step=".01" value="${num(s.customs.rate)}"></div><div class="field"><label>Pakistan Bank</label><input id="tgBank" value="${esc(s.customs.bank||'')}"></div><div class="field"><label>Pakistan IBAN</label><input id="tgIBAN" value="${esc(s.customs.iban||'')}"></div><div class="field"><label>FI / GD Control</label><input readonly value="FI: ${esc(fi||'None')} · GD: ${esc(gd||'None')}"></div></div><div class="cards"><div class="card"><b>TG → Final Buyer Pack</b><p class="meta">TG Sales Contract, Commercial Invoice/Packing List, buyer L/C documents and TG bank covering at the customer price.</p><button class="btn green" id="printTGCustomer">PRINT TG CUSTOMER PACK</button></div><div class="card"><b>${esc(SELLERS[pakistanExporterKey(s)])} → TG Pakistan Pack</b><p class="meta">Custom/intercompany invoice, packing list, settlement control and Pakistan bank covering at the reduced intercompany rate.</p><button class="btn navy" id="printTGPakistan">SAVE & PRINT PAKISTAN PACK</button></div></div></div>`;document.getElementById('tgExporter').onchange=e=>{s.customs.exporter=e.target.value;s.customs.saved=false;s.tgdocs={...(s.tgdocs||{}),saved:false};renderShipmentWorkspace()};document.getElementById('tgRate').oninput=e=>{s.customs.rate=num(e.target.value);s.customs.saved=false;s.tgdocs={...(s.tgdocs||{}),saved:false}};document.getElementById('tgBank').oninput=e=>{s.customs.bank=e.target.value;s.customs.saved=false};document.getElementById('tgIBAN').oninput=e=>{s.customs.iban=e.target.value;s.customs.saved=false};document.getElementById('printTGCustomer').onclick=()=>printShipmentDoc('TG CUSTOMER DOCUMENT PACK',commercialInvoiceDoc(s,c,false)+packingListDoc(s,c,false)+(lcApplies(s,c)?lcControlDoc(s,c)+lcDraftDoc(s,c)+lcDraftDoc(s,c):''),c.seller);document.getElementById('printTGPakistan').onclick=()=>{if(num(s.customs.rate)<=0)return alert('Enter the Pakistan Exporter → Trans Grains intercompany rate.');if(!customsBalanced(s,c))return alert('Save the currently balanced Customs master after selecting the exporter, rate, bank, IBAN and FI/Open Account split.');s.tgdocs={saved:true,at:new Date().toISOString(),exporter:pakistanExporterKey(s),rate:num(s.customs.rate),customsInvoiceNo:s.customs.invoiceNo};audit('TG Documents','Two-pack TG settlement prepared',`${s.contractRef} · ${s.lotId} · ${pakistanExporterKey(s)}`);printShipmentDoc('PAKISTAN EXPORTER TO TG DOCUMENT PACK',commercialInvoiceDoc(s,c,true).replaceAll('CUSTOM INVOICE','INTERCOMPANY / CUSTOM INVOICE')+packingListDoc(s,c,true).replaceAll('CUSTOM PACKING LIST','INTERCOMPANY / CUSTOM PACKING LIST')+tgInternalDoc(s,c)+tgPakistanCoveringDoc(s,c),pakistanExporterKey(s))}}

function fiUsed(f){return(f.allocations||[]).reduce((a,x)=>a+num(x.amount),0)}
function fiReference(f){return{fiId:f.id,number:f.number,amount:0,currency:f.currency,bank:f.bank||'',lcNo:f.lcNo||'',lcDate:f.lcDate||''}}
function openFIModal(){openModal('Generate / Insert FI',`<div class="grid3"><div class="field"><label>FI No.</label><input id="mFINo" value="FI-${new Date().getFullYear()}-${String(state.fi.length+1).padStart(4,'0')}"></div><div class="field"><label>Date</label><input id="mFIDate" type="date" value="${TODAY()}"></div><div class="field"><label>Customer</label><select id="mFICustomer"><option value="">Select customer</option>${state.customers.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Type</label><select id="mFIType"><option>Advance</option><option>L/C</option><option>Open Account</option><option>TG Unallocated</option></select></div><div class="field"><label>Bank</label><input id="mFIBank"></div><div class="field"><label>Currency</label><select id="mFICur">${['USD','EUR','GBP','AED','PKR'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>Total Value</label><input id="mFIValue" type="number" step=".01"></div><div class="field"><label>L/C No. (required for L/C FI)</label><input id="mFILC"></div><div class="field"><label>L/C Date</label><input id="mFILCDate" type="date"></div><div class="field full"><label>Payment Terms / Reference</label><input id="mFIPayment"></div></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveFI">SAVE FI</button>`);document.getElementById('saveFI').onclick=()=>{const no=document.getElementById('mFINo').value.trim(),value=num(document.getElementById('mFIValue').value),type=document.getElementById('mFIType').value,customerName=type==='TG Unallocated'?SELLERS.TG:document.getElementById('mFICustomer').value,lcNo=document.getElementById('mFILC').value.trim();if(!no||!customerName||value<=0)return alert('FI number, customer and positive value are required.');if(type==='L/C'&&!lcNo)return alert('L/C Number is required for an L/C FI.');if(state.fi.some(f=>f.number.toLowerCase()===no.toLowerCase()))return alert('FI number already exists.');state.fi.push({id:uid('FI'),number:no,date:document.getElementById('mFIDate').value,customer:customerName,type,bank:document.getElementById('mFIBank').value.trim(),currency:document.getElementById('mFICur').value,value,lcNo,lcDate:document.getElementById('mFILCDate').value,paymentTerms:document.getElementById('mFIPayment').value.trim(),allocations:[],createdAt:new Date().toISOString()});audit('FI Register','FI generated',no);closeModal();view='fi';renderFI()}}
function openFIAllocation(id){const f=state.fi.find(x=>x.id===id),available=num(f.value)-fiUsed(f),eligible=state.shipments.filter(l=>l.kind==='lot'&&!l.cancelled&&!l.completed&&(l.buyer===f.customer||(f.type==='TG Unallocated'&&l.seller==='TG'))&&contractByRef(l.contractRef)?.currency===f.currency);openModal('Allocate FI — '+f.number,eligible.length?`<div class="notice"><b>Available:</b> ${money(available,f.currency)}. The selected FI will appear automatically in all documents for the lot.</div><div class="grid2"><div class="field"><label>Lot</label><select id="faLot">${eligible.map(l=>`<option value="${esc(l.id)}">${esc(l.contractRef)} · ${esc(l.lotId)} · ${num(l.plannedQty).toFixed(3)} MT</option>`).join('')}</select></div><div class="field"><label>Amount</label><input id="faAmount" type="number" step=".01" max="${available}"></div></div>`:`<div class="notice warn">No open lot matches this FI customer and currency.</div>`,eligible.length?`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveFIAllocation">ALLOCATE</button>`:`<button class="btn" data-modal-close>Close</button>`);document.getElementById('saveFIAllocation')?.addEventListener('click',()=>{const lot=state.shipments.find(x=>x.id===document.getElementById('faLot').value),amount=num(document.getElementById('faAmount').value);if(!lot||amount<=0||amount>available+.001)return alert('Enter an amount within the available FI balance.');const allocation={id:uid('FIA'),lotId:lot.id,contractRef:lot.contractRef,lotRef:lot.lotId,amount,at:new Date().toISOString()};f.allocations=f.allocations||[];f.allocations.push(allocation);lot.customs.fiAllocations=lot.customs.fiAllocations||[];const ref=fiReference(f);ref.amount=amount;ref.allocationId=allocation.id;lot.customs.fiAllocations.push(ref);lot.customs.bank=lot.customs.bank||f.bank;lot.customs.openAccount=null;lot.customs.saved=false;audit('FI Allocation','Allocated to lot; Customs payment control reopened',`${f.number} · ${lot.contractRef} · ${lot.lotId} · ${money(amount,f.currency)}`);closeModal();renderFI()})}
function removeFIAllocation(fiId,allocationId){const f=state.fi.find(x=>x.id===fiId),a=f?.allocations?.find(x=>x.id===allocationId);if(!f||!a)return;if(!confirm(`Remove ${f.number} allocation from ${a.contractRef} · ${a.lotRef}?`))return;f.allocations=f.allocations.filter(x=>x.id!==allocationId);const lot=state.shipments.find(x=>x.id===a.lotId);if(lot?.customs){lot.customs.fiAllocations=(lot.customs.fiAllocations||[]).filter(x=>x.allocationId!==allocationId);lot.customs.openAccount=null;lot.customs.saved=false}audit('FI Allocation','Removed from lot; Customs payment control reopened',`${f.number} · ${a.contractRef} · ${a.lotRef}`);renderFI()}
function openFIEdit(id){const f=state.fi.find(x=>x.id===id);if(!f)return;const used=fiUsed(f);openModal('Controlled FI Amendment — '+f.number,`<div class="notice">Allocated value is protected. Customer/currency cannot change while allocations exist, and total cannot be reduced below ${money(used,f.currency)}.</div><div class="grid3"><div class="field"><label>FI No.</label><input id="efNo" value="${esc(f.number)}"></div><div class="field"><label>Date</label><input id="efDate" type="date" value="${f.date}"></div><div class="field"><label>Customer</label><input id="efCustomer" value="${esc(f.customer)}" ${used?'readonly':''}></div><div class="field"><label>Bank</label><input id="efBank" value="${esc(f.bank||'')}"></div><div class="field"><label>Currency</label><input id="efCurrency" value="${esc(f.currency)}" ${used?'readonly':''}></div><div class="field"><label>Total Value</label><input id="efValue" type="number" step=".01" value="${num(f.value)}"></div><div class="field"><label>L/C No.</label><input id="efLC" value="${esc(f.lcNo||'')}"></div><div class="field"><label>L/C Date</label><input id="efLCDate" type="date" value="${f.lcDate||''}"></div><div class="field full"><label>Payment Terms</label><input id="efTerms" value="${esc(f.paymentTerms||'')}"></div><div class="field full"><label>Mandatory amendment reason</label><textarea id="efReason"></textarea></div></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveFIEdit">SAVE AMENDMENT</button>`);document.getElementById('saveFIEdit').onclick=()=>{const number=efNo.value.trim(),value=num(efValue.value),reason=efReason.value.trim();if(!number||value<used-.001||!reason)return alert('FI number, valid total and amendment reason are required. Total cannot be below the allocated value.');if(state.fi.some(x=>x.id!==f.id&&x.number.toLowerCase()===number.toLowerCase()))return alert('FI number already exists.');snapshot(f,reason,'FI amended');Object.assign(f,{number,date:efDate.value,customer:efCustomer.value.trim(),bank:efBank.value.trim(),currency:efCurrency.value.trim().toUpperCase(),value,lcNo:efLC.value.trim(),lcDate:efLCDate.value,paymentTerms:efTerms.value.trim(),updatedAt:new Date().toISOString(),updatedBy:currentUser()});for(const lot of state.shipments){for(const ref of lot.customs?.fiAllocations||[])if(ref.fiId===f.id){Object.assign(ref,{number:f.number,currency:f.currency,bank:f.bank,lcNo:f.lcNo,lcDate:f.lcDate});lot.customs.saved=false}}audit('FI Register','FI amended',`${f.number} · ${reason}`);closeModal();renderFI()}}
function openFITransfer(id){const from=state.fi.find(x=>x.id===id),available=from?num(from.value)-fiUsed(from):0,targets=state.fi.filter(x=>x.id!==id&&x.customer===from?.customer&&x.currency===from?.currency);if(!from)return;openModal('Transfer FI Balance — '+from.number,targets.length?`<div class="notice">Only unallocated balance may be transferred. Available: ${money(available,from.currency)}.</div><div class="grid2"><div class="field"><label>Transfer To</label><select id="tfTarget">${targets.map(x=>`<option value="${esc(x.id)}">${esc(x.number)} · available ${money(num(x.value)-fiUsed(x),x.currency)}</option>`).join('')}</select></div><div class="field"><label>Amount</label><input id="tfAmount" type="number" step=".01" max="${available}"></div><div class="field full"><label>Mandatory reason</label><textarea id="tfReason"></textarea></div></div>`:`<div class="notice warn">Create another FI for the same customer and currency before transferring an unallocated balance.</div>`,targets.length?`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveTransfer">TRANSFER BALANCE</button>`:`<button class="btn" data-modal-close>Close</button>`);document.getElementById('saveTransfer')?.addEventListener('click',()=>{const to=state.fi.find(x=>x.id===tfTarget.value),amount=num(tfAmount.value),reason=tfReason.value.trim();if(!to||amount<=0||amount>available+.001||!reason)return alert('Enter a valid amount and mandatory reason.');snapshot(from,reason,'Balance transferred out');snapshot(to,reason,'Balance transferred in');from.value=num(from.value)-amount;to.value=num(to.value)+amount;const tx={id:uid('FIT'),at:new Date().toISOString(),by:currentUser(),fromId:from.id,from:from.number,toId:to.id,to:to.number,amount,currency:from.currency,reason};from.transfers=[...(from.transfers||[]),tx];to.transfers=[...(to.transfers||[]),tx];audit('FI Transfer','Unallocated balance transferred',`${from.number} → ${to.number} · ${money(amount,from.currency)} · ${reason}`);closeModal();renderFI()})}
function lcRegisterRows(){const rows=[];for(const p of processes().filter(x=>x.lc?.saved))rows.push({lcNo:p.lc.lcNo,date:p.lc.lcDate,contract:p.contractRef,customer:p.buyer,bank:p.lc.issuingBank||p.lc.advisingBank,currency:p.lc.currency||contractByRef(p.contractRef)?.currency,value:p.lc.amount||0,status:'Reviewed L/C Master'});for(const f of state.fi.filter(x=>x.type==='L/C'||x.lcNo)){const key=String(f.lcNo||'').trim().toLowerCase(),row=rows.find(r=>String(r.lcNo||'').trim().toLowerCase()===key);if(row)Object.assign(row,{date:f.lcDate||row.date,customer:row.customer||f.customer,bank:row.bank||f.bank,currency:row.currency||f.currency,value:num(row.value)||num(f.value),status:'FI Linked'});else rows.push({lcNo:f.lcNo,date:f.lcDate,contract:'',customer:f.customer,bank:f.bank,currency:f.currency,value:f.value,status:'FI Linked'})}return rows}
