function renderHome(){const ps=processes().filter(p=>!p.cancelled&&!p.completed),lots=state.shipments.filter(s=>s.kind==='lot'&&!s.cancelled&&!s.completed),updates=(state.alerts||[]).filter(a=>!a.seen);document.getElementById('main').innerHTML=`<div class="homeLead"><div><h2>Exports</h2><div class="metaText">Contract-centred export operations and shipment documentation</div><label class="searchLabel">SEARCH ACTIVE SHIPMENTS<input id="homeSearch" placeholder="Customer / Contract / Lot / B/L / Container"></label></div><div class="homeActions"><button class="btn green" id="addFIHome">+ FI</button><button class="btn green" id="newContract">+ NEW SALES CONTRACT</button><div class="summaryRow"><div class="summaryBox"><span>Active Contracts</span><b>${ps.length}</b></div><div class="summaryBox"><span>Active Lots</span><b>${lots.length}</b></div><div class="summaryBox millHover" tabindex="0"><span>Mill Updates</span><b>${updates.length}</b><div class="millPopover">${updates.length?updates.slice(0,8).map(a=>`<div><b>${esc(a.contractRef||'Mill')}</b><br>${esc(a.message||a.detail||'Update received')}</div>`).join(''):'No unread Mill updates.'}</div></div></div></div></div><div class="oldCards" id="activeCards">${ps.map(processCard).join('')||'<div class="panel">No active shipments.</div>'}</div>`;document.getElementById('newContract').onclick=()=>startContract();document.getElementById('addFIHome').onclick=openFIModal;document.getElementById('homeSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-search-card]').forEach(x=>x.hidden=!x.dataset.searchCard.includes(q))};wireShipmentCards()}
