function renderContractWorkspace(d){const p=shipment(),c=contractByRef(p.contractRef),lcNeeded=String(c.paymentCode).startsWith('LC_');d.innerHTML=`<div class="section"><div class="toolbar"><div><h3>Sales Contract</h3><div class="metaText">${esc(c.status)} · ${fmt(c.date)}</div></div><div class="spacer"></div><button class="btn soft" id="amendContract">OPEN / AMEND CONTRACT</button><button class="btn green" id="markReceived">${c.received?'CONTRACT RECEIVED ✓':'MARK SIGNED CONTRACT RECEIVED'}</button></div>${lcNeeded?`<div class="notice ${p.lc?.saved?'':'warn'}"><b>L/C Master:</b> ${p.lc?.saved?esc(p.lc.lcNo)+' · reviewed and controlling all lot documents':'Required by payment terms and not yet uploaded'} <button class="btn small green" id="lcUploadHere">${p.lc?.saved?'REPLACE / REVIEW L/C':'UPLOAD L/C'}</button></div>`:''}</div>`;document.getElementById('amendContract').onclick=()=>openContract(c.id);document.getElementById('markReceived').onclick=()=>{c.received=true;c.status='Contract Received';p.status='Contract Received';p.next='Bag Order / Production';audit('Sales Contract','Signed contract received',c.ref);renderShipmentWorkspace()};document.getElementById('lcUploadHere')?.addEventListener('click',()=>openLCUpload(p.id))}
function loadingRemainingByPack(p,c){const issued=lotsFor(p).filter(x=>!x.cancelled);return c.packings.map((pk,i)=>{const used=issued.flatMap(x=>x.loadingPlan?.allocations||[]).filter(a=>num(a.packIndex)===i).reduce((sum,a)=>sum+num(a.containers),0);return Math.max(0,num(pk.containers)-used)})}
