const renderLoadingBase=renderLoading;
renderLoading=function(d){renderLoadingBase(d);const p=shipment(),draft=p.loading.draft,issued=lotsFor(p).filter(l=>!l.cancelled);if(draft){if(!draft.physicalContainers)draft.physicalContainers=Math.ceil(draft.allocations.reduce((sum,a)=>sum+num(a.containers),0));d.querySelectorAll('[data-li-cont]').forEach(input=>{input.step='.001';input.title='Use a fractional share when one physical container receives cargo from multiple locations.'});const head=d.querySelector('.grid3');head?.insertAdjacentHTML('beforeend',`<div class="field"><label>Physical Containers</label><input id="liPhysicalContainers" type="number" min="1" step="1" value="${num(draft.physicalContainers)}"><div class="metaText">Source rows may use fractional shares (for example 0.500 + 0.500) when one physical container is filled from multiple locations.</div></div>`);document.getElementById('liPhysicalContainers').oninput=e=>draft.physicalContainers=num(e.target.value)}if(!issued.length)return;d.insertAdjacentHTML('beforeend',`<div class="section"><h3>ISSUED LOADING INSTRUCTIONS</h3><div class="notice">Reissue the same lot reference with a mandatory reason. Previous versions remain in history and the exact Mill handoff is replaced, not duplicated.</div>${issued.map(l=>`<div class="notice"><b>${esc(p.contractRef)} · ${esc(l.lotId)}</b> · ${num(l.plannedQty).toFixed(3)} MT · ${num(l.containers)} physical container(s) · ${loadingSourceSummary(l.loadingPlan?.allocations||[])} <button class="btn small amber" data-reissue-loading="${esc(l.id)}" ${(l.millActuals||[]).length?'disabled title="Mill actuals already received"':''}>Reallocate / Reissue</button></div>`).join('')}</div>`);document.querySelectorAll('[data-reissue-loading]').forEach(b=>b.onclick=()=>openLoadingReissue(b.dataset.reissueLoading))};
function openLoadingReissue(lotId){const lot=state.shipments.find(x=>x.id===lotId),p=processFor(lot),c=lot&&contractByRef(lot.contractRef);if(!lot||!p||!c)return;if((lot.millActuals||[]).length)return alert('Loading Instructions cannot be reissued after Mill actuals arrive. Use a documented Mill correction against the same container instead.');const draft=structuredClone(lot.loadingPlan),locations=millLocations();openModal('Reallocate / Reissue Loading Instructions — '+lot.contractRef+' · '+lot.lotId,`<div class="notice">The lot identity remains unchanged. Adjust locations and contributions; the total lot quantity must remain ${num(lot.plannedQty).toFixed(3)} MT.</div><datalist id="reissueLocations">${locations.map(x=>`<option value="${esc(x.name)}">`).join('')}</datalist><div class="tableWrap"><table class="table"><thead><tr><th>Packing</th><th>Loading From</th><th>Type</th><th>Containers / Contributions</th><th>MT / Container</th></tr></thead><tbody>${draft.allocations.map((a,i)=>`<tr><td>${esc(c.packings[num(a.packIndex)]?.brand||'Packing '+(num(a.packIndex)+1))}</td><td><input list="reissueLocations" data-ri-name="${i}" value="${esc(a.name)}"></td><td><select data-ri-type="${i}"><option ${a.type==='TTI'?'selected':''}>TTI</option><option ${a.type==='Ex-Mill'?'selected':''}>Ex-Mill</option><option ${a.type==='Reprocessing'?'selected':''}>Reprocessing</option></select></td><td><input data-ri-cont="${i}" type="number" value="${num(a.containers)}"></td><td><input data-ri-weight="${i}" type="number" step=".001" value="${num(a.weightPer)}"></td></tr>`).join('')}</tbody></table></div><div id="reissueFeedback" class="notice red hidden" role="status" aria-live="polite"></div><div class="field"><label>Mandatory reissue reason</label><textarea id="riReason"></textarea></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveReissue">REISSUE SAME LOADING INSTRUCTION</button>`);document.getElementById('saveReissue').onclick=()=>{draft.allocations.forEach((a,i)=>{a.name=document.querySelector(`[data-ri-name="${i}"]`).value.trim();a.type=document.querySelector(`[data-ri-type="${i}"]`).value;a.containers=num(document.querySelector(`[data-ri-cont="${i}"]`).value);a.weightPer=num(document.querySelector(`[data-ri-weight="${i}"]`).value)});const reason=riReason.value.trim(),normalized=normalizeLoadingAllocations(draft.allocations),total=normalized.reduce((sum,a)=>sum+num(a.containers)*num(a.weightPer),0),typeIssue=loadingLocationIssue(normalized,locations);if(!reason||normalized.some(a=>!a.name||a.containers<=0||a.weightPer<=0))return setLoadingFeedback('reissueFeedback','Complete all allocations and enter the mandatory reason.');if(typeIssue)return setLoadingFeedback('reissueFeedback',typeIssue);if(Math.abs(total-num(lot.plannedQty))>.001)return setLoadingFeedback('reissueFeedback','Reissued allocation total must equal the existing lot quantity.');draft.allocations=normalized;snapshot(lot.loadingPlan,reason,'Loading Instructions reissued');draft.reissuedAt=new Date().toISOString();draft.reissuedBy=currentUser();draft.reissueReason=reason;lot.loadingPlan=draft;lot.loadingVersions=[...(lot.loadingVersions||[]),{at:draft.reissuedAt,by:currentUser(),reason,plan:structuredClone(draft)}];const summary=p.loading.lots.find(x=>x.lotRecordId===lot.id);if(summary){summary.plan={allocations:structuredClone(draft.allocations),loadingProgrammeNo:draft.loadingProgrammeNo||lot.loadingProgrammeNo,intendedVessel:draft.intendedVessel||'',shippingLine:draft.shippingLine||''};summary.loadingProgrammeNo=draft.loadingProgrammeNo||lot.loadingProgrammeNo;summary.intendedVessel=draft.intendedVessel||'';summary.shippingLine=draft.shippingLine||'';summary.reissuedAt=draft.reissuedAt}state.millSync.exportLoading=state.millSync.exportLoading.filter(x=>x.shipmentId!==lot.id);state.millSync.exportLoading.push({contractRef:p.contractRef,shipmentId:lot.id,processId:p.id,lotId:lot.lotId,loadingProgrammeNo:draft.loadingProgrammeNo||lot.loadingProgrammeNo,intendedVessel:draft.intendedVessel||'',shippingLine:draft.shippingLine||'',plan:{allocations:structuredClone(draft.allocations),loadingProgrammeNo:draft.loadingProgrammeNo||lot.loadingProgrammeNo,intendedVessel:draft.intendedVessel||'',shippingLine:draft.shippingLine||''},production:structuredClone(p.production),sentAt:draft.reissuedAt,reissue:true,reason});for(const a of draft.allocations)registerMillLocation(a.name,a.type);audit('LOADING INSTRUCTIONS','Reallocated and reissued same lot',`${p.contractRef} · ${lot.lotId} · ${reason}`);closeModal();renderShipmentWorkspace()}}

function nextLoadingProgrammeNo(){const yy=new Intl.DateTimeFormat('en',{timeZone:'Asia/Karachi',year:'2-digit'}).format(new Date()),prefix=`LP-${yy}-`;let max=0;for(const row of [...(state.shipments||[]),...(state.millSync?.exportLoading||[])]){const value=String(row?.loadingProgrammeNo||row?.loadingPlan?.loadingProgrammeNo||'');if(!value.startsWith(prefix))continue;const sequence=Number(value.slice(prefix.length));if(Number.isInteger(sequence))max=Math.max(max,sequence)}return prefix+String(max+1).padStart(4,'0')}
const renderLoadingWithProgramme=renderLoading;
renderLoading=function(d){renderLoadingWithProgramme(d);const p=shipment(),draft=p?.loading?.draft;if(draft){if(!draft.loadingProgrammeNo)draft.loadingProgrammeNo=nextLoadingProgrammeNo();const head=d.querySelector('.grid3');head?.insertAdjacentHTML('afterbegin',`<div class="field"><label>Loading Programme No.</label><input value="${esc(draft.loadingProgrammeNo)}" readonly><div class="metaText">System reference shared with Mill, Transport and Accounts.</div></div>`);const button=d.querySelector('#sendLoading'),original=button?.onclick,programme=draft.loadingProgrammeNo;if(button&&original)button.onclick=async event=>{const before=new Set(lotsFor(p).map(x=>x.id));await original.call(button,event);const lot=lotsFor(p).find(x=>!before.has(x.id));if(!lot||lot.loadingProgrammeNo)return;lot.loadingProgrammeNo=programme;lot.loadingPlan=lot.loadingPlan||{};lot.loadingPlan.loadingProgrammeNo=programme;const summary=(p.loading?.lots||[]).find(x=>x.lotRecordId===lot.id);if(summary)summary.loadingProgrammeNo=programme;const handoff=(state.millSync?.exportLoading||[]).find(x=>x.shipmentId===lot.id);if(handoff)handoff.loadingProgrammeNo=programme;audit('LOADING PROGRAMME','Assigned',`${programme} · ${p.contractRef} · ${lot.lotId}`);save();try{const shared=window.TT_SHARED_SYNC?.saveNow?.();if(shared)await shared}catch(error){console.error('Loading Programme shared save',error)}}}for(const button of d.querySelectorAll('[data-reissue-loading]')){const lot=state.shipments.find(x=>x.id===button.dataset.reissueLoading);if(lot?.loadingProgrammeNo&&!button.parentElement.querySelector('.tt-lp-number'))button.insertAdjacentHTML('beforebegin',`<b class="tt-lp-number">${esc(lot.loadingProgrammeNo)}</b> · `)}};

// Lot document workspace — approved September 2026 workflow.
const LOT_DOCUMENT_GROUPS=[
 [['customs','🧾','Customs'],['bl','🚢','B/L Draft'],['commercial','▤','Commercial Invoice'],['coo','◫','Certificate of Origin']],
 [['certs','＋','+ Certificate'],['uploads','⇧','Upload Documents']],
 [['cover','✉','Bank & Dispatch'],['tg','↔','TG Documents'],['lcdraft','🏦','L/C Draft'],['output','▣','Final Output'],['history','◷','History']]
];
const KNOWN_UPLOAD_DOCUMENTS=['Carrier B/L Draft','Final / Original B/L','Certificate of Origin','Phytosanitary Certificate','Fumigation Certificate','Inspection / SGS Certificate','Health Certificate','Insurance Certificate','Laboratory Report','Goods Declaration (GD)','Customer Contract','Contract Amendment','Bank Advice / SWIFT','Custom'];

const upgradeStateBeforeLotDocuments=upgradeState;
upgradeState=function(){upgradeStateBeforeLotDocuments();for(const s of state.shipments){s.uploadedDocuments=Array.isArray(s.uploadedDocuments)?s.uploadedDocuments:[];s.documentActivity=Array.isArray(s.documentActivity)?s.documentActivity:[];if(s.kind==='lot'){s.loadingPlan=s.loadingPlan||{};s.bl=s.bl||{};s.bl.intendedVessel=s.bl.intendedVessel||s.loadingPlan.intendedVessel||'';s.bl.shippingLine=s.bl.shippingLine||s.loadingPlan.shippingLine||''}}save()};

function documentAreaLabel(area){const value=String(area||'').toLowerCase();if(value.includes('custom'))return'Customs';if(value.includes('b/l'))return'B/L Draft';if(value.includes('commercial'))return'Commercial Invoice';if(value.includes('coo')||value.includes('origin'))return'Certificate of Origin';if(value.includes('certificate'))return'Certificate';if(value.includes('upload'))return'Upload Documents';if(value.includes('cover')||value.includes('dispatch'))return'Bank & Dispatch';if(value.includes('tg'))return'TG Documents';if(value.includes('l/c'))return'L/C Draft';return''}
const auditBeforeLotActivity=audit;
audit=function(area,action,detail=''){const s=shipment(),documentName=s?.kind==='lot'?documentAreaLabel(area):'';if(documentName){const at=new Date().toISOString(),completed=/completed|final|original uploaded|dispatched|frozen/i.test(String(action))||(/custom|commercial/i.test(String(area))&&/saved/i.test(String(action)));s.documentActivity=Array.isArray(s.documentActivity)?s.documentActivity:[];s.documentActivity.unshift({at,user:currentUser(),document:documentName,action:String(action||''),completed});s.documentActivity=s.documentActivity.slice(0,80)}return auditBeforeLotActivity(area,action,detail)};

function lotActivitySummary(s){const rows=s.documentActivity||[],last=rows[0],completed=rows.find(x=>x.completed);return`<div class="lotActivity"><div><b>Last work</b><span>${last?`${esc(last.document)} · ${esc(last.user)} · ${new Date(last.at).toLocaleString()}`:'No document work recorded yet'}</span></div><div><b>Last completed</b><span>${completed?`${esc(completed.document)} · ${esc(completed.user)} · ${new Date(completed.at).toLocaleString()}`:'No document completed yet'}</span></div></div>`}

const tileStatusBeforeLotDocuments=tileStatus;
tileStatus=function(k,s){if(k==='certs')return`${(s.certs||[]).filter(x=>x.kind==='generated'||(!x.kind&&!x.finalDocument)).length} prepared`;if(k==='uploads')return`${(s.uploadedDocuments||[]).length+(s.certs||[]).filter(x=>x.finalDocument&&!x.kind).length} uploaded`;return tileStatusBeforeLotDocuments(k,s)};

const renderShipmentWorkspaceBeforeLotDocuments=renderShipmentWorkspace;
renderShipmentWorkspace=function(){const s=shipment();if(!s||s.kind!=='lot')return renderShipmentWorkspaceBeforeLotDocuments();renderNav();const c=contractByRef(s.contractRef);if(!c)return renderShipments();const groups=LOT_DOCUMENT_GROUPS.map(group=>group.filter(([k])=>(k!=='lcdraft'||lcApplies(s,c))&&(k!=='tg'||s.seller==='TG')));const rows=groups.map((group,index)=>{const activeHere=group.some(([k])=>k===activeWorkspace);return`<div class="lotDocumentGroup" data-lot-row="${index}"><div class="lotDocumentIcons">${group.map(([k,icon,label])=>`<button class="lotDocumentIcon ${activeWorkspace===k?'active':''}" data-workspace="${k}" aria-expanded="${activeWorkspace===k}"><span class="lotDocumentGlyph">${icon}</span><span><b>${esc(label)}</b><small>${esc(tileStatus(k,s))}</small></span></button>`).join('')}</div>${activeHere?'<div class="workspaceDetail" id="workspaceDetail"></div>':''}</div>`}).join('');document.getElementById('main').innerHTML=`<button class="backLink" id="backShipments">← Back to Export Home</button><div class="panel workspaceHead"><div><h2>${esc(s.contractRef)} — ${esc(s.lotId)}</h2><div class="metaText">${esc(s.buyer)} · ${num(s.plannedQty).toFixed(3)} MT · ${num(s.containers)} container(s)</div></div><div class="toolbar"><button class="btn soft" id="combineLots">Combine Lots / GDs</button><button class="btn red small" id="cancelLot">Cancel Lot</button></div></div>${lotActivitySummary(s)}<div class="workspacePanel lotWorkspacePanel">${rows}</div>`;document.getElementById('backShipments').onclick=()=>{activeWorkspace='';view='home';render()};document.getElementById('combineLots').onclick=()=>openCombineLots(s);document.querySelectorAll('[data-workspace]').forEach(button=>button.onclick=()=>{activeWorkspace=activeWorkspace===button.dataset.workspace?'':button.dataset.workspace;renderShipmentWorkspace()});renderWorkspaceDetail()};

function bagArtworkFor(s,brand){const p=processFor(s),orders=p?.bagOrders||[];for(let i=orders.length-1;i>=0;i--){const line=(orders[i].lines||[]).find(x=>String(x.brand||'').toLowerCase()===String(brand||'').toLowerCase());if(line?.artworkData)return line.artworkData}return''}
function bagMarkingCell(s,brand){const art=bagArtworkFor(s,brand);return`<div class="docBrand"><b>${esc(brand||'UNBRANDED')}</b>${art?`<img src="${esc(art)}" alt="${esc(brand)} bag marking">`:''}</div>`}
function numberWordsBelowThousand(n){const ones=['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'],tens=['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];if(n<20)return ones[n];if(n<100)return tens[Math.floor(n/10)]+(n%10?'-'+ones[n%10]:'');return ones[Math.floor(n/100)]+' hundred'+(n%100?' '+numberWordsBelowThousand(n%100):'')}
function amountInWords(value,currency){let n=Math.max(0,Math.floor(num(value))),parts=[];for(const [size,name] of [[1000000000,'billion'],[1000000,'million'],[1000,'thousand']])if(n>=size){parts.push(numberWordsBelowThousand(Math.floor(n/size))+' '+name);n%=size}if(n||!parts.length)parts.push(numberWordsBelowThousand(n));const cents=Math.round((num(value)-Math.floor(num(value)))*100);return`${String(currency||'').toUpperCase()} ${parts.join(' ')}${cents?` and ${cents}/100`:''} only`.toUpperCase()}
function loadingProgrammeFor(s){return s.loadingProgrammeNo||s.loadingPlan?.loadingProgrammeNo||''}
function intendedVesselFor(s){return s.loadingPlan?.intendedVessel||s.bl?.intendedVessel||s.bl?.vessel||''}
function shippingLineFor(s){return s.loadingPlan?.shippingLine||s.bl?.shippingLine||''}

commercialInvoiceDoc=function(s,c,custom=false){const dc=custom?customsDocumentContext(s,c):c,x=custom?s.customs:s.commercial,lines=invoiceLines(s,dc,custom),currency=x.currency||dc.currency,total=lines.reduce((sum,line)=>sum+num(line.amount),0),received=custom?0:accountsTotal(s,c),balance=total-received,fi=(s.customs.fiAllocations||[]).map(v=>v.number||v).filter(Boolean).join(', '),gd=(s.customs.gdRefs||[]).map(v=>v.number||v).filter(Boolean).join(', '),title=custom?'CUSTOM / INTERCOMPANY INVOICE':'COMMERCIAL INVOICE';return pageDoc(dc,title,`<div class="invoiceTop"><div><b>INVOICE NO.</b>${esc(x.invoiceNo||dc.ref)}</div><div><b>DATE</b>${fmt(x.date||TODAY())}</div><div><b>CONTRACT</b>${esc(s.contractRef)}</div><div><b>LOT</b>${esc(s.lotId)}</div></div>${partyGrid(dc)}<table class="docMeta"><tr><td class="lbl">Shipment</td><td>${esc(dc.pol)} to ${esc(dc.podPort||dc.destPort)}</td><td class="lbl">B/L</td><td>${esc(s.bl.blNo||'PENDING')} ${s.bl.onBoardDate?'· '+fmt(s.bl.onBoardDate):''}</td></tr>${lcApplies(s,c)?`<tr><td class="lbl">L/C Number / Date</td><td>${esc(s.lc.lcNo)} / ${fmt(s.lc.lcDate)}</td><td class="lbl">Issuing Bank</td><td>${esc(s.lc.issuingBank||'')}</td></tr>`:''}<tr><td class="lbl">Payment Terms</td><td>${esc(custom?s.customs.paymentTerms||paymentText(dc):paymentText(dc))}</td><td class="lbl">FI / GD</td><td>${esc([fi,gd].filter(Boolean).join(' / ')||'—')}</td></tr></table><table class="docTable invoiceGoods"><thead><tr><th>Brand / Bag Marking</th><th>Description of Goods</th><th>Quantity MT</th><th>Rate / MT</th><th>Total</th></tr></thead><tbody>${lines.map(line=>`<tr><td>${bagMarkingCell(s,line.brand)}</td><td><b>${esc(dc.product)}</b><br>${esc(line.packing||'')}<br>${esc(dc.quality||DEFAULT_QUALITY)}</td><td>${num(line.mt).toFixed(3)}</td><td>${esc(currency)} ${num(line.rate).toFixed(2)}</td><td>${esc(currency)} ${num(line.amount).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="2">TOTAL</th><th>${lines.reduce((sum,line)=>sum+num(line.mt),0).toFixed(3)}</th><th></th><th>${esc(currency)} ${total.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</th></tr>${custom?'':`<tr><td colspan="4">Advance received through Accounts</td><td>${esc(currency)} ${received.toLocaleString('en-US',{minimumFractionDigits:2})}</td></tr><tr><th colspan="4">BALANCE PAYABLE</th><th>${esc(currency)} ${balance.toLocaleString('en-US',{minimumFractionDigits:2})}</th></tr>`}</tfoot></table><div class="amountWords"><b>Amount in words:</b> ${esc(amountInWords(custom?total:balance,currency))}</div>${x.bank||x.iban?`<div class="docPartyBox"><b>Bank Details</b>${esc(x.bank||'')}${x.iban?` · IBAN ${esc(x.iban)}`:''}</div>`:''}${signature(dc)}`)};

packingListDoc=function(s,c,custom=false){const dc=custom?customsDocumentContext(s,c):c,t=custom?plannedTotals(s,dc):actualTotals(s,dc),rows=t.rows||[],title=custom?'CUSTOM PACKING LIST':'COMMERCIAL PACKING LIST',groups=new Map();for(const row of rows){const key=[row.brand,row.packing].join('|'),g=groups.get(key)||{brand:row.brand||'',packing:row.packing||'',bags:0,netKg:0,tareKg:0,grossKg:0,containers:0};g.bags+=num(row.bags);g.netKg+=num(row.netKg);g.tareKg+=num(row.tareKg);g.grossKg+=num(row.grossKg||row.netKg);g.containers++;groups.set(key,g)}return pageDoc(dc,title,`<div class="invoiceTop"><div><b>REFERENCE</b>${esc((custom?s.customs.invoiceNo:s.commercial.invoiceNo)||dc.ref)}</div><div><b>DATE</b>${fmt((custom?s.customs.date:s.commercial.date)||TODAY())}</div><div><b>CONTRACT / LOT</b>${esc(s.contractRef)} / ${esc(s.lotId)}</div><div><b>B/L</b>${esc(s.bl.blNo||'PENDING')}</div></div>${partyGrid(dc)}<table class="docMeta"><tr><td class="lbl">Vessel / Voyage</td><td>${esc(s.bl.vessel||intendedVesselFor(s)||'TBA')} / ${esc(s.bl.voyage||'TBA')}</td><td class="lbl">Destination</td><td>${esc(dc.podPort||dc.destPort)}</td></tr></table><table class="docTable packingGoods"><thead><tr><th>Brand / Bag Marking</th><th>Packing</th><th>Containers</th><th>Bags</th><th>Net KG</th><th>Tare KG</th><th>Gross KG</th></tr></thead><tbody>${[...groups.values()].map(row=>`<tr><td>${bagMarkingCell(s,row.brand)}</td><td>${esc(row.packing)}</td><td>${row.containers}</td><td>${row.bags.toLocaleString()}</td><td>${row.netKg.toFixed(3)}</td><td>${row.tareKg.toFixed(3)}</td><td>${row.grossKg.toFixed(3)}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="2">TOTAL</th><th>${num(s.containers)}</th><th>${t.bags.toLocaleString()}</th><th>${t.net.toFixed(3)}</th><th>${t.tare.toFixed(3)}</th><th>${t.gross.toFixed(3)}</th></tr></tfoot></table>${!custom&&rows.length?`<h3 class="docSection">CONTAINER / SEAL DETAILS</h3><table class="docTable"><thead><tr><th>Container</th><th>Seal</th><th>Brand</th><th>Bags</th><th>Net KG</th><th>Gross KG</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.number||'PENDING')}</td><td>${esc(row.seal||'PENDING')}</td><td>${esc(row.brand||'')}</td><td>${num(row.bags).toLocaleString()}</td><td>${num(row.netKg).toFixed(3)}</td><td>${num(row.grossKg||row.netKg).toFixed(3)}</td></tr>`).join('')}</tbody></table>`:''}${signature(dc)}`)};

blDraftDoc=function(s,c){const dc=s.seller==='TG'?pakistanOriginContext(s,c):c,t=actualTotals(s,dc),marks=s.customs.marks||c.packings.map(p=>p.brand).filter(Boolean).join(' / ');return pageDoc(dc,'B/L DRAFT / SHIPPING INSTRUCTIONS',`<div class="blInstructionGrid"><div><b>Loading Programme No.</b>${esc(loadingProgrammeFor(s)||'PENDING')}</div><div><b>Shipping Line</b>${esc(shippingLineFor(s)||'TBA')}</div><div><b>Intended Vessel</b>${esc(intendedVesselFor(s)||'TBA')}</div><div><b>Voyage</b>${esc(s.bl.voyage||'TBA')}</div></div><div class="blParty"><b>SHIPPER</b>${esc(sellerOf(dc).name)}<br>${esc(sellerOf(dc).address)}</div><div class="blParty"><b>CONSIGNEE</b>${esc(s.bl.consignee||'TO ORDER')}</div><div class="blParty"><b>NOTIFY PARTY</b>${esc(s.bl.notify||s.buyer)}</div>${lcDocReference(s,dc)}${lcInstructions(s,dc)}<table class="docMeta"><tr><td class="lbl">Place / Port of Loading</td><td>${esc(dc.pol)}</td><td class="lbl">Port of Discharge</td><td>${esc(dc.podPort||dc.destPort)}</td></tr><tr><td class="lbl">Freight</td><td>${esc(dc.incoterm==='FOB'?'COLLECT':'PREPAID')}</td><td class="lbl">Service</td><td>FCL / FCL</td></tr></table><table class="docTable blGoods"><thead><tr><th>Marks & Numbers</th><th>No. and Kind of Packages</th><th>Description of Goods</th><th>Gross Weight</th><th>Measurement</th></tr></thead><tbody><tr><td><b>${esc(marks||'AS PER SHIPPING MARKS')}</b><br><span class="tinyDocNote">Text marks only — bag artwork is intentionally excluded.</span></td><td>${t.bags.toLocaleString()} BAGS</td><td>${esc(s.bl.description||dc.product)}<br>${esc(dc.quality||DEFAULT_QUALITY)}</td><td>NET ${t.net.toFixed(3)} KG<br>GROSS ${t.gross.toFixed(3)} KG</td><td>AS DECLARED</td></tr></tbody></table><h3 class="docSection">CONTAINER / SEAL NUMBERS</h3><table class="docTable"><tbody>${t.rows.map(row=>`<tr><td>${esc(row.number||'PENDING')}</td><td>${esc(row.seal||'PENDING')}</td><td>${num(row.bags).toLocaleString()} BAGS</td><td>${num(row.netKg).toFixed(3)} KG NET</td></tr>`).join('')}</tbody></table><div class="greenBox"><b>Draft for carrier confirmation only.</b> The carrier-issued draft and final legal B/L must be uploaded separately.</div>${signature(dc)}`)};

const commercialInvoiceDocWithApprovedTitle=commercialInvoiceDoc;
commercialInvoiceDoc=function(s,c,custom=false){let html=commercialInvoiceDocWithApprovedTitle(s,c,custom).replace('CUSTOM / INTERCOMPANY INVOICE','CUSTOM INVOICE / INTERCOMPANY');if(custom)html=html.replace(/<tr><td class="lbl">L\/C Number \/ Date<\/td>[\s\S]*?<\/tr>/,'');return html};

const packingListDocWithApprovedLayout=packingListDoc;
packingListDoc=function(s,c,custom=false){if(!custom)return packingListDocWithApprovedLayout(s,c,false);const dc=customsDocumentContext(s,c),t=plannedTotals(s,dc),groups=new Map();for(const row of t.rows||[]){const key=[row.brand,row.packing].join('|'),g=groups.get(key)||{brand:row.brand||'',packing:row.packing||'',bags:0,netKg:0,tareKg:0,grossKg:0};g.bags+=num(row.bags);g.netKg+=num(row.netKg);g.tareKg+=num(row.tareKg);g.grossKg+=num(row.grossKg||row.netKg);groups.set(key,g)}return pageDoc(dc,'CUSTOM PACKING LIST',`<div class="invoiceTop"><div><b>REFERENCE</b>${esc(s.customs.invoiceNo||dc.ref)}</div><div><b>DATE</b>${fmt(s.customs.date||TODAY())}</div><div><b>CONTRACT / LOT</b>${esc(s.contractRef)} / ${esc(s.lotId)}</div><div><b>DESTINATION</b>${esc(dc.podPort||dc.destPort)}</div></div>${partyGrid(dc)}<table class="docTable packingGoods"><thead><tr><th>Brand / Packing / Bag Marking</th><th>Bags</th><th>Net KG</th><th>Tare KG</th><th>Gross KG</th></tr></thead><tbody>${[...groups.values()].map(row=>`<tr><td>${bagMarkingCell(s,row.brand)}<div>${esc(row.packing)}</div></td><td>${row.bags.toLocaleString()}</td><td>${row.netKg.toFixed(3)}</td><td>${row.tareKg.toFixed(3)}</td><td>${row.grossKg.toFixed(3)}</td></tr>`).join('')}</tbody><tfoot><tr><th>TOTAL</th><th>${t.bags.toLocaleString()}</th><th>${t.net.toFixed(3)}</th><th>${t.tare.toFixed(3)}</th><th>${t.gross.toFixed(3)}</th></tr></tfoot></table>${signature(dc)}`)};

function generatedCertificateDoc(s,c,certificate){const selected=certificate.selectedFields||[],values={seller:sellerOf(c).name,buyer:s.buyer,contract:s.contractRef,lot:s.lotId,product:c.product,quantity:`${actualTotals(s,c).mt.toFixed(3)} MTONS`,packing:c.packings.map(p=>`${p.brand} · ${p.type} · ${p.size} ${c.packingUnit}`).join('; '),containers:actualTotals(s,c).rows.map(r=>`${r.number||'PENDING'} / ${r.seal||'PENDING'}`).join('; '),bl:s.bl.blNo||'PENDING',ports:`${c.pol} to ${c.podPort||c.destPort}`,origin:'PAKISTAN',quality:c.quality||DEFAULT_QUALITY};return pageDoc(c,certificate.type,`${partyGrid(c)}<table class="docMeta">${selected.map(key=>`<tr><td class="lbl">${esc(key.charAt(0).toUpperCase()+key.slice(1))}</td><td>${esc(values[key]||'')}</td></tr>`).join('')}</table><p class="certificateText">${esc(certificate.statement||certificate.text||'')}</p><p><b>Reference:</b> ${esc(certificate.reference||s.contractRef)} · <b>Date:</b> ${fmt(certificate.date||TODAY())}</p>${signature(c)}`)}

function renderCertificatesApproved(d){const s=shipment(),c=contractByRef(s.contractRef),fields=[['seller','Seller / Exporter'],['buyer','Buyer / Importer'],['contract','Contract Reference'],['lot','Lot Reference'],['product','Product'],['quantity','Actual Quantity'],['packing','Packing / Brand'],['containers','Containers / Seals'],['bl','B/L Reference'],['ports','Ports'],['origin','Origin'],['quality','Quality']];const generated=(s.certs||[]).filter(x=>x.kind==='generated'||(!x.kind&&!x.finalDocument));d.innerHTML=`<div class="section"><h3>+ CERTIFICATE</h3><div class="notice">Create a Transtrade-issued certificate only when the customer, contract or L/C requires an additional statement.</div><div class="field"><label>Certificate Title</label><input id="generatedCertTitle" placeholder="Example: Quality and Weight Certificate"></div><div class="field"><label>Information to include</label><div class="certificateFieldGrid">${fields.map(([key,label])=>`<label><input type="checkbox" data-cert-field="${key}"> ${esc(label)}</label>`).join('')}</div></div><div class="field"><label>What this certificate confirms</label><textarea id="generatedCertStatement" placeholder="Enter the exact statement required by the customer or L/C."></textarea></div><div class="toolbar"><div class="spacer"></div><button class="btn green" id="saveGeneratedCertificate">SAVE CERTIFICATE</button></div>${generated.length?`<div class="tableWrap"><table class="table"><thead><tr><th>Certificate</th><th>Date</th><th>Included Information</th><th></th></tr></thead><tbody>${generated.map(x=>`<tr><td>${esc(x.type)}</td><td>${fmt(x.date)}</td><td>${esc((x.selectedFields||[]).join(', '))}</td><td><button class="btn small soft" data-print-generated-cert="${esc(x.id)}">Print / PDF</button></td></tr>`).join('')}</tbody></table></div>`:''}</div>`;document.getElementById('saveGeneratedCertificate').onclick=()=>{const type=generatedCertTitle.value.trim(),statement=generatedCertStatement.value.trim(),selectedFields=[...document.querySelectorAll('[data-cert-field]:checked')].map(x=>x.dataset.certField);if(!type||!statement)return alert('Enter the certificate title and the exact statement.');const cert={id:uid('CERT'),kind:'generated',type,issuer:sellerOf(c).name,reference:s.contractRef,date:TODAY(),selectedFields,statement,text:statement};s.certs.push(cert);audit('Certificate','Draft prepared',`${s.contractRef} · ${s.lotId} · ${type}`);renderShipmentWorkspace()};document.querySelectorAll('[data-print-generated-cert]').forEach(button=>button.onclick=()=>{const cert=s.certs.find(x=>x.id===button.dataset.printGeneratedCert);if(cert)printShipmentDoc(cert.type,generatedCertificateDoc(s,c,cert),c.seller)})}

function renderUploadDocuments(d){const s=shipment();s.uploadedDocuments=Array.isArray(s.uploadedDocuments)?s.uploadedDocuments:[];const legacy=(s.certs||[]).filter(x=>x.finalDocument&&!x.kind);d.innerHTML=`<div class="section"><h3>UPLOAD DOCUMENTS</h3><div class="notice">Choose a known document name, or choose Custom and type the name. This area is for carrier, government, bank, customer and other external/final documents.</div><div class="grid2"><div class="field"><label>Document Name</label><select id="uploadDocumentType">${KNOWN_UPLOAD_DOCUMENTS.map(name=>`<option>${esc(name)}</option>`).join('')}</select></div><div class="field hidden" id="customUploadNameWrap"><label>Custom Document Name</label><input id="customUploadName"></div><div class="field full"><label>File</label><div class="documentDropZone" id="documentDropZone" tabindex="0"><b>Drag and drop the document here</b><span>or click Browse</span><input id="lotDocumentFile" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,image/*"><button class="btn soft" type="button" id="browseLotDocument">Browse</button><span class="fileNote" id="lotDocumentFileName">No file selected</span></div></div></div><div class="toolbar"><div class="spacer"></div><button class="btn green" id="saveLotDocument">UPLOAD DOCUMENT</button></div>${s.uploadedDocuments.length||legacy.length?`<div class="tableWrap"><table class="table"><thead><tr><th>Document</th><th>Uploaded</th><th>File</th></tr></thead><tbody>${s.uploadedDocuments.map(x=>`<tr><td>${esc(x.name)}</td><td>${new Date(x.uploadedAt||x.finalDocument?.uploadedAt||Date.now()).toLocaleString()}</td><td>${fileLink(x.finalDocument)}</td></tr>`).join('')}${legacy.map(x=>`<tr><td>${esc(x.type)}</td><td>${fmt(x.date)}</td><td>${fileLink(x.finalDocument)}</td></tr>`).join('')}</tbody></table></div>`:''}</div>`;const select=document.getElementById('uploadDocumentType'),customWrap=document.getElementById('customUploadNameWrap'),fileInput=document.getElementById('lotDocumentFile'),dropZone=document.getElementById('documentDropZone'),showName=()=>lotDocumentFileName.textContent=fileInput.files[0]?.name||'No file selected';select.onchange=()=>customWrap.classList.toggle('hidden',select.value!=='Custom');browseLotDocument.onclick=()=>fileInput.click();fileInput.onchange=showName;dropZone.ondragover=e=>{e.preventDefault();dropZone.classList.add('dragging')};dropZone.ondragleave=()=>dropZone.classList.remove('dragging');dropZone.ondrop=e=>{e.preventDefault();dropZone.classList.remove('dragging');if(e.dataTransfer.files.length){fileInput.files=e.dataTransfer.files;showName()}};saveLotDocument.onclick=async()=>{try{const name=select.value==='Custom'?customUploadName.value.trim():select.value,file=fileInput.files[0];if(!name)return alert('Enter the custom document name.');if(!file)return alert('Choose a document to upload.');const doc=await uploadDocument(file,'lot-document-'+name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),s),entry={id:uid('UPDOC'),name,uploadedAt:new Date().toISOString(),uploadedBy:currentUser(),finalDocument:doc};s.uploadedDocuments.push(entry);if(/^Final \/ Original B\/L$/i.test(name)){s.bl.finalDocument=doc;s.bl.finalFile=doc.name;s.bl.finalized=!!s.bl.blNo&&!!s.bl.onBoardDate}else if(/^Certificate of Origin$/i.test(name))s.coo.finalDocument=doc;else if(/^Goods Declaration/i.test(name)){doc.gdRefsFingerprint=gdRefsFingerprint(s.customs.gdRefs||[]);s.customs.gdDocument=doc}else if(/Certificate|Phytosanitary|Fumigation|Inspection|SGS|Health|Insurance/i.test(name)){const existing=s.certs.find(x=>x.kind==='uploaded'&&x.type===name);const certificate={id:existing?.id||uid('CERT'),kind:'uploaded',type:name,issuer:'External',reference:'',date:TODAY(),finalDocument:doc};if(existing)Object.assign(existing,certificate);else s.certs.push(certificate)}audit('Upload Documents','Completed document uploaded',`${s.contractRef} · ${s.lotId} · ${name}`);renderShipmentWorkspace()}catch(error){alert(error.message)}}}

const renderWorkspaceDetailBeforeApprovedDocuments=renderWorkspaceDetail;
renderWorkspaceDetail=function(){if(activeWorkspace==='uploads'){const d=document.getElementById('workspaceDetail');if(d)renderUploadDocuments(d);return}renderWorkspaceDetailBeforeApprovedDocuments()};
renderCertificates=renderCertificatesApproved;

function liveLotDocument(key,s,c){const copy=structuredClone(s),value=id=>document.getElementById(id)?.value;if(key==='bl'){Object.assign(copy.bl,{blNo:value('blNo')??copy.bl.blNo,onBoardDate:value('blDate')??copy.bl.onBoardDate,vessel:value('blVessel')??copy.bl.vessel,voyage:value('blVoyage')??copy.bl.voyage,consignee:value('blConsignee')??copy.bl.consignee,notify:value('blNotify')??copy.bl.notify,description:value('blDesc')??copy.bl.description});return blDraftDoc(copy,c)}if(key==='commercial'){Object.assign(copy.commercial,{invoiceNo:value('coNo')??copy.commercial.invoiceNo,date:value('coDate')??copy.commercial.date,destination:value('coDestination')??copy.commercial.destination,notifyParty:value('coNotify')??copy.commercial.notifyParty});return commercialInvoiceDoc(copy,c,false)}if(key==='customs'){Object.assign(copy.customs,{date:value('cuDate')??copy.customs.date,paymentTerms:value('cuPaymentTerms')??copy.customs.paymentTerms,hsCode:value('cuHS')??copy.customs.hsCode,bank:value('cuBank')??copy.customs.bank,iban:value('cuIBAN')??copy.customs.iban,marks:value('cuMarks')??copy.customs.marks,description:value('cuDesc')??copy.customs.description,rate:num(value('cuRate')??copy.customs.rate)});return commercialInvoiceDoc(copy,c,true)}if(key==='coo'){Object.assign(copy.coo,{reference:value('cooRef')??copy.coo.reference,date:value('cooDate')??copy.coo.date,description:value('cooDesc')??copy.coo.description});return cooDoc(copy,c,false)}if(key==='cover')return coveringDoc(copy,c);if(key==='lcdraft')return lcDraftDoc(copy,c);return''}
function splitLotDocumentWorkspace(d,key,title){const s=shipment(),c=contractByRef(s.contractRef),children=[...d.childNodes];d.innerHTML='<div class="lotSplitWorkspace"><div class="lotFormPane"></div><aside class="lotPreviewPane"><div class="lotPreviewHead"><b>'+esc(title)+'</b><span>Live A4 preview</span></div><div class="lotPreviewPaper"></div></aside></div>';const form=d.querySelector('.lotFormPane'),paper=d.querySelector('.lotPreviewPaper');children.forEach(node=>form.appendChild(node));const update=()=>{try{paper.innerHTML=liveLotDocument(key,s,c)||'<div class="previewEmpty">Preview becomes available after the document is prepared.</div>'}catch(error){paper.innerHTML='<div class="previewEmpty">Complete the available fields to preview this document.</div>'}};form.querySelectorAll('input,select,textarea').forEach(control=>{control.addEventListener('input',update);control.addEventListener('change',update)});update()}
for(const [name,key,title] of [['renderBL','bl','B/L Draft / Shipping Instructions'],['renderCommercial','commercial','Commercial Invoice'],['renderCustoms','customs','Customs Invoice'],['renderCOO','coo','Certificate of Origin'],['renderCover','cover','Bank Covering Letter'],['renderLCDraft','lcdraft','L/C Exchange Draft']]){const original={renderBL,renderCommercial,renderCustoms,renderCOO,renderCover,renderLCDraft}[name];if(name==='renderBL')renderBL=function(d){original(d);splitLotDocumentWorkspace(d,key,title)};else if(name==='renderCommercial')renderCommercial=function(d){original(d);splitLotDocumentWorkspace(d,key,title)};else if(name==='renderCustoms')renderCustoms=function(d){original(d);splitLotDocumentWorkspace(d,key,title)};else if(name==='renderCOO')renderCOO=function(d){original(d);splitLotDocumentWorkspace(d,key,title)};else if(name==='renderCover')renderCover=function(d){original(d);splitLotDocumentWorkspace(d,key,title)};else if(name==='renderLCDraft')renderLCDraft=function(d){original(d);splitLotDocumentWorkspace(d,key,title)}}

const renderBLBeforeHandoffFields=renderBL;
renderBL=function(d){renderBLBeforeHandoffFields(d);const s=shipment(),grid=d.querySelector('.lotFormPane .grid3');if(grid)grid.insertAdjacentHTML('afterbegin',`<div class="field"><label>Loading Programme No.</label><input readonly value="${esc(loadingProgrammeFor(s)||'PENDING')}"></div><div class="field"><label>Intended Vessel — from Loading Instructions</label><input readonly value="${esc(intendedVesselFor(s)||'TBA')}"></div><div class="field"><label>Shipping Line — from Loading Instructions</label><input readonly value="${esc(shippingLineFor(s)||'TBA')}"></div>`)};

const renderDocumentOutputBeforeUploadedDocuments=renderDocumentOutput;
renderDocumentOutput=function(d){renderDocumentOutputBeforeUploadedDocuments(d);const s=shipment(),documents=s.uploadedDocuments||[];if(!documents.length)return;const section=d.querySelector('.section'),toolbar=section?.querySelector('.toolbar:last-child');if(section&&toolbar)toolbar.insertAdjacentHTML('beforebegin',`<h4>Other Uploaded Documents</h4><div class="checklist">${documents.map(item=>`<div class="checkItem"><b>${esc(item.name)}</b> · ${fileLink(item.finalDocument)}</div>`).join('')}</div>`)};

const renderLoadingBeforeVesselHandoff=renderLoading;
renderLoading=function(d){renderLoadingBeforeVesselHandoff(d);const p=shipment(),draft=p?.loading?.draft;if(!draft)return;draft.intendedVessel=draft.intendedVessel||'';draft.shippingLine=draft.shippingLine||'';const head=d.querySelector('.grid3');if(head&&!d.querySelector('#liIntendedVessel'))head.insertAdjacentHTML('beforeend',`<div class="field"><label>Intended Vessel</label><input id="liIntendedVessel" value="${esc(draft.intendedVessel)}" placeholder="Enter intended vessel"></div><div class="field"><label>Shipping Line</label><input id="liShippingLine" value="${esc(draft.shippingLine)}" placeholder="Enter shipping line name"></div>`);const vessel=document.getElementById('liIntendedVessel'),line=document.getElementById('liShippingLine');vessel.oninput=e=>draft.intendedVessel=e.target.value;line.oninput=e=>draft.shippingLine=e.target.value;const button=d.querySelector('#sendLoading'),original=button?.onclick,programme=draft.loadingProgrammeNo;if(button&&original)button.onclick=async event=>{const before=new Set(lotsFor(p).map(x=>x.id)),intendedVessel=vessel.value.trim(),shippingLine=line.value.trim();if(!intendedVessel||!shippingLine)return setLoadingFeedback('loadingFeedback','Enter Intended Vessel and Shipping Line before sending Loading Instructions.');await original.call(button,event);const lot=lotsFor(p).find(x=>!before.has(x.id));if(!lot)return;lot.loadingProgrammeNo=lot.loadingProgrammeNo||programme;Object.assign(lot.loadingPlan,{loadingProgrammeNo:lot.loadingProgrammeNo,intendedVessel,shippingLine});Object.assign(lot.bl,{intendedVessel,shippingLine,vessel:lot.bl.vessel||intendedVessel});const summary=(p.loading?.lots||[]).find(x=>x.lotRecordId===lot.id);if(summary)Object.assign(summary,{loadingProgrammeNo:lot.loadingProgrammeNo,intendedVessel,shippingLine});const handoff=(state.millSync.exportLoading||[]).find(x=>x.shipmentId===lot.id);if(handoff){Object.assign(handoff,{loadingProgrammeNo:lot.loadingProgrammeNo,intendedVessel,shippingLine});handoff.plan={...(handoff.plan||{}),loadingProgrammeNo:lot.loadingProgrammeNo,intendedVessel,shippingLine}}audit('LOADING INSTRUCTIONS','Vessel and shipping line sent to Mill',`${p.contractRef} · ${lot.lotId} · ${intendedVessel} · ${shippingLine}`);save();try{const shared=window.TT_SHARED_SYNC?.saveNow?.();if(shared)await shared}catch(error){console.error('Loading vessel shared save',error)}}};

function applyLoadingHandoffFields(p,lot,programme,intendedVessel,shippingLine){if(!lot)return;lot.loadingProgrammeNo=lot.loadingProgrammeNo||programme;lot.loadingPlan=lot.loadingPlan||{};Object.assign(lot.loadingPlan,{loadingProgrammeNo:lot.loadingProgrammeNo,intendedVessel,shippingLine});Object.assign(lot.bl,{intendedVessel,shippingLine,vessel:lot.bl.vessel||intendedVessel});const summary=(p.loading?.lots||[]).find(x=>x.lotRecordId===lot.id);if(summary)Object.assign(summary,{loadingProgrammeNo:lot.loadingProgrammeNo,intendedVessel,shippingLine,plan:{...(summary.plan||{}),loadingProgrammeNo:lot.loadingProgrammeNo,intendedVessel,shippingLine}});const handoff=(state.millSync.exportLoading||[]).find(x=>x.shipmentId===lot.id);if(handoff){Object.assign(handoff,{loadingProgrammeNo:lot.loadingProgrammeNo,intendedVessel,shippingLine});handoff.plan={...(handoff.plan||{}),loadingProgrammeNo:lot.loadingProgrammeNo,intendedVessel,shippingLine}}}
const renderLoadingWithImmediateHandoff=renderLoading;
renderLoading=function(d){renderLoadingWithImmediateHandoff(d);const p=shipment(),draft=p?.loading?.draft,button=d.querySelector('#sendLoading'),original=button?.onclick;if(!draft||!button||!original)return;button.onclick=event=>{const before=new Set(lotsFor(p).map(x=>x.id)),programme=draft.loadingProgrammeNo,intendedVessel=String(draft.intendedVessel||'').trim(),shippingLine=String(draft.shippingLine||'').trim(),result=original.call(button,event),lot=lotsFor(p).find(x=>!before.has(x.id));applyLoadingHandoffFields(p,lot,programme,intendedVessel,shippingLine);return result}};

// Restore the original Lot icon screen. Document work opens in one temporary
// two-column editor above the icons and returns to the Lot after a valid save.
const LOT_EDITOR_TITLES={customs:'Customs Documents',bl:'B/L Draft',commercial:'Commercial Invoice & Packing List',coo:'Certificate of Origin',certs:'+ Certificate',uploads:'Upload Documents',cover:'Bank & Dispatch',tg:'TG Documents',lcdraft:'L/C Draft',output:'Final Output',history:'History'};
const LOT_EDITOR_SAVE_CONTROLS={customs:'#saveCustoms',bl:'#saveBL',commercial:'#saveCommercial',coo:'#saveCOO',certs:'#saveGeneratedCertificate',uploads:'#saveLotDocument',cover:'#saveCover',tg:'#printTGPakistan'};

function closeLotEditor(){activeWorkspace='';renderShipmentWorkspace()}
function wireLotEditorSave(form,key){const selector=LOT_EDITOR_SAVE_CONTROLS[key];if(!selector)return;const button=form.querySelector(selector);if(!button||button.dataset.returnToLot)return;button.dataset.returnToLot='1';const original=button.onclick;if(!original)return;button.onclick=event=>{const before=(state.audits||[]).length,result=original.call(button,event),finish=()=>{if((state.audits||[]).length>before&&activeWorkspace===key)closeLotEditor()};if(result&&typeof result.then==='function')return result.then(value=>{finish();return value});finish();return result}}

splitLotDocumentWorkspace=function(d,key,title){const s=shipment(),c=contractByRef(s.contractRef),children=[...d.childNodes];d.innerHTML='<div class="lotSplitWorkspace"><div class="lotFormPane"></div><aside class="lotPreviewPane"><div class="lotPreviewHead"><b>'+esc(title)+'</b><span>Document preview</span></div><div class="lotPreviewPaper"></div></aside></div>';const form=d.querySelector('.lotFormPane'),paper=d.querySelector('.lotPreviewPaper');children.forEach(node=>form.appendChild(node));const update=()=>{try{paper.innerHTML=liveLotDocument(key,s,c)||'<div class="previewEmpty">The document preview will appear here when its information is available.</div>'}catch(error){paper.innerHTML='<div class="previewEmpty">Complete the requested information to preview this document.</div>'}};form.querySelectorAll('input,select,textarea').forEach(control=>{control.addEventListener('input',update);control.addEventListener('change',update)});wireLotEditorSave(form,key);update()};

function splitSupportingLotWorkspace(d,key){if(d.querySelector('.lotSplitWorkspace'))return;const children=[...d.childNodes];d.innerHTML='<div class="lotSplitWorkspace"><div class="lotFormPane"></div><aside class="lotPreviewPane"><div class="lotPreviewHead"><b>'+esc(LOT_EDITOR_TITLES[key]||'Document')+'</b><span>Document information</span></div><div class="previewEmpty">Saved documents and output remain attached to this Lot.</div></aside></div>';const form=d.querySelector('.lotFormPane');children.forEach(node=>form.appendChild(node));wireLotEditorSave(form,key)}

const renderWorkspaceDetailBeforeRestoredLot=renderWorkspaceDetail;
renderWorkspaceDetail=function(){renderWorkspaceDetailBeforeRestoredLot();const d=document.getElementById('workspaceDetail'),s=shipment();if(!d||!activeWorkspace||s?.kind!=='lot')return;if(['certs','uploads','tg'].includes(activeWorkspace))splitSupportingLotWorkspace(d,activeWorkspace)};

function restoredLotTiles(s,c){const tiles=LOT_TILES.filter(([k])=>(k!=='lcdraft'||lcApplies(s,c))&&(k!=='tg'||s.seller==='TG')).map(row=>row[0]==='certs'?[row[0],row[1],'+ Certificate']:row);const certificateIndex=tiles.findIndex(([k])=>k==='certs');if(!tiles.some(([k])=>k==='uploads'))tiles.splice(certificateIndex<0?tiles.length:certificateIndex+1,0,['uploads','⇧','Upload Documents']);return tiles}

renderShipmentWorkspace=function(){const s=shipment();if(!s||s.kind!=='lot')return renderShipmentWorkspaceBeforeLotDocuments();renderNav();const c=contractByRef(s.contractRef);if(!c)return renderShipments();const tiles=restoredLotTiles(s,c),editor=activeWorkspace?`<section class="lotEditorShell" aria-label="${esc(LOT_EDITOR_TITLES[activeWorkspace]||'Lot document')}"><div class="lotEditorHead"><h3>${esc(LOT_EDITOR_TITLES[activeWorkspace]||'Lot document')}</h3><button class="lotEditorClose" id="closeLotEditor" type="button" aria-label="Close document editor">×</button></div><div class="workspaceDetail" id="workspaceDetail"></div></section>`:'';document.getElementById('main').innerHTML=`<button class="backLink" id="backShipments">← Back to Export Home</button><div class="panel workspaceHead"><div><h2>${esc(s.contractRef)} — ${esc(s.lotId)}</h2><div class="metaText">${esc(s.buyer)} · ${num(s.plannedQty).toFixed(3)} MT · ${num(s.containers)} container(s)</div></div><div class="toolbar"><button class="btn soft" id="combineLots">Combine Lots / GDs</button><button class="btn red small" id="cancelLot">Cancel Lot</button></div></div>${editor}<div class="workspacePanel"><div class="workspaceTiles">${tiles.map(([k,icon,label])=>`<button class="workspaceTile ${activeWorkspace===k?'active':''}" data-workspace="${k}" aria-expanded="${activeWorkspace===k}"><span class="workspaceGlyph">${icon}</span><b>${label}</b><small>${tileStatus(k,s)}</small></button>`).join('')}</div></div>`;document.getElementById('backShipments').onclick=()=>{activeWorkspace='';view='home';render()};document.getElementById('combineLots').onclick=()=>openCombineLots(s);document.getElementById('closeLotEditor')?.addEventListener('click',closeLotEditor);document.querySelectorAll('[data-workspace]').forEach(button=>button.onclick=()=>{activeWorkspace=button.dataset.workspace;renderShipmentWorkspace();document.querySelector('.lotEditorShell')?.scrollIntoView?.({behavior:'smooth',block:'start'})});renderWorkspaceDetail()};

const renderContractEditorBeforePackingSource=renderContractEditor;
renderContractEditor=function(){if(contractDraft){contractDraft.packings.forEach(p=>p.weightPer=num(contractDraft.weightPer));syncQty()}return renderContractEditorBeforePackingSource()};

const showContractReviewBeforePackingSource=showContractReview;
showContractReview=function(x){
 showContractReviewBeforePackingSource(x);
 const productInput=document.getElementById('riProduct'),saveButton=document.getElementById('saveContractImport'),products=productMasters();
 if(productInput&&products.length){
  const source=String(x.product||'').toUpperCase(),match=products.find(v=>source.includes(String(v[1]||'').toUpperCase())&&(!cleanBroken(v)||source.includes(cleanBroken(v).toUpperCase())));
  const select=document.createElement('select');select.id='riProduct';select.innerHTML=`<option value="">Select complete Product Identity</option>${products.map(v=>`<option value="${esc(productIdentityCode(v))}" ${match===v?'selected':''}>${esc(productLabel(v))}</option>`).join('')}`;productInput.replaceWith(select);
  const originalSave=saveButton.onclick;
  saveButton.onclick=()=>{
   const identity=select.value;if(!identity)return alert('Select a complete Product Identity from Products & Quality Master.');
   const prepared=newContractShape();applyProductMaster(prepared,identity);x.quality=prepared.quality;
   const ref=document.getElementById('riRef').value.trim(),existingIds=new Set(state.contracts.map(c=>c.id));originalSave();
   const saved=state.contracts.find(c=>!existingIds.has(c.id)&&c.ref.toLowerCase()===ref.toLowerCase());if(!saved)return;
   applyProductMaster(saved,identity);const process=state.shipments.find(s=>s.contractRef===saved.ref&&s.kind==='process');if(process?.production)process.production.qualityNotes=saved.quality;save();window.TT_SHARED_SYNC?.flush()
  }
 }
 saveButton?.insertAdjacentHTML('beforebegin','<div class="notice info"><b>Weight per container is entered once.</b> It is calculated from Quantity MT ÷ Total Containers and applied automatically to every packing line.</div>')
};

/* Specimen-led A4 shipment outputs. */
function specimenPartyBox(label,party){return`<div class="specimenParty"><b>${esc(label)}</b><strong>${esc(party?.name||'')}</strong><span>${esc(party?.address||'')}</span></div>`}
function specimenReference(ref,date,extra=''){return`<div class="specimenReference"><div><b>REF NO.</b>${esc(ref||'')}</div><div><b>DATE</b>${fmt(date||TODAY())}</div>${extra}</div>`}
function specimenWeightFooter(t,trailing=0){return`<tr class="specimenWeights"><th>GROSS WEIGHT<br>${(num(t.gross)/1000).toFixed(3)} M/TONS<br>${num(t.gross).toFixed(3)} KGS</th><th>TARE<br>${(num(t.tare)/1000).toFixed(3)} M/T<br>${num(t.tare).toFixed(3)} KGS</th><th>NET WEIGHT<br>${(num(t.net)/1000).toFixed(3)} M/T<br>${num(t.net).toFixed(3)} KGS</th>${'<th></th>'.repeat(trailing)}</tr>`}
function specimenDescription(c,line,extra=''){return`<b>${esc(c.product||line.description||'')}</b><br>${esc(c.quality||DEFAULT_QUALITY)}<br>${esc(line.packing||'')}${extra?`<br>${esc(extra)}`:''}`}
function cleanOutputText(value){return String(value||'').replace(/\b(?:inter[ -]?company|intra[ -]?company|intra[ -]?group)\b/gi,'').replace(/\s*\/\s*FI SETTLEMENT ARRANGEMENT/gi,'').replace(/\s{2,}/g,' ').trim()}
function customsOutputPayment(s,c){const raw=cleanOutputText(s.customs?.paymentTerms||paymentText(c)),fiValue=(s.customs?.fiAllocations||[]).reduce((sum,row)=>sum+num(row.amount),0),balance=num(s.customs?.openAccount),currency=s.customs?.currency||c.currency;if(s.seller!=='TG'&&raw)return raw;if(fiValue>0&&balance>0)return`${money(fiValue,currency)} ADVANCE UNDER FI; BALANCE ${money(balance,currency)} CAD`;if(fiValue>0)return'100% ADVANCE UNDER FI';return raw||'100% CAD'}
function customsOutputReferences(s){const fi=(s.customs?.fiAllocations||[]).map(row=>row.number||row).filter(Boolean).join(', '),gd=(s.customs?.gdRefs||[]).map(row=>row.number||row).filter(Boolean).join(', ');return fi||gd?`<div class="specimenTerms">${fi?`<b>FI REFERENCE</b>${esc(fi)}`:''}${fi&&gd?'<br>':''}${gd?`<b>GD REFERENCE</b>${esc(gd)}`:''}</div>`:''}

commercialInvoiceDoc=function(s,c,custom=false){const dc=custom?customsDocumentContext(s,c):c,x=custom?s.customs:s.commercial,lines=invoiceLines(s,dc,custom),currency=x.currency||dc.currency,t=custom?plannedTotals(s,dc):actualTotals(s,dc),total=lines.reduce((sum,line)=>sum+num(line.amount),0),buyer=buyerOf(dc),ship=`${esc(dc.pol||'')} TO ${esc(dc.podPort||dc.destPort||'')}`;if(custom)return pageDoc(dc,'CUSTOM INVOICE',`${specimenReference(x.invoiceNo||dc.ref,x.date)}<div class="specimenTopGrid">${specimenPartyBox('DRAWEE — NAME & ADDRESS',buyer)}<div class="specimenRoute"><b>FROM</b>${esc(dc.pol||'KARACHI, PAKISTAN')}<br><b>TO</b>${esc(dc.podPort||dc.destPort||'')}<br><b>BANK</b>${esc(x.bank||'')}<br><b>IBAN</b>${esc(x.iban||'')}</div></div><div class="specimenTerms"><b>PAYMENT TERMS</b>${esc(customsOutputPayment(s,dc))}</div>${customsOutputReferences(s)}<table class="docTable specimenGoods customInvoiceGoods"><thead><tr><th>BRAND MARKING</th><th>NO. OF PACKAGES</th><th>DESCRIPTION OF GOODS AND/OR SERVICES</th><th>UNIT PRICE</th><th>TOTAL VALUE</th></tr></thead><tbody>${lines.map(line=>`<tr><td>${bagMarkingCell(s,line.brand)}</td><td>${Math.round(num(line.mt)*1000/Math.max(1,num((dc.packings||[]).find(p=>p.brand===line.brand)?.size)||1)).toLocaleString()} BAGS</td><td>${specimenDescription(dc,line)}</td><td>${esc(currency)} ${num(line.rate).toFixed(2)} PER MT<br>${esc(dc.incoterm||'')} ${ship}</td><td>${esc(currency)} ${num(line.amount).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</td></tr>`).join('')}</tbody><tfoot>${specimenWeightFooter(t,2)}<tr><th colspan="4">TOTAL PAYABLE</th><th>${esc(currency)} ${total.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</th></tr></tfoot></table><div class="amountWords"><b>IN WORDS:</b> ${esc(amountInWords(total,currency))}</div>${signature(dc)}`);const received=accountsTotal(s,c),balance=Math.max(0,total-received),showSettlement=received>0;return pageDoc(dc,'COMMERCIAL INVOICE',`${specimenReference(x.invoiceNo||dc.ref,x.date,`<div><b>B/L NO.</b>${esc(s.bl.blNo||'PENDING')}</div>${lcApplies(s,c)?`<div><b>L/C NO.</b>${esc(s.lc.lcNo||'PENDING')}</div>`:''}`)}<div class="specimenTopGrid">${specimenPartyBox('BY ORDER AND FOR ACCOUNT OF',buyer)}<div class="specimenRoute"><b>VESSEL / VOYAGE</b>${esc(s.bl.vessel||intendedVesselFor(s)||'TBA')} / ${esc(s.bl.voyage||'TBA')}<br><b>FROM</b>${esc(dc.pol||'')}<br><b>TO</b>${esc(dc.podPort||dc.destPort||'')}<br><b>PAYMENT</b>${esc(paymentText(dc))}</div></div><table class="docTable specimenGoods commercialInvoiceGoods"><thead><tr><th>PACKING / BRAND MARKING</th><th>DESCRIPTION OF GOODS AND/OR SERVICES</th><th>UNIT PRICE</th><th>TOTAL VALUE</th></tr></thead><tbody>${lines.map(line=>`<tr><td>${bagMarkingCell(s,line.brand)}<span>${esc(line.packing||'')}</span></td><td>${specimenDescription(dc,line)}</td><td>${esc(currency)} ${num(line.rate).toFixed(2)} PER MT<br>${esc(dc.incoterm||'')} ${ship}</td><td>${esc(currency)} ${num(line.amount).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</td></tr>`).join('')}</tbody><tfoot><tr><th>GROSS WEIGHT<br>${(num(t.gross)/1000).toFixed(3)} M/TONS</th><th>NET WEIGHT<br>${(num(t.net)/1000).toFixed(3)} M/TONS</th><th>TOTAL PAYABLE</th><th>${esc(currency)} ${total.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</th></tr>${showSettlement?`<tr><td colspan="3">LESS ADVANCE RECEIVED</td><td>${esc(currency)} ${received.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</td></tr><tr><th colspan="3">BALANCE PAYABLE</th><th>${esc(currency)} ${balance.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</th></tr>`:''}</tfoot></table><div class="amountWords"><b>IN WORDS:</b> ${esc(amountInWords(showSettlement?balance:total,currency))}</div>${signature(dc)}`)};

packingListDoc=function(s,c,custom=false){const dc=custom?customsDocumentContext(s,c):c,x=custom?s.customs:s.commercial,t=custom?plannedTotals(s,dc):actualTotals(s,dc),rows=t.rows||[],groups=new Map();for(const row of rows){const key=[row.brand,row.packing].join('|'),g=groups.get(key)||{brand:row.brand||'',packing:row.packing||'',bags:0,netKg:0,tareKg:0,grossKg:0};g.bags+=num(row.bags);g.netKg+=num(row.netKg);g.tareKg+=num(row.tareKg);g.grossKg+=num(row.grossKg||row.netKg);groups.set(key,g)}if(custom)return pageDoc(dc,'CUSTOM PACKING LIST',`${specimenReference(x.invoiceNo||dc.ref,x.date)}<div class="specimenTopGrid">${specimenPartyBox('DRAWEE — NAME & ADDRESS',buyerOf(dc))}<div class="specimenRoute"><b>FROM</b>${esc(dc.pol||'KARACHI, PAKISTAN')}<br><b>TO</b>${esc(dc.podPort||dc.destPort||'')}</div></div><table class="docTable specimenGoods customPackingGoods"><thead><tr><th>BRAND MARKING</th><th>NO. OF PACKAGES</th><th>DESCRIPTION OF GOODS AND/OR SERVICES</th></tr></thead><tbody>${[...groups.values()].map(row=>`<tr><td>${bagMarkingCell(s,row.brand)}</td><td>${row.bags.toLocaleString()} BAGS</td><td>${specimenDescription(dc,row)}</td></tr>`).join('')}</tbody><tfoot>${specimenWeightFooter(t)}</tfoot></table>${signature(dc)}`);return pageDoc(dc,'COMMERCIAL PACKING LIST',`${specimenReference(x.invoiceNo||dc.ref,x.date,`<div><b>B/L NO.</b>${esc(s.bl.blNo||'PENDING')}</div>${lcApplies(s,c)?`<div><b>L/C NO.</b>${esc(s.lc.lcNo||'PENDING')}</div>`:''}`)}${specimenPartyBox('CONSIGNEE',buyerOf(dc))}<table class="specimenPackingSummary"><tr><th>DESCRIPTION OF GOODS</th><td>${esc(dc.product||'')}<br>${esc(dc.quality||DEFAULT_QUALITY)}</td></tr><tr><th>VESSEL NAME</th><td>${esc(s.bl.vessel||intendedVesselFor(s)||'TBA')} &nbsp; VOY: ${esc(s.bl.voyage||'TBA')}</td></tr><tr><th>PACKING</th><td>${[...groups.values()].map(row=>`${esc(row.brand)} — ${esc(row.packing)} — ${row.bags.toLocaleString()} BAGS`).join('<br>')}</td></tr><tr><th>PORT OF LOADING</th><td>${esc(dc.pol||'')}</td></tr><tr><th>PORT OF DISCHARGE</th><td>${esc(dc.podPort||dc.destPort||'')}</td></tr></table><table class="docTable specimenContainerTable"><thead><tr><th>CONTAINER NO.</th><th>SEAL NO.</th><th>PACKAGES</th><th>NET WEIGHT</th><th>GROSS WEIGHT</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.number||'PENDING')}</td><td>${esc(row.seal||'PENDING')}</td><td>${num(row.bags).toLocaleString()} BAGS</td><td>${num(row.netKg).toFixed(3)} KGS</td><td>${num(row.grossKg||row.netKg).toFixed(3)} KGS</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="2">TOTAL</th><th>${t.bags.toLocaleString()} BAGS</th><th>${num(t.net).toFixed(3)} KGS</th><th>${num(t.gross).toFixed(3)} KGS</th></tr></tfoot></table>${signature(dc)}`)};

phytoInvoiceDoc=function(s,c){const dc=customsDocumentContext(s,c),x=s.customs,t=plannedTotals(s,dc),lines=invoiceLines(s,dc,true),currency=x.currency||dc.currency,total=lines.reduce((sum,line)=>sum+num(line.amount),0);return pageDoc(dc,'PHYTOSANITARY INVOICE',`${specimenReference(x.invoiceNo||dc.ref,x.date)}<div class="specimenTopGrid">${specimenPartyBox('DRAWEE — NAME & ADDRESS',buyerOf(dc))}<div class="specimenRoute"><b>FROM</b>${esc(dc.pol||'KARACHI, PAKISTAN')}<br><b>TO</b>${esc(dc.podPort||dc.destPort||'')}<br><b>BANK</b>${esc(x.bank||'')}<br><b>IBAN</b>${esc(x.iban||'')}</div></div><table class="docTable specimenGoods phytoGoods"><thead><tr><th>BRAND MARKING</th><th>NO. OF PACKAGES</th><th>DESCRIPTION OF GOODS AND/OR SERVICES</th><th>UNIT PRICE</th><th>TOTAL VALUE</th></tr></thead><tbody>${lines.map(line=>`<tr><td>${bagMarkingCell(s,line.brand)}</td><td>${Math.round(num(line.mt)*1000/Math.max(1,num((dc.packings||[]).find(p=>p.brand===line.brand)?.size)||1)).toLocaleString()} BAGS</td><td>${specimenDescription(dc,line,'FOR PHYTOSANITARY / PLANT QUARANTINE PURPOSE')}</td><td>${esc(currency)} ${num(line.rate).toFixed(2)} PER MT</td><td>${esc(currency)} ${num(line.amount).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</td></tr>`).join('')}</tbody><tfoot>${specimenWeightFooter(t,2)}<tr><th colspan="4">TOTAL PAYABLE</th><th>${esc(currency)} ${total.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</th></tr></tfoot></table><div class="amountWords"><b>IN WORDS:</b> ${esc(amountInWords(total,currency))}</div>${signature(dc)}`)};

