blDraftDoc=function(s,c){const dc=s.seller==='TG'?pakistanOriginContext(s,c):c,t=actualTotals(s,dc),marks=s.customs.marks||c.packings.map(p=>p.brand).filter(Boolean).join(' / ');return plainBlPage('B/L DRAFT / SHIPPING INSTRUCTIONS',`<div class="blInstructionGrid"><div><b>Loading Programme No.</b>${esc(loadingProgrammeFor(s)||'PENDING')}</div><div><b>Shipping Line</b>${esc(shippingLineFor(s)||'TBA')}</div><div><b>Intended Vessel</b>${esc(intendedVesselFor(s)||'TBA')}</div><div><b>Voyage</b>${esc(s.bl.voyage||'TBA')}</div></div><div class="blParty"><b>SHIPPER</b>${esc(sellerOf(dc).name)}<br>${esc(sellerOf(dc).address)}</div><div class="blParty"><b>CONSIGNEE</b>${esc(s.bl.consignee||'TO ORDER')}</div><div class="blParty"><b>NOTIFY PARTY</b>${esc(s.bl.notify||s.buyer)}</div>${lcDocReference(s,dc)}${lcInstructions(s,dc)}<table class="docMeta"><tr><td class="lbl">Place / Port of Loading</td><td>${esc(dc.pol)}</td><td class="lbl">Port of Discharge</td><td>${esc(dc.podPort||dc.destPort)}</td></tr><tr><td class="lbl">Freight</td><td>${esc(dc.incoterm==='FOB'?'COLLECT':'PREPAID')}</td><td class="lbl">Service</td><td>FCL / FCL</td></tr></table><table class="docTable blGoods"><thead><tr><th>Marks & Numbers</th><th>No. and Kind of Packages</th><th>Description of Goods</th><th>Gross Weight</th><th>Measurement</th></tr></thead><tbody><tr><td><b>${esc(marks||'AS PER SHIPPING MARKS')}</b></td><td>${t.bags.toLocaleString()} BAGS</td><td>${esc(s.bl.description||dc.product)}<br>${esc(dc.quality||DEFAULT_QUALITY)}</td><td>NET ${t.net.toFixed(3)} KG<br>GROSS ${t.gross.toFixed(3)} KG</td><td>AS DECLARED</td></tr></tbody></table><h3 class="docSection">CONTAINER / SEAL NUMBERS</h3><table class="docTable"><tbody>${t.rows.map(row=>`<tr><td>${esc(row.number||'PENDING')}</td><td>${esc(row.seal||'PENDING')}</td><td>${num(row.bags).toLocaleString()} BAGS</td><td>${num(row.netKg).toFixed(3)} KG NET</td></tr>`).join('')}</tbody></table><div class="greenBox"><b>Draft for carrier confirmation only.</b> The carrier-issued draft and final legal B/L must be uploaded separately.</div>`)};

tgInternalDoc=function(s,c){const dc=pakistanCustomsContext(s,c),t=actualTotals(s,c),fi=(s.customs.fiAllocations||[]).map(v=>v.number||v).filter(Boolean).join(', '),gd=(s.customs.gdRefs||[]).map(v=>v.number||v).filter(Boolean).join(', ');return pageDoc(dc,'EXPORT SETTLEMENT STATEMENT',`${partyGrid(dc)}<table class="docMeta"><tr><td class="lbl">Reference</td><td>${esc(s.customs.invoiceNo||s.contractRef)}</td></tr><tr><td class="lbl">Quantity</td><td>${t.mt.toFixed(3)} MTONS</td></tr><tr><td class="lbl">Payment Terms</td><td>${esc(customsOutputPayment(s,c))}</td></tr><tr><td class="lbl">FI Reference(s)</td><td>${esc(fi||'NOT ALLOCATED')}</td></tr><tr><td class="lbl">GD Reference(s)</td><td>${esc(gd||'PENDING')}</td></tr><tr><td class="lbl">Bank / IBAN</td><td>${esc(s.customs.bank||'')}${s.customs.iban?` · ${esc(s.customs.iban)}`:''}</td></tr></table>${signature(dc)}`)};
tgPakistanCoveringDoc=function(s,c){const dc=pakistanCustomsContext(s,c),fi=(s.customs.fiAllocations||[]).map(v=>v.number||v).filter(Boolean).join(', '),gd=(s.customs.gdRefs||[]).map(v=>v.number||v).filter(Boolean).join(', '),docs=['Custom Packing List','Goods Declaration','Final Bill of Lading','Certificate of Origin','Required Certificates'];return pageDoc(dc,'EXPORT DOCUMENT COVERING',`<p>${fmt(s.customs.date||TODAY())}</p><div class="docPartyBox"><b>To</b>${esc(s.customs.bank||'The Manager, Export Department')}</div><div class="coverSubject">${esc(s.customs.invoiceNo||s.contractRef)} · ${esc(s.lotId)}</div><p>Please find enclosed the export documents for the above shipment.</p><table class="coverDocs"><tr><th>#</th><th>Document</th></tr>${docs.map((name,index)=>`<tr><td>${index+1}</td><td>${esc(name)}</td></tr>`).join('')}</table>${fi?`<p><b>FI:</b> ${esc(fi)}</p>`:''}${gd?`<p><b>GD:</b> ${esc(gd)}</p>`:''}${s.customs.iban?`<p><b>IBAN:</b> ${esc(s.customs.iban)}</p>`:''}${signature(dc)}`)};

