renderDocumentOutput=function(d){renderDocumentOutputBeforePackExclusions(d);const s=shipment(),c=contractByRef(s.contractRef);d.querySelector('[data-output="customInvoice"]')?.closest('label')?.remove();const notice=d.querySelector('.notice');if(notice)notice.insertAdjacentHTML('beforeend','<br><b>Excluded from combined packs:</b> B/L Draft and Customs Invoice remain individual outputs only.');if(s.seller==='TG'){const button=d.querySelector('#printTGPakistanSet');if(button)button.onclick=()=>{const origin=pakistanOriginContext(s,c),certDrafts=s.certs.filter(x=>!x.finalDocument).map(x=>pageDoc(origin,x.type,`${partyGrid(origin)}<p class="certificateText">${esc(x.text)}</p><p><b>Reference:</b> ${esc(x.reference)} · <b>Date:</b> ${fmt(x.date)}</p>${signature(origin)}`)).join(''),html=packingListDoc(s,c,true)+phytoInvoiceDoc(s,c)+cooDoc(s,c,false)+certDrafts+tgInternalDoc(s,c)+tgPakistanCoveringDoc(s,c);printShipmentDoc('PAKISTAN EXPORT DOCUMENT SET',html,pakistanExporterKey(s))}}};
