const TT_PORTS=['Port Qasim, Pakistan or Karachi Port, Pakistan','Port Qasim, Pakistan','Karachi Port, Pakistan'];
const TT_PACKINGS=['P.P. Bags','BOPP laminated Bags','Cotton Bags','Non- Woven Bags','Jute Bags'];
