function uxSettings(){state.settings=state.settings||{};for(const key of ['customPackingTypes','customCurrencies','customInspections'])state.settings[key]=Array.isArray(state.settings[key])?state.settings[key]:[];state.deletedShipments=Array.isArray(state.deletedShipments)?state.deletedShipments:[];return state.settings}
function uniqueValues(fixed,custom){return[...new Set([...fixed,...(custom||[])].map(v=>String(v||'').trim()).filter(Boolean))]}
function selectOptions(values,current,customLabel='+ Custom'){const known=values.includes(current);return`<option value="">Select</option>${values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}<option value="__custom__" ${current&&!known?'selected':''}>${customLabel}</option>`}
function normalizedPartyName(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\b(?:private|pvt|limited|ltd|llc|l\.l\.c|incorporated|inc|company|co)\b/g,'').replace(/[^a-z0-9]/g,'')}
function closeNameMatch(value){const key=normalizedPartyName(value);return state.customers.find(c=>normalizedPartyName(c.name)===key)}
function nameDistance(a,b){const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const old=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=old}}return row[b.length]}
function similarNameMatch(value){const key=normalizedPartyName(value);if(key.length<5)return null;return state.customers.find(c=>{const other=normalizedPartyName(c.name);if(other===key)return false;if(key.includes(other)||other.includes(key))return Math.min(key.length,other.length)>=5;return 1-nameDistance(key,other)/Math.max(key.length,other.length)>=.86})}
function nextLotReference(process){const used=lotsFor(process).map(l=>{const m=String(l.lotId||'').match(/\/L(\d+)$/i);return m?num(m[1]):0});return`${process.contractRef}/L${String((used.length?Math.max(...used):0)+1).padStart(2,'0')}`}
function locationType(name){const row=millLocations().find(x=>String(x.name||'').trim().toLowerCase()===String(name||'').trim().toLowerCase());return String(row?.name||'').toLowerCase()==='tti rice mills'||/own\s*\/\s*default/i.test(String(row?.type||''))?'TTI':/reprocess/i.test(String(row?.type||''))?'Reprocessing':'Ex-Mill'}
openCustomerModal=function(){openModal('Add New Customer',`<div class="grid2"><div class="field"><label>Customer Name</label><input id="mCustName"></div><div class="field"><label>Code</label><input id="mCustCode" maxlength="6"></div><div class="field full"><label>Address</label><textarea id="mCustAddress"></textarea></div><div class="field"><label>Country</label><input id="mCustCountry"></div><div class="field"><label>Email</label><input id="mCustEmail" type="email"></div><div class="field"><label>Phone</label><input id="mCustPhone"></div><div class="field"><label>Default Packing Unit</label><select id="mCustPack"><option>KG</option><option>LB</option></select></div><div class="field full"><label>Notify Parties — one per line as Name | Full Address</label><textarea id="mCustNotify"></textarea></div><div id="customerDuplicateWarning" class="notice warn hidden full"></div></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveNewCustomer">SAVE CUSTOMER & RETURN TO CONTRACT</button>`);const nameInput=document.getElementById('mCustName'),warning=document.getElementById('customerDuplicateWarning'),check=()=>{const match=closeNameMatch(nameInput.value)||similarNameMatch(nameInput.value);warning.classList.toggle('hidden',!match);warning.textContent=match?'Possible existing customer: '+match.name+'. Please verify before adding another account.':'';return match};nameInput.oninput=check;saveNewCustomer.onclick=()=>{const name=nameInput.value.trim(),address=mCustAddress.value.trim(),exact=closeNameMatch(name),similar=similarNameMatch(name);if(!name||!address)return alert('Customer Name and Address are required.');if(exact)return alert('This customer already exists, including punctuation and spacing variations. Select '+exact.name+'.');if(similar&&!confirm('A similar customer already exists: '+similar.name+'. Confirm this is genuinely a different legal customer.'))return;const notifies=mCustNotify.value.split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const [notifyName,...rest]=line.split('|');return{name:notifyName.trim(),address:rest.join('|').trim()}}),n={id:uid('C'),name,code:(mCustCode.value.trim()||name.replace(/[^A-Za-z]/g,'').slice(0,3)||'CUS').toUpperCase(),address,country:mCustCountry.value.trim(),email:mCustEmail.value.trim(),phone:mCustPhone.value.trim(),notifies,packingDefault:mCustPack.value,nextSeq:1};state.customers.push(n);contractDraft.customerId=n.id;contractDraft.packingUnit=n.packingDefault;contractDraft.ref=nextContractRef(n.id,contractDraft.seller);audit('Customer','Added from Sales Contract',n.name);closeModal();renderContractEditor()}};
