uploadDocument=async function(file,category,s){
 if(!file)throw new Error('Select a file.');
 if(file.size>10*1024*1024)throw new Error('Document must be 10 MB or smaller.');
 const access=window.TT_MODULE_ACCESS||{};
 if(access.csrf){
  const body=new FormData();body.append('csrf',access.csrf);body.append('category',category);body.append('contractRef',s.contractRef||'');body.append('lotId',s.lotId||'');body.append('file',file);
  const response=await fetch('/api/export_documents.php',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json'},body});
  const raw=await response.text();let result;
  try{result=JSON.parse(raw)}catch{if(/<!doctype|<html/i.test(raw))throw new Error('Your login session expired. Please sign in again, then upload the file.');throw new Error('The server returned an invalid upload response. Please retry.')}
  if(!response.ok||!result.ok)throw new Error(result.error||'Upload failed.');return result.document;
 }
 const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=()=>reject(new Error('File could not be read.'));r.readAsDataURL(file)});
 return{id:uid('DOC'),name:file.name,mime:file.type,size:file.size,dataUrl,uploadedAt:new Date().toISOString(),category}
};
deleteShipmentDocuments=async function(contractRef){const access=window.TT_MODULE_ACCESS||{};if(!access.csrf)return{deleted:0};const body=new FormData();body.append('csrf',access.csrf);body.append('action','delete-shipment');body.append('contractRef',contractRef);const response=await fetch('/api/export_documents.php',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json'},body}),raw=await response.text();let result;try{result=JSON.parse(raw)}catch{throw new Error(/<!doctype|<html/i.test(raw)?'Your login session expired. Please sign in again.':'The server returned an invalid deletion response.')}if(!response.ok||!result.ok)throw new Error(result.error||'Shipment documents could not be deleted.');return result};

const deleteShipmentDataBeforeTombstone=deleteShipmentData;
deleteShipmentData=function(processId){const p=state.shipments.find(x=>x.id===processId&&x.kind!=='lot'),ref=p?.contractRef||'';const result=deleteShipmentDataBeforeTombstone(processId);if(ref){state.deletedShipments=Array.isArray(state.deletedShipments)?state.deletedShipments:[];state.deletedShipments=state.deletedShipments.filter(x=>x.contractRef!==ref);state.deletedShipments.push({id:uid('DEL'),processId,contractRef:ref,deletedAt:new Date().toISOString(),deletedBy:currentUser()})}return result};
const restartShipmentDataBeforeTombstone=restartShipmentData;
restartShipmentData=function(contractId){const c=state.contracts.find(x=>x.id===contractId);if(c)state.deletedShipments=(state.deletedShipments||[]).filter(x=>x.contractRef!==c.ref);return restartShipmentDataBeforeTombstone(contractId)};

openCustomerModal=function(){openModal('Add New Customer',`<div class="grid2"><div class="field"><label>Customer Name</label><input id="mCustName"></div><div class="field"><label>Code</label><input id="mCustCode" maxlength="6"></div><div class="field full"><label>Address</label><textarea id="mCustAddress"></textarea></div><div class="field"><label>Country</label><input id="mCustCountry"></div><div class="field"><label>Email</label><input id="mCustEmail" type="email"></div><div class="field"><label>Phone</label><input id="mCustPhone"></div><div class="field"><label>Default Packing Unit</label><select id="mCustPack"><option>KG</option><option>LB</option></select></div><div class="field full"><label>Notify Parties — one per line as Name | Full Address</label><textarea id="mCustNotify"></textarea></div><div id="customerDuplicateWarning" class="notice warn hidden full"></div></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveNewCustomer">SAVE CUSTOMER & RETURN TO CONTRACT</button>`);const nameInput=document.getElementById('mCustName'),warning=document.getElementById('customerDuplicateWarning'),check=()=>{const match=closeNameMatch(nameInput.value);warning.classList.toggle('hidden',!match);warning.textContent=match?'A matching customer already exists: '+match.name+'. Select the existing customer instead.':'';return match};nameInput.oninput=check;saveNewCustomer.onclick=()=>{const name=nameInput.value.trim(),address=mCustAddress.value.trim(),match=check();if(!name||!address)return alert('Customer Name and Address are required.');if(match)return alert('This customer already exists, including punctuation/spacing variations. Select '+match.name+'.');const notifies=mCustNotify.value.split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const [notifyName,...rest]=line.split('|');return{name:notifyName.trim(),address:rest.join('|').trim()}}),n={id:uid('C'),name,code:(mCustCode.value.trim()||name.replace(/[^A-Za-z]/g,'').slice(0,3)||'CUS').toUpperCase(),address,country:mCustCountry.value.trim(),email:mCustEmail.value.trim(),phone:mCustPhone.value.trim(),notifies,packingDefault:mCustPack.value,nextSeq:1};state.customers.push(n);contractDraft.customerId=n.id;contractDraft.packingUnit=n.packingDefault;contractDraft.ref=nextContractRef(n.id,contractDraft.seller);audit('Customer','Added from Sales Contract',n.name);closeModal();renderContractEditor()}};

function persistPackingDraft(){if(!packingDraft)return true;const c=contractDraft,typeControl=document.getElementById('mPackType'),customControl=document.getElementById('mPackTypeCustom'),type=typeControl?.value==='__custom__'?String(customControl?.value||'').trim():String(typeControl?.value||'').trim(),size=num(document.getElementById('mPackSize')?.value),brand=String(document.getElementById('mPackBrand')?.value||'').trim(),tare=num(document.getElementById('mPackTare')?.value),containers=num(document.getElementById('mPackContainers')?.value),extraBagPct=num(document.getElementById('mPackExtra')?.value),enabled=!!document.getElementById('mMasterEnabled')?.checked,bagsPerMaster=num(document.getElementById('mMasterQty')?.value),masterTare=num(document.getElementById('mMasterTare')?.value);if(!type||size<=0||containers<=0||num(c.weightPer)<=0){alert('Complete Bag Type, Bag Size, Containers, and Quantity & Shipment weight per container.');return false}if(enabled&&(bagsPerMaster<=0||masterTare<=0)){alert('Enter how many bags are in one master bag and the Master Bag Tare.');return false}if(typeControl?.value==='__custom__'){const settings=uxSettings();if(!settings.customPackingTypes.some(x=>x.toLowerCase()===type.toLowerCase()))settings.customPackingTypes.push(type)}const productBags=bagRequired({size,containers,weightPer:c.weightPer},c),totalBags=productBags+Math.ceil(productBags*extraBagPct/100),masterQty=enabled?Math.ceil(totalBags/bagsPerMaster):0,np={...packingDraft,type,size,brand,tare,containers,weightPer:num(c.weightPer),extraBagPct,masterBag:{enabled,bagsPerMaster,quantity:masterQty,qty:masterQty,weight:bagsPerMaster*size,tare:masterTare}};if(activePackingIndex<c.packings.length)c.packings[activePackingIndex]=np;else c.packings.push(np);activePackingIndex=c.packings.indexOf(np);packingDraft=structuredClone(np);return true}

packingEditorHTML=function(){if(!packingDraft)return contractDraft.packings.length?'<div class="notice">Select a bag tab to view or update it, or add another bag type.</div>':'<div class="notice warn">No packing entered yet. Press + ADD BAG TYPE to start with a blank form.</div>';const p=packingDraft,master=!!p.masterBag?.enabled,types=uniqueValues(TT_PACKINGS,uxSettings().customPackingTypes),known=types.includes(p.type);return`<div class="packingInline"><div class="grid3"><div class="field"><label>BAG TYPE</label><select id="mPackType">${selectOptions(types,p.type)}</select><input id="mPackTypeCustom" class="${known||!p.type?'hidden':''}" value="${known?'':esc(p.type||'')}" placeholder="Enter custom packing"></div><div class="field"><label>BAG SIZE in kgs</label><input id="mPackSize" type="number" step="0.001" value="${p.size||''}"></div><div class="field"><label>BRAND</label><input id="mPackBrand" value="${esc(p.brand||'')}"></div><div class="field"><label>TARE GRAMS</label><input id="mPackTare" type="number" value="${p.tare||''}"></div><div class="field"><label>HOW MANY CONTAINERS FOR THIS PACKING</label><input id="mPackContainers" type="number" value="${p.containers||''}"></div><div class="field"><label>CALCULATED NUMBER OF BAGS</label><input id="mCalculatedBags" readonly></div><div class="field"><label>Extra Bags (%)</label><input id="mPackExtra" type="number" step="0.1" value="${p.extraBagPct===undefined?'':p.extraBagPct}"></div><label class="masterBagToggle"><input id="mMasterEnabled" type="checkbox" ${master?'checked':''}> <b>MASTER BAG</b></label><div id="masterBagFields" class="grid3 full ${master?'':'hidden'}"><div class="field"><label>How many bags in one master bag?</label><input id="mMasterQty" type="number" value="${p.masterBag?.bagsPerMaster||''}"></div><div class="field"><label>MASTER BAG QUANTITY</label><input id="mMasterCount" readonly></div><div class="field"><label>MASTER BAG WEIGHT</label><input id="mMasterWeight" readonly></div><div class="field"><label>Master Bag Tare</label><input id="mMasterTare" type="number" value="${p.masterBag?.tare||''}"></div></div></div>${activePackingIndex<contractDraft.packings.length?'<button class="btn red" id="removePacking">REMOVE THIS BAG TYPE</button>':''}</div>`};

wirePackingStep=function(){const c=contractDraft;cPackingUnit.onchange=e=>{c.packingUnit=e.target.value;renderContractStep()};const allocated=()=>c.packings.reduce((sum,p,i)=>sum+(i===activePackingIndex?0:num(p.containers)),0)+num(document.getElementById('mPackContainers')?.value||0),add=document.getElementById('addPacking');if(allocated()>=num(c.containers)){add.disabled=true;add.title='All contract containers are already allocated to packing lines.'}add.onclick=()=>{if(packingDraft&&!persistPackingDraft())return;if(c.packings.reduce((sum,p)=>sum+num(p.containers),0)>=num(c.containers))return alert('All contract containers are already allocated. Reduce an existing packing line before adding another bag size.');activePackingIndex=c.packings.length;packingDraft=blankPackingShape();renderContractStep()};document.querySelectorAll('[data-pack-tab]').forEach(x=>x.onclick=()=>{if(packingDraft&&!persistPackingDraft())return;const i=num(x.dataset.packTab);if(i<c.packings.length){activePackingIndex=i;packingDraft=structuredClone(c.packings[i])}renderContractStep()});if(!packingDraft)return;const enabled=mMasterEnabled,fields=masterBagFields,calculate=()=>{const size=num(mPackSize.value),containers=num(mPackContainers.value),unitKg=c.packingUnit==='LB'?size*.45359237:size,productBags=unitKg?Math.round(containers*num(c.weightPer)*1000/unitKg):0,totalBags=productBags+Math.ceil(productBags*num(mPackExtra.value)/100),per=num(mMasterQty.value),quantity=enabled.checked&&per?Math.ceil(totalBags/per):0;mCalculatedBags.value=productBags?productBags.toLocaleString():'';mMasterCount.value=quantity?quantity.toLocaleString():'';mMasterWeight.value=enabled.checked&&per?(per*size).toFixed(3)+' '+c.packingUnit:''};mPackType.onchange=()=>mPackTypeCustom.classList.toggle('hidden',mPackType.value!=='__custom__');enabled.onchange=()=>{fields.classList.toggle('hidden',!enabled.checked);calculate()};[mPackSize,mPackContainers,mPackExtra,mMasterQty,mMasterTare].forEach(x=>x.oninput=calculate);calculate();document.getElementById('removePacking')?.addEventListener('click',()=>{c.packings.splice(activePackingIndex,1);activePackingIndex=-1;packingDraft=null;renderContractStep()})};

priceLinesHTML=function(){return contractDraft.packings.map((p,i)=>{const pc=priceComponents(p,contractDraft),showFob=contractDraft.incoterm==='FOB'||num(p.freight)>0;return`<div class="section"><b>${esc(p.brand||'Packing '+(i+1))} · ${p.size} ${contractDraft.packingUnit}</b><div class="grid4" style="margin-top:8px"><div class="field"><label>CNF/CFR value per MT</label><input data-contract-rate="${i}" type="number" step="0.01" value="${pc.finalRate||''}"></div><div class="field"><label>Freight per MT</label><input data-freight="${i}" type="number" step="0.01" value="${pc.freight||''}"></div>${contractDraft.incoterm==='CIF'?`<div class="field"><label>Insurance per MT</label><input data-ins="${i}" type="number" step="0.01" value="${pc.insurance||''}"></div>`:''}<div class="field"><label>FOB value per MT</label><input data-fob="${i}" readonly value="${showFob?pc.fob.toFixed(2):''}" placeholder="Enter freight first"></div><div class="field"><label>${contractDraft.incoterm} Line Value</label><input data-line-value="${i}" readonly value="${money(num(p.containers)*num(contractDraft.weightPer)*pc.finalRate,contractDraft.currency)}"></div></div></div>`}).join('')+`<label class="checkItem"><input id="showAllContractPrices" type="checkbox" ${contractDraft.showAllPrices?'checked':''}> SHOW ALL SEPARATELY ON CONTRACT</label>`};

const renderContractStepBeforeApprovedInputs=renderContractStep;
renderContractStep=function(){renderContractStepBeforeApprovedInputs();const c=contractDraft;if(contractStep===3){const pol=document.getElementById('cPOL');if(pol){const select=document.createElement('select');select.id='cPOL';select.innerHTML=TT_PORTS.map(v=>`<option ${c.pol===v?'selected':''}>${esc(v)}</option>`).join('');pol.replaceWith(select);select.onchange=e=>c.pol=e.target.value}}if(contractStep===5){const currency=document.getElementById('cCurrency'),inspection=document.getElementById('cInspection'),settings=uxSettings();if(currency){currency.innerHTML=selectOptions(uniqueValues(TT_CURRENCIES,settings.customCurrencies),c.currency);currency.onchange=()=>{if(currency.value==='__custom__'){const value=String(prompt('Enter currency code:')||'').trim().toUpperCase();if(!value){renderContractStep();return}if(!settings.customCurrencies.includes(value))settings.customCurrencies.push(value);c.currency=value}else c.currency=currency.value;renderContractStep()}}if(inspection){const select=document.createElement('select');select.id='cInspection';select.innerHTML=selectOptions(uniqueValues(TT_INSPECTIONS,settings.customInspections),c.inspection);inspection.replaceWith(select);select.onchange=()=>{if(select.value==='__custom__'){const value=String(prompt('Enter inspection company:')||'').trim();if(!value){renderContractStep();return}if(!settings.customInspections.some(x=>x.toLowerCase()===value.toLowerCase()))settings.customInspections.push(value);c.inspection=value;state.settings.sharedInspectionCompanies=uniqueValues([],settings.customInspections)}else c.inspection=select.value;renderContractStep()}}}};
async function persistInspectionCompany(value){if(!value||TT_INSPECTIONS.includes(value)||currentRole()!=='Super Admin')return;const existing=masterValues('companies').some(v=>normalizedPartyName(v[0])===normalizedPartyName(value));if(existing)return;const access=window.TT_MODULE_ACCESS||{};if(!access.csrf)return;const code=value.replace(/[^A-Za-z]/g,'').slice(0,6).toUpperCase()||'INSP';try{await fetch('/api/masters.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({csrf:access.csrf,type:'companies',action:'create',values:[value,code,'Inspection Company','','','','Active']})})}catch(error){console.error('Inspection master save',error)}}
const renderContractStepBeforeSharedDefaults=renderContractStep;
renderContractStep=function(){renderContractStepBeforeSharedDefaults();if(contractStep===3){const pol=document.getElementById('cPOL');if(pol&&!TT_PORTS.includes(contractDraft.pol))contractDraft.pol=pol.value}if(contractStep===5){const inspection=document.getElementById('cInspection');inspection?.addEventListener('change',()=>setTimeout(()=>persistInspectionCompany(contractDraft.inspection),0))}};
const renderContractEditorBeforeAutoPacking=renderContractEditor;
renderContractEditor=function(){renderContractEditorBeforeAutoPacking();if(contractStep!==4)return;const next=document.getElementById('nextStep');if(next)next.onclick=()=>{if(packingDraft&&!persistPackingDraft())return;const err=validateContractStep(4);if(err)return alert(err);contractStep=5;packingDraft=null;renderContractEditor()}};

const renderLoadingBeforeApprovedInputs=renderLoading;
renderLoading=function(d){renderLoadingBeforeApprovedInputs(d);const p=shipment(),c=contractByRef(p.contractRef),l=p?.loading?.draft;if(!l)return;l.lotId=l.lotId||nextLotReference(p);l.tba=false;l.portOfLoading=l.portOfLoading||c.pol;l.loadingProgrammeNo=l.loadingProgrammeNo&& !/^LP-/i.test(l.loadingProgrammeNo)?l.loadingProgrammeNo:'';const lot=d.querySelector('#liLot')?.closest('.field'),tba=d.querySelector('#liTBA')?.closest('label');lot?.remove();tba?.remove();const date=d.querySelector('#liDate');if(date)date.disabled=false;d.querySelectorAll('[data-li-type]').forEach(x=>x.closest('td').style.display='none');const typeHeader=[...d.querySelectorAll('th')].find(x=>x.textContent.trim()==='Type');if(typeHeader)typeHeader.style.display='none';const head=d.querySelector('.grid3');if(head){d.querySelectorAll('input[readonly]').forEach(input=>{if(input.closest('.field')?.querySelector('label')?.textContent.includes('Loading Programme'))input.closest('.field').remove()});head.insertAdjacentHTML('afterbegin',`<div class="field"><label>Loading Programme No.</label><input id="liProgramme" value="${esc(l.loadingProgrammeNo)}"></div>`);if(!d.querySelector('#liPort'))head.insertAdjacentHTML('beforeend',`<div class="field"><label>Port of Loading</label><select id="liPort">${TT_PORTS.map(v=>`<option ${l.portOfLoading===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`)}const programme=d.querySelector('#liProgramme'),port=d.querySelector('#liPort');programme.oninput=e=>l.loadingProgrammeNo=e.target.value;port.onchange=e=>l.portOfLoading=e.target.value;d.querySelectorAll('[data-li-name]').forEach(input=>{const sync=()=>{l.allocations[num(input.dataset.liName)].type=locationType(input.value)};input.addEventListener('change',sync);input.addEventListener('blur',sync)});const button=d.querySelector('#sendLoading'),original=button?.onclick;if(button&&original)button.onclick=e=>{l.allocations.forEach(a=>a.type=locationType(a.name));l.lotId=nextLotReference(p);l.loadingProgrammeNo=programme.value.trim();l.portOfLoading=port.value;if(!l.loadingProgrammeNo)return setLoadingFeedback('loadingFeedback','Enter Loading Programme No.');if(!l.loadingDate)return setLoadingFeedback('loadingFeedback','Enter Loading Date.');return original.call(button,e)}};

const renderLoadingBeforeManualProgrammeCommit=renderLoading;
renderLoading=function(d){renderLoadingBeforeManualProgrammeCommit(d);const p=shipment(),draft=p?.loading?.draft,button=d.querySelector('#sendLoading'),programme=d.querySelector('#liProgramme'),port=d.querySelector('#liPort'),original=button?.onclick;if(!draft||!button||!original)return;button.onclick=event=>{const manual=programme.value.trim(),selectedPort=port.value,before=new Set(lotsFor(p).map(x=>x.id));if(!manual)return setLoadingFeedback('loadingFeedback','Enter Loading Programme No.');draft.loadingProgrammeNo=manual;draft.portOfLoading=selectedPort;const apply=()=>{const lot=lotsFor(p).find(x=>!before.has(x.id));if(!lot)return;lot.loadingProgrammeNo=manual;lot.loadingPlan=lot.loadingPlan||{};Object.assign(lot.loadingPlan,{loadingProgrammeNo:manual,portOfLoading:selectedPort});lot.bl=lot.bl||{};lot.bl.portOfLoading=selectedPort;const summary=(p.loading?.lots||[]).find(x=>x.lotRecordId===lot.id);if(summary)Object.assign(summary,{loadingProgrammeNo:manual,portOfLoading:selectedPort});const handoff=(state.millSync.exportLoading||[]).find(x=>x.shipmentId===lot.id);if(handoff){handoff.loadingProgrammeNo=manual;handoff.portOfLoading=selectedPort;handoff.plan={...(handoff.plan||{}),loadingProgrammeNo:manual,portOfLoading:selectedPort}}save()};const result=original.call(button,event);if(result&&typeof result.then==='function')return result.then(value=>{apply();return value});apply();return result}};

const renderLoadingBeforeRemovingDerivedType=renderLoading;
