openFIModal=function(){const banks=masterValues('banks').map(v=>({name:String(v[0]||v[1]||'').trim(),account:String(v[2]||v[3]||'').trim()})).filter(x=>x.name),bankOptions=banks.map(x=>`<option value="${esc([x.name,x.account].filter(Boolean).join(' · '))}">${esc(x.name)}${x.account?' · '+esc(x.account):''}</option>`).join('');openModal('Generate / Insert FI',`<div class="grid3"><div class="field"><label>FI No.</label><input id="mFINo" value="FI-${new Date().getFullYear()}-${String(state.fi.length+1).padStart(4,'0')}"></div><div class="field"><label>Date</label><input id="mFIDate" type="date" value="${TODAY()}"></div><div class="field"><label>Exporter</label><select id="mFIExporter"><option value="TTI">TTI — ${esc(SELLERS.TTI)}</option><option value="BRM">BRM — ${esc(SELLERS.BRM)}</option></select></div><div class="field"><label>Customer</label><select id="mFICustomer"><option value="">Select customer</option>${state.customers.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>FI Type</label><select id="mFIType"><option>Advance</option><option>L/C</option><option>CAD</option><option>TG Unallocated</option></select></div><div class="field"><label>Bank / Account Number</label><select id="mFIBank"><option value="">Select bank account</option>${bankOptions}</select></div><div class="field"><label>Currency</label><select id="mFICur">${uniqueValues(TT_CURRENCIES,uxSettings().customCurrencies).map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Total Value</label><input id="mFIValue" type="number" step=".01"></div><div class="field"><label>L/C No. (required for L/C FI)</label><input id="mFILC"></div><div class="field"><label>L/C Date</label><input id="mFILCDate" type="date"></div><div class="field full"><label>Payment Terms / Reference</label><input id="mFIPayment"></div></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveFI">SAVE FI</button>`);saveFI.onclick=()=>{const no=mFINo.value.trim(),value=num(mFIValue.value),type=mFIType.value,customerName=type==='TG Unallocated'?SELLERS.TG:mFICustomer.value,lcNo=mFILC.value.trim();if(!no||!customerName||value<=0)return alert('FI number, customer and positive value are required.');if(!mFIBank.value)return alert('Select the receiving bank account.');if(type==='L/C'&&!lcNo)return alert('L/C Number is required for an L/C FI.');if(state.fi.some(f=>f.number.toLowerCase()===no.toLowerCase()))return alert('FI number already exists.');state.fi.push({id:uid('FI'),number:no,date:mFIDate.value,exporter:mFIExporter.value,customer:customerName,type,bank:mFIBank.value,currency:mFICur.value,value,lcNo,lcDate:mFILCDate.value,paymentTerms:mFIPayment.value.trim(),allocations:[],createdAt:new Date().toISOString()});audit('FI Register','FI generated',no);closeModal();view='fi';renderFI()}};

ensureBagDraft=function(){const s=shipment(),c=contractByRef(s.contractRef);if(!s.bagOrderDraft){s.bagOrderDraft={poNo:nextBagPoNo(),supplier:'',deliverTo:'To Be Advised Later',requiredDate:'',lines:c.packings.map((p,i)=>{const requiredBags=bagRequired(p,c),extraPct=num(p.extraBagPct),emptyBags=Math.ceil(requiredBags*extraPct/100),master=structuredClone(p.masterBag||{enabled:false,bagsPerMaster:0,qty:0,tare:0});master.printed=!!master.enabled;master.quantity=master.enabled&&num(master.bagsPerMaster)>0?Math.ceil((requiredBags+emptyBags)/num(master.bagsPerMaster)):num(master.quantity||master.qty);master.qty=master.quantity;return{packingIndex:i,brand:p.brand,type:p.type,size:p.size,unit:c.packingUnit,tare:p.tare,requiredBags,extraPct,emptyBags,totalBags:requiredBags+emptyBags,artworkName:'',artworkData:'',artworkAttached:false,approved:false,approvedAt:'',handle:'No',masterBag:master}})}}for(const line of s.bagOrderDraft.lines){line.emptyBags=num(line.emptyBags!==undefined?line.emptyBags:Math.ceil(num(line.requiredBags)*num(line.extraPct)/100));line.totalBags=num(line.requiredBags)+line.emptyBags;line.masterBag=line.masterBag||{enabled:false,bagsPerMaster:0,qty:0,tare:0};line.masterBag.printed=line.masterBag.printed===undefined?!!line.masterBag.enabled:!!line.masterBag.printed;if(line.masterBag.enabled&&num(line.masterBag.bagsPerMaster)>0){line.masterBag.quantity=Math.ceil(line.totalBags/num(line.masterBag.bagsPerMaster));line.masterBag.qty=line.masterBag.quantity}line.approved=!!line.artworkAttached}return s.bagOrderDraft};

renderBagOrder=function(d){const s=shipment(),po=ensureBagDraft(),rows=po.lines.map((l,i)=>{const main=`<tr><td>${i+1}</td><td>${esc(l.brand)}</td><td>${num(l.tare)} g</td><td>${esc(l.type)}</td><td>${num(l.size)} ${esc(l.unit)}</td><td>${num(l.requiredBags).toLocaleString()}</td><td><input data-bo-empty="${i}" type="number" min="0" step="1" value="${num(l.emptyBags)}"></td><td data-total-bags="${i}">${num(l.totalBags).toLocaleString()}</td><td><select data-bo-handle="${i}"><option ${l.handle==='No'?'selected':''}>No</option><option ${l.handle==='Yes'?'selected':''}>Yes</option></select></td><td><input data-bo-art="${i}" type="file" accept="image/*"><div class="metaText">${esc(l.artworkName||'No marking uploaded')}</div>${l.artworkData?`<img class="artPreview" src="${esc(l.artworkData)}" alt="Bag marking">`:''}</td></tr>`;if(!l.masterBag.enabled)return main;const m=l.masterBag,master=`<tr class="masterBagOrderRow"><td>${i+1}.2</td><td>${esc(l.brand)} — MASTER BAG</td><td>${num(m.tare)} g</td><td>MASTER BAG</td><td>${num(m.bagsPerMaster)*num(l.size)} ${esc(l.unit)} (${num(m.bagsPerMaster)} bags)</td><td>${num(m.quantity||m.qty).toLocaleString()}</td><td>—</td><td>${num(m.quantity||m.qty).toLocaleString()}</td><td><label><input data-bo-master-print="${i}" type="checkbox" ${m.printed?'checked':''}> Printed Master Bag</label></td><td><div class="${m.printed?'':'hidden'}" data-master-art-wrap="${i}"><input data-bo-master-art="${i}" type="file" accept="image/*"><div class="metaText">${esc(m.artworkName||'No master marking uploaded')}</div>${m.artworkData?`<img class="artPreview" src="${esc(m.artworkData)}" alt="Master bag marking">`:''}</div></td></tr>`;return main+master}).join('');d.innerHTML=`<div class="section"><div class="toolbar"><div><h3>BAG ORDER</h3><div class="metaText">One white-paper PO for all bag sizes and any printed master bags.</div></div><div class="spacer"></div><button class="btn soft" id="newPODraft">Reset Draft</button></div><div class="grid3"><div class="field"><label>PO Number</label><input id="boNo" value="${esc(po.poNo)}"></div><div class="field"><label>Supplier</label><select id="boSupplier"><option value="">Select Supplier</option>${state.suppliers.map(x=>`<option ${po.supplier===x.name?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="btn small green" id="addSupplier">+ Supplier</button></div><div class="field"><label>Deliver To</label><input id="boDeliver" value="${esc(po.deliverTo)}"></div><div class="field"><label>Required Delivery Date</label><input id="boDate" type="date" value="${po.requiredDate||''}"></div></div><div class="tableWrap"><table class="table"><thead><tr><th>#</th><th>Brand</th><th>Tare G</th><th>BAG TYPE</th><th>BAG SIZE</th><th>Required</th><th>EMPTY BAGS</th><th>Total</th><th>Handle / Print</th><th>Marking</th></tr></thead><tbody>${rows}</tbody></table></div><div class="toolbar"><div class="notice">Changes to EMPTY BAGS apply only to this Bag Order and do not change the Sales Contract.</div><div class="spacer"></div><button class="btn green" id="generatePO">GENERATE ONE PO & SEND TO MILL</button></div></div>${s.bagOrders.length?`<div class="section"><h3>Issued POs</h3>${s.bagOrders.map((x,i)=>`<div class="notice"><b>${esc(x.poNo)}</b> · ${esc(x.supplier)} · ${x.lines.length} bag size(s) <button class="btn small soft" data-load-po="${i}">Update Same PO</button></div>`).join('')}</div>`:''}`;wireBagOrder()};

async function uploadBagArtwork(input,line,target){const file=input.files[0];if(!file)return;if(file.size>1536*1024){input.value='';throw new Error('Each bag marking file must be 1.5 MB or smaller.')}if(!file.type.startsWith('image/')){input.value='';throw new Error('Bag marking must be an image.')}input.disabled=true;try{const doc=await uploadDocument(file,target==='master'?'master-bag-marking':'bag-marking',shipment()),holder=target==='master'?line.masterBag:line;holder.artworkName=doc.name;holder.artworkDocument=doc;holder.artworkData=doc.downloadUrl||doc.dataUrl;holder.artworkAttached=true;if(target!=='master'){line.approved=true;line.approvedAt=new Date().toISOString()}save();renderShipmentWorkspace()}catch(error){input.disabled=false;input.value='';throw error}}
wireBagOrder=function(){const s=shipment(),po=ensureBagDraft();addSupplier.onclick=openSupplierModal;boNo.oninput=e=>po.poNo=e.target.value;boSupplier.onchange=e=>po.supplier=e.target.value;boDeliver.oninput=e=>po.deliverTo=e.target.value;boDate.onchange=e=>po.requiredDate=e.target.value;newPODraft.onclick=()=>{s.bagOrderDraft=null;save();renderShipmentWorkspace()};document.querySelectorAll('[data-bo-empty]').forEach(x=>x.oninput=e=>{const l=po.lines[num(x.dataset.boEmpty)];l.emptyBags=Math.max(0,Math.round(num(e.target.value)));l.totalBags=l.requiredBags+l.emptyBags;if(l.masterBag.enabled&&num(l.masterBag.bagsPerMaster)>0){l.masterBag.quantity=Math.ceil(l.totalBags/num(l.masterBag.bagsPerMaster));l.masterBag.qty=l.masterBag.quantity}document.querySelector(`[data-total-bags="${x.dataset.boEmpty}"]`).textContent=l.totalBags.toLocaleString()});document.querySelectorAll('[data-bo-handle]').forEach(x=>x.onchange=e=>po.lines[num(x.dataset.boHandle)].handle=e.target.value);document.querySelectorAll('[data-bo-master-print]').forEach(x=>x.onchange=e=>{const i=num(x.dataset.boMasterPrint),m=po.lines[i].masterBag;m.printed=e.target.checked;document.querySelector(`[data-master-art-wrap="${i}"]`)?.classList.toggle('hidden',!m.printed)});document.querySelectorAll('[data-bo-art]').forEach(x=>x.onchange=async()=>{try{await uploadBagArtwork(x,po.lines[num(x.dataset.boArt)],'main')}catch(e){alert(e.message)}});document.querySelectorAll('[data-bo-master-art]').forEach(x=>x.onchange=async()=>{try{await uploadBagArtwork(x,po.lines[num(x.dataset.boMasterArt)],'master')}catch(e){alert(e.message)}});generatePO.onclick=issuePO;document.querySelectorAll('[data-load-po]').forEach(x=>x.onclick=()=>{s.bagOrderDraft=structuredClone(s.bagOrders[num(x.dataset.loadPo)]);s.bagOrderDraft._updateIndex=num(x.dataset.loadPo);renderShipmentWorkspace()})};

issuePO=function(){const s=shipment(),po=ensureBagDraft();if(!contractByRef(s.contractRef).received)return alert('Mark the signed Sales Contract received before issuing the Bag Order.');if(!po.supplier)return alert('Select Supplier.');if(po.lines.some(l=>!l.artworkAttached))return alert('Upload the bag marking for every main bag size.');if(po.lines.some(l=>l.masterBag?.enabled&&l.masterBag.printed&&!l.masterBag.artworkAttached))return alert('Upload the marking for every printed Master Bag.');const out=structuredClone(po);out.issuedAt=new Date().toISOString();out.status='Synced to Mill';if(Number.isInteger(po._updateIndex)){out.poNo=s.bagOrders[po._updateIndex].poNo;s.bagOrders[po._updateIndex]=out}else s.bagOrders.push(out);state.millSync.newExportBags=state.millSync.newExportBags.filter(x=>!(x.contractRef===s.contractRef&&x.poNo===out.poNo));out.lines.forEach((l,i)=>state.millSync.newExportBags.push({contractRef:s.contractRef,poNo:out.poNo,supplier:out.supplier,deliverTo:out.deliverTo,requiredDate:out.requiredDate,line:i+1,brand:l.brand,type:l.type,size:l.size,unit:l.unit,orderedTare:l.tare,requiredBags:l.requiredBags,emptyBags:l.emptyBags,totalOrdered:l.totalBags,artworkName:l.artworkName,artworkData:l.artworkData,artworkDocument:l.artworkDocument||null,approved:true,handle:l.handle,masterBag:l.masterBag,status:'Order from Export — Awaiting Receipt'}));audit('BAG ORDER','Generated one white-paper PO and sent to Mill',s.contractRef+' · '+out.poNo);s.bagOrderDraft=null;directPrint('PURCHASE ORDER',purchaseOrderPrint(out),'without');renderShipmentWorkspace()};
purchaseOrderPrint=function(po){const rows=[];for(const [i,l] of po.lines.entries()){rows.push(`<tr><td>${i+1}</td><td>${esc(l.brand)}</td><td>${num(l.tare)} g</td><td>${esc(l.type)}</td><td>${num(l.size)} ${esc(l.unit)}</td><td>${num(l.requiredBags).toLocaleString()}</td><td>${num(l.emptyBags).toLocaleString()}</td><td>${num(l.totalBags).toLocaleString()}</td></tr>`);if(l.masterBag?.enabled)rows.push(`<tr><td>${i+1}.2</td><td>${esc(l.brand)} — MASTER BAG</td><td>${num(l.masterBag.tare)} g</td><td>MASTER BAG</td><td>${num(l.masterBag.bagsPerMaster)*num(l.size)} ${esc(l.unit)}</td><td>${num(l.masterBag.quantity||l.masterBag.qty).toLocaleString()}</td><td>—</td><td>${num(l.masterBag.quantity||l.masterBag.qty).toLocaleString()}</td></tr>`)}const art=[];for(const l of po.lines){if(l.artworkData)art.push(`<section class="docPage plainOrderPage"><h1>APPROVED BAG MARKING — ${esc(l.brand)}</h1><img class="poMarking" src="${esc(l.artworkData)}" alt="Bag marking"></section>`);if(l.masterBag?.printed&&l.masterBag.artworkData)art.push(`<section class="docPage plainOrderPage"><h1>APPROVED MASTER BAG MARKING — ${esc(l.brand)}</h1><img class="poMarking" src="${esc(l.masterBag.artworkData)}" alt="Master bag marking"></section>`)}return`<div class="printDoc"><section class="docPage plainOrderPage"><h1 class="docTitle">PURCHASE ORDER</h1><table class="docMeta"><tr><td class="lbl">PO Number</td><td>${esc(po.poNo)}</td><td class="lbl">Supplier</td><td>${esc(po.supplier)}</td></tr><tr><td class="lbl">Required Delivery</td><td>${po.requiredDate?fmt(po.requiredDate):'TO BE ADVISED LATER'}</td><td class="lbl">Deliver To</td><td>${esc(po.deliverTo)}</td></tr></table><table class="docTable"><thead><tr><th>#</th><th>Brand</th><th>Tare G</th><th>BAG TYPE</th><th>BAG SIZE</th><th>Required</th><th>EMPTY BAGS</th><th>Total</th></tr></thead><tbody>${rows.join('')}</tbody></table><div class="greenBox"><b>DELIVERY CHALLAN MUST CLEARLY MENTION THE BRAND NAME AND P.O. NUMBER.</b></div></section>${art.join('')}</div>`};

const renderBagOrderBeforeSequentialRows=renderBagOrder;
renderBagOrder=function(d){renderBagOrderBeforeSequentialRows(d);let sequence=1;d.querySelectorAll('tbody tr').forEach(row=>{const first=row.querySelector('td');if(first)first.textContent=String(sequence++)})};
